module asyn_fifo #(parameter WIDTH=8, DEPTH=16) (
    input wclk,
    input rclk,
    input wrstn,
    input rrstn,
    input winc,
    input rinc,
    input [WIDTH-1:0] wdata,
    output wfull,
    output rempty,
    output [WIDTH-1:0] rdata
);
    localparam ADDR_WIDTH = $clog2(DEPTH);
    localparam PTR_WIDTH = ADDR_WIDTH;

    reg [ADDR_WIDTH-1:0] waddr_bin, raddr_bin;
    reg [PTR_WIDTH-1:0] wptr, rptr, wptr_next, rptr_next;
    reg [PTR_WIDTH-1:0] rptr_sync1, rptr_sync2;
    reg [PTR_WIDTH-1:0] wptr_sync1, wptr_sync2;
    wire [PTR_WIDTH-1:0] rptr_syn = rptr_sync2;
    wire [PTR_WIDTH-1:0] wptr_syn = wptr_sync2;

    wire wenc = winc && !wfull;
    wire renc = rinc && !rempty;

    dual_port_RAM #(.WIDTH(WIDTH), .DEPTH(DEPTH)) ram (
        .wclk(wclk),
        .wenc(wenc),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(renc),
        .raddr(raddr_bin),
        .rdata(rdata)
    );

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
            wptr <= 0;
        end else begin
            waddr_bin <= waddr_bin + (winc && !wfull);
            wptr <= wptr_next;
        end
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
            rptr <= 0;
        end else begin
            raddr_bin <= raddr_bin + (rinc && !rempty);
            rptr <= rptr_next;
        end
    end

    assign wptr_next = (wptr >> 1) ^ wptr;
    assign rptr_next = (rptr >> 1) ^ rptr;

    always @(posedge wclk) begin
        rptr_sync1 <= rptr;
        rptr_sync2 <= rptr_sync1;
    end

    always @(posedge rclk) begin
        wptr_sync1 <= wptr;
        wptr_sync2 <= wptr_sync1;
    end

    assign full = (wptr_next == {~rptr_syn[ADDR_WIDTH-1], ~rptr_syn[ADDR_WIDTH-2], rptr_syn[ADDR_WIDTH-3:0]});
    assign empty = (rptr == wptr_syn);

    assign wfull = full;
    assign rempty = empty;
endmodule

module dual_port_RAM #(parameter WIDTH=8, DEPTH=16) (
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);
    reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

    always @(posedge wclk) begin
        if (wenc)
            RAM_MEM[waddr] <= wdata;
    end

    always @(posedge rclk) begin
        if (renc)
            rdata <= RAM_MEM[raddr];
    end
endmodule

