module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output data_out
);
    reg state;
    localparam IDLE = 0, PULSE1 = 1;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    state <= data_in ? PULSE1 : IDLE;
                end
                PULSE1: begin
                    state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

    assign data_out = (state == PULSE1) && (~data_in);

endmodule

