module traffic_light (
    input        rst_n,
    input        clk,
    input        pass_request,
    output [7:0] clock,
    output       red,
    output       yellow,
    output       green
);
    parameter [1:0] idle     = 2'b00,
                    s1_red   = 2'b01,
                    s2_yellow= 2'b10,
                    s3_green = 2'b11;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;
    reg red_next, yellow_next, green_next;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin
            if (pass_request && green) begin
                cnt <= 8'd10;
            end else if (p_green && !green) begin
                cnt <= 8'd60;
            end else if (p_yellow && !yellow) begin
                cnt <= 8'd5;
            end else if (p_red && !red) begin
                cnt <= 8'd10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle:    state <= s1_red;
                s1_red:  if (cnt == 0) state <= s3_green else state <= s1_red;
                s3_green:if (cnt == 0) state <= s2_yellow else state <= s3_green;
                s2_yellow:if (cnt == 0) state <= s1_red else state <= s2_yellow;
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
        end
    end


    always @(*) begin
        case (state)
            idle:    {red_next, yellow_next, green_next} = 3'b000;
            s1_red:  {red_next, yellow_next, green_next} = 3'b100;
            s3_green: {red_next, yellow_next, green_next} = 3'b001;
            s2_yellow:{red_next, yellow_next, green_next} = 3'b010;
            default: {red_next, yellow_next, green_next} = 3'b000;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            red <= red_next;
            yellow <= yellow_next;
            green <= green_next;
        end
    end

    assign clock = cnt;
endmodule

