parameter SRL = 6'b000010;
parameter SRA = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI = 6'b001111;

reg [31:0] res;
reg signed [31:0] a_signed, b_signed;
wire [32:0] temp_sum, temp_diff;

assign a_signed = a;
assign b_signed = b;

always @* begin
    res = 32'bz;

    carry = 0;
    overflow = 0;
    case (aluc)
        ADD: begin
            temp_sum = {1'b0, a} + {1'b0, b};
            res = temp_sum[31:0];
            carry = temp_sum[32];
            overflow = (a_signed[31] == b_signed[31]) && (res[31] != a_signed[31]);
        end
        ADDU: begin
            res = a + b;
            temp_sum = {1'b0, a} + {1'b0, b};
            carry = temp_sum[32];
            overflow = 0;
        end
        SUB: begin
            temp_diff = {1'b0, a} - {1'b0, b};
            res = temp_diff[31:0];
            carry = ~temp_diff[32];
            overflow = (a_signed[31] != b_signed[31]) && (res[31] != a_signed[31]);
        end
        SUBU: begin
            res = a - b;
            temp_diff = {1'b0, a} - {1'b0, b};
            carry = ~temp_diff[32];
            overflow = 0;
        end
        AND: res = a & b;
        OR: res = a | b;
        XOR: res = a ^ b;
        NOR: res = ~(a | b);
        SLT: res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
        SLTU: res = (a < b) ? 32'd1 : 32'd0;
        SLL: res = b << a[4:0];
        SRL: res = b >> a[4:0];
        SRA: res = $signed(b) >>> a[4:0];
        SLLV: res = b << a[4:0];
        SRLV: res = b >> a[4:0];
        SRAV: res = $signed(b) >>> a[4:0];
        LUI: res = {a[31:16], 16'b0};
        default: res = 32'bz;
    endcase
end

assign zero = (res == 32'b0);
assign negative = res[31];
assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;

assign r = res;

endmodule

