module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] saved_dividend, saved_divisor;
    reg [7:0] abs_dividend, abs_divisor;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [8:0] NEG_DIVISOR;
    reg sign_quotient, sign_remainder;
    reg [7:0] quotient_abs, remainder_abs;
    reg [1:0] state;

    localparam IDLE = 2'b00, RUN = 2'b01, DONE = 2'b10;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            result <= 0;
            saved_dividend <= 0;
            saved_divisor <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            NEG_DIVISOR <= 0;
            quotient_abs <= 0;
            remainder_abs <= 0;
            sign_quotient <= 0;
            sign_remainder <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (opn_valid && !res_valid) begin
                        saved_dividend <= dividend;
                        saved_divisor <= divisor;
                        abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                        abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                        NEG_DIVISOR <= {1'b0, ~(abs_divisor)} + 1;
                        SR <= {8'b0, abs_dividend} << 1;
                        cnt <= 4'd1;
                        start_cnt <= 1'b1;
                        state <= RUN;
                        res_valid <= 0;
                    end
                end
                RUN: begin
                    if (start_cnt) begin
                        if (cnt < 8) begin
                            automatic logic [8:0] temp_remainder = {1'b0, SR[15:8]} - NEG_DIVISOR;
                            automatic logic carry_out = temp_remainder[8];
                            automatic logic [7:0] q_bit = carry_out ? 1'b1 : 1'b0;
                            quotient_abs <= {quotient_abs[6:0], q_bit};
                            remainder_abs <= carry_out ? temp_remainder[7:0] : SR[15:8];
                            SR <= {carry_out ? temp_remainder[7:0] : SR[15:8], SR[7:1]};
                            cnt <= cnt + 1;
                        end else begin
                            state <= DONE;
                            start_cnt <= 0;
                        end
                    end
                end
                DONE: begin
                    sign_quotient <= (saved_dividend[7] ^ saved_divisor[7]) && sign;
                    sign_remainder <= saved_dividend[7] && sign;
                    if (sign) begin
                        result[7:0] <= sign_quotient ? (~quotient_abs + 1) : quotient_abs;
                        result[15:8] <= sign_remainder ? (~remainder_abs + 1) : remainder_abs;
                    end else begin
                        result <= {remainder_abs, quotient_abs};
                    end
                    res_valid <= 1'b1;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

