module cla_16bit (
    input [16:1] A,
    input [16:1] B,
    input Cin,
    output [16:1] S,
    output G,
    output P,
    output Cout
);
    wire [15:0] P_i, G_i;
    wire [16:0] C;
    integer i, j;

    assign C[0] = Cin;

    generate
        for (i = 1;
 i <= 16;
 i = i + 1) begin: gen_carries
            assign P_i[i-1] = A[i] ^ B[i];
            assign G_i[i-1] = A[i] & B[i];
            assign C[i] = G_i[i-1] | (P_i[i-1] & C[i-1]);
        end
    endgenerate


    reg [15:0] G_terms;
    always @(*) begin
        G_terms[0] = G_i[0];
        for (j = 1;
 j < 16;
 j = j + 1)
            G_terms[j] = G_i[j] | (P_i[j-1] & G_terms[j-1]);
    end
    assign G = G_terms[15];
    assign P = &P_i;


    for (i = 1;
 i <= 16;
 i = i + 1)
        assign S[i] = P_i[i-1] ^ C[i-1];

    assign Cout = C[16];
