reg [2:0] count;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        accumulator <= 10'b0;
        count <= 3'b0;
        valid_out <= 1'b0;
        data_out <= 10'b0;
    end else begin
        valid_out <= 1'b0;
        if (valid_in) begin
            accumulator <= accumulator + data_in;
            count <= count + 1;
            if (count == 3) begin
                valid_out <= 1'b1;
                data_out <= accumulator + data_in;
                count <= 3'b0;
                accumulator <= 10'b0;
            end
        end
    end
end

endmodule

