module fixed_point_subtractor #(parameter Q=2, N=4) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);
reg [N-1:0] res;
wire [N-1:0] absolute_a, absolute_b;
wire same_sign, a_sign, b_sign;

assign a_sign = a[N-1];
assign b_sign = b[N-1];
assign same_sign = (a_sign == b_sign);

assign absolute_a = a_sign ? (~a + 1) : a;
assign absolute_b = b_sign ? (~b + 1) : b;

always @* begin
    if (same_sign) begin
        res = a - b;
        if (res == 0)
            res = 0;
    end else begin
        if (a_sign && !b_sign) begin
            res = absolute_a + absolute_b;
            res[N-1] = 1'b1;
        end else begin
            if (a > absolute_b)
                res = a - absolute_b;
            else
                res = absolute_b - a;
            res[N-1] = (a > absolute_b) ? 1'b0 : 1'b1;
        end
    end
end

assign c = res;

endmodule

