module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [47:0] product;
    reg [4:0] guard, round, sticky;
    reg [23:0] rounded_mantissa;
    reg shift_flag;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'd0;
        end else begin
            case (counter)
                3'b000: begin 
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};
                    counter <= 3'b001;
                end

                3'b001: begin 
                    if ((a_exponent == 8'hff && |a_mantissa) || (b_exponent == 8'hff && |b_mantissa)) begin
                        z <= 32'h7fc00000;

                        counter <= 3'b111;
                    end else if (a_exponent == 8'hff) begin 
                        if (b_exponent == 8'hff) begin
                            z <= 32'h7fc00000;

                        end else begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'd0};

                        end
                        counter <= 3'b111;
                    end else if (b_exponent == 8'hff) begin 
                        z <= {a_sign ^ b_sign, 8'hff, 23'd0};

                        counter <= 3'b111;
                    end else if (a_exponent == 0 && a_mantissa == 0) begin 
                        if (b_exponent == 0 && b_mantissa == 0) begin
                            z <= 32'h7fc00000;

                        end else begin
                            z <= 32'd0;
                        end
                        counter <= 3'b111;
                    end else if (b_exponent == 0 && b_mantissa == 0) begin 
                        z <= 32'd0;
                        counter <= 3'b111;
                    end else begin
                        product <= a_mantissa * b_mantissa;
                        counter <= 3'b010;
                    end
                end

                3'b010: begin 
                    shift_flag <= product[47];
                    z_exponent <= a_exponent + b_exponent - 8'd127;
                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 8'd1;
                    end
                    counter <= 3'b011;
                end

                3'b011: begin 
                    guard <= product[23 + (shift_flag ? 0 : 1)];
                    round <= product[22 + (shift_flag ? 0 : 1)];
                    sticky <= |product[21:0 + (shift_flag ? 0 : 1)];
                    counter <= 3'b100;
                end

                3'b100: begin 
                    rounded_mantissa = shift_flag ? product[46:23] : product[47:24];
                    if (guard && (round || sticky || rounded_mantissa[0])) begin
                        rounded_mantissa = rounded_mantissa + 1;
                    end
                    counter <= 3'b101;
                end

                3'b101: begin 
                    if (rounded_mantissa[23]) begin
                        z_mantissa <= {1'b1, rounded_mantissa[23:1]};
                        z_exponent <= z_exponent + 8'd1;
                    end else begin
                        z_mantissa <= rounded_mantissa[23:1];
                    end
                    counter <= 3'b110;
                end

                3'b110: begin 
                    if (z_exponent >= 255) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'd0};
                    end else if (z_exponent == 0) begin
                        z <= {a_sign ^ b_sign, 23'd0, 1'b0};
                    end else begin
                        z <= {a_sign ^ b_sign, z_exponent, z_mantissa[22:0]};
                    end
                    counter <= 3'b111;
                end

                default: begin
                    counter <= 3'b111;
                end
            endcase
        end
    end

endmodule

