        if (!rst_n) begin
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: begin
                    p_red <= 1;
                    if (cnt == 3) state <= s3_green;
