module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] dividend_reg, divisor_reg;
    reg sign_dividend, sign_divisor, sign_quotient;
    reg [7:0] abs_dividend, abs_divisor;
    reg [8:0] NEG_DIVISOR;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            start_cnt <= 0;
            cnt <= 0;
            dividend_reg <= 0;
            divisor_reg <= 0;
            sign_dividend <= 0;
            sign_divisor <= 0;
            sign_quotient <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            NEG_DIVISOR <= 0;
            SR <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                dividend_reg <= dividend;
                divisor_reg <= divisor;
                sign_dividend <= sign && dividend[7];
                sign_divisor <= sign && divisor[7];
                sign_quotient <= sign && (dividend[7] ^ divisor[7]);


                abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                NEG_DIVISOR <= -abs_divisor;


                SR <= {abs_dividend, 8'b0} << 1;
                start_cnt <= 1;
                cnt <= 4'd1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt < 8) begin

                    wire [8:0] temp_sub = {1'b0, SR[15:8]} + {1'b0, abs_divisor};
                    wire carry_out = temp_sub[8];
                    reg [7:0] new_remainder, new_quotient;

                    new_remainder = carry_out ? temp_sub[7:0] : SR[15:8];
                    new_quotient = (SR[7:0] << 1) | carry_out;
                    SR <= {new_remainder, new_quotient};
                    cnt <= cnt + 1;
                end else begin

                    reg [7:0] quotient, remainder;
                    quotient = SR[7:0];
                    remainder = SR[15:8];

                    if (sign) begin
                        if (sign_quotient)
                            quotient = -quotient;
                        if (sign_dividend)
                            remainder = -remainder;
                    end
                    result <= {remainder, quotient};
                    res_valid <= 1;
                    start_cnt <= 0;
                    cnt <= 0;
                end
            end
        end
    end

endmodule

