    input [4:1] A,
    input [4:1] B,
    input Cin,
    output [4:1] S,
    output P_4,
    output G_4,
    output Cout
);
    wire [4:1] G, P;
    wire C1, C2, C3;


    assign G[1] = A[1] & B[1];
    assign P[1] = A[1] ^ B[1];
    assign G[2] = A[2] & B[2];
    assign P[2] = A[2] ^ B[2];
    assign G[3] = A[3] & B[3];
    assign P[3] = A[3] ^ B[3];
    assign G[4] = A[4] & B[4];
    assign P[4] = A[4] ^ B[4];


    assign P_4 = P[1] & P[2] & P[3] & P[4];
    assign G_4 = G[4] | (P[4] & G[3]) | (P[4] & P[3] & G[2]) | (P[4] & P[3] & P[2] & G[1]);


    assign C1 = G[1] | (P[1] & Cin);
    assign C2 = G[2] | (P[2] & G[1]) | (P[2] & P[1] & Cin);
    assign C3 = G[3] | (P[3] & G[2]) | (P[3] & P[2] & G[1]) | (P[3] & P[2] & P[1] & Cin);
    assign Cout = G[4] | (P[4] & G[3]) | (P[4] & P[3] & G[2]) | (P[4] & P[3] & P[2] & G[1]) | (P[4] & P[3] & P[2] & P[1] & Cin);


    assign S[1] = P[1] ^ Cin;
    assign S[2] = P[2] ^ C1;
    assign S[3] = P[3] ^ C2;
    assign S[4] = P[4] ^ C3;
endmodule

module cla_16bit (
    input [16:1] A,
    input [16:1] B,
    input Cin,
    output [16:1] S,
    output P_16,
    output G_16,
    output Cout
);
    wire P1, G1, Cout1;
    wire P2, G2, Cout2;
    wire P3, G3, Cout3;
    wire P4, G4, Cout4;

    cla_4bit cla1 (
        .A(A[4:1]),
        .B(B[4:1]),
        .Cin(Cin),
        .S(S[4:1]),
        .P_4(P1),
        .G_4(G1),
        .Cout(Cout1)
    );

    cla_4bit cla2 (
        .A(A[8:5]),
        .B(B[8:5]),
        .Cin(Cout1),
        .S(S[8:5]),
        .P_4(P2),
        .G_4(G2),
        .Cout(Cout2)
    );

    cla_4bit cla3 (
        .A(A[12:9]),
        .B(B[12:9]),
        .Cin(Cout2),
        .S(S[12:9]),
        .P_4(P3),
        .G_4(G3),
        .Cout(Cout3)
    );

    cla_4bit cla4 (
        .A(A[16:13]),
        .B(B[16:13]),
        .Cin(Cout3),
        .S(S[16:13]),
        .P_4(P4),
        .G_4(G4),
        .Cout(Cout4)
    );

    assign P_16 = P1 & P2 & P3 & P4;
    assign G_16 = G4 | (P4 & G3) | (P4 & P3 & G2) | (P4 & P3 & P2 & G1) | (P4 & P3 & P2 & P1 & Cin);
    assign Cout = G_16 | (P_16 & Cin);
endmodule

module adder_32bit (
    input [32:1] A,
    input [32:1] B,
    output [32:1] S,
    output C32
);
    wire C16;
    wire P1, G1, P2, G2;

    cla_16bit cla1 (
        .A(A[16:1]),
        .B(B[16:1]),
        .Cin(1'b0),
        .S(S[16:1]),
        .P_16(P1),
        .G_16(G1),
        .Cout(C16)
    );

    cla_16bit cla2 (
        .A(A[32:17]),
        .B(B[32:17]),
        .Cin(C16),
        .S(S[32:17]),
        .P_16(P2),
        .G_16(G2),
        .Cout(C32)
    );

    assign C32 = G2 | (P2 & G1);
endmodule

