module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output reg [9:0] data_out
);
    reg [1:0] counter;

    reg [9:0] accumulator;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            accumulator <= 10'b0;
            counter <= 2'b0;
            valid_out <= 1'b0;
            data_out <= 10'b0;
        end else begin
            valid_out <= 1'b0;

            if (valid_in) begin

                accumulator <= accumulator + data_in;
                counter <= counter + 1;

                if (counter == 2'd3) begin
                    data_out <= accumulator + data_in;

                    valid_out <= 1'b1;

                    accumulator <= 10'b0;
                    counter <= 2'b0;
                end
            end
        end
    end
endmodule

