module fixed_point_adder #(parameter Q=2, parameter N=4) (
    input [N-1:0] a, b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire a_msb = a[N-1];
    wire b_msb = b[N-1];
    reg [N-1:0] absolute_a, absolute_b;
    reg signed [N-1:0] a_signed, b_signed;

    always @* begin
        if (a_msb == b_msb) begin

            absolute_a = a_msb ? (-a) : a;
            absolute_b = b_msb ? (-b) : b;
            res = absolute_a + absolute_b;
        end else begin

            a_signed = $signed(a);
            b_signed = $signed(b);
            if (a_signed > b_signed)
                res = a_signed - b_signed;
            else
                res = b_signed - a_signed;
        end
        c = res;
    end
endmodule

