module fixed_point_subtractor #(parameter Q=4, N=8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire [N-2:0] a_mag = a[N-2:0];
    wire [N-2:0] b_mag = b[N-2:0];
    reg res_sign;
    reg [N-2:0] res_mag;

    always @(*) begin
        if (sign_a == sign_b) begin

            if (a_mag >= b_mag) begin
                res_sign = sign_a;
                res_mag = a_mag - b_mag;
            end else begin
                res_sign = sign_a;
                res_mag = b_mag - a_mag;
            end
        end else begin

            if (a_mag > b_mag) begin
                res_sign = 0;
                res_mag = a_mag + b_mag;
            end else begin
                res_sign = 1;
                res_mag = a_mag + b_mag;
            end
        end


        if (res_mag == {N-2{1'b0}}) begin
            res_sign = 0;
        end

        res = {res_sign, res_mag};
        c = res;
    end

endmodule

