module float_multi(
    input               clk,
    input               rst,
    input  [31:0]       a,
    input  [31:0]       b,
    output reg [31:0]   z
);
    reg [2:0]           counter;
    reg                 a_sign, b_sign, z_sign;
    reg [9:0]           a_exponent, b_exponent, z_exponent;
    reg [23:0]          a_mantissa, b_mantissa, z_mantissa;
    reg [49:0]          product;
    reg                 guard, round, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b000: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= {2'b00, a[30:23]};
                    b_exponent <= {2'b00, b[30:23]};
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};

                    if (a[30:23] == 8'hff || b[30:23] == 8'hff) begin

                        if ((a[30:23] == 8'hff && a[22:0] != 0) || (b[30:23] == 8'hff && b[22:0] != 0)) begin
                            z <= {a[31] ^ b[31], 8'hff, 1'b1, 22'b0};
                        end else if (a[30:23] == 8'hff && b[30:23] == 8'hff) begin
                            z <= {a[31] ^ b[31], 8'hff, 23'b0};
                        end else begin
                            z <= {a[31] ^ b[31], 8'h0, 23'b0};
                        end
                        counter <= 3'b111;
                    end else if (a[30:23] == 8'h0 && a[22:0] == 0 && b[30:23] == 8'h0 && b[22:0] == 0) begin

                        z <= {a[31] ^ b[31], 8'b0, 23'b0};
                        counter <= 3'b111;
                    end else begin
                        product <= a_mantissa * b_mantissa;
                        counter <= 3'b001;
                    end
                end
                3'b001: begin

                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= a_exponent + b_exponent - 10'd254 + 10'd1;
                    end else begin
                        z_exponent <= a_exponent + b_exponent - 10'd254;
                    end
                    guard <= product[22];
                    round <= product[21];
                    sticky <= |product[20:0];
                    counter <= 3'b010;
                end
                3'b010: begin

                    if ((guard && (round || sticky)) || (guard && !round && !sticky && product[23])) begin
                        if (product[23:1] == 24'hffffff) begin
                            z_mantissa <= 23'b0;
                            z_exponent <= z_exponent + 1;
                        end else begin
                            z_mantissa <= product[23:1] + 1;
                        end
                    end else begin
                        z_mantissa <= product[23:1];
                    end
                    counter <= 3'b011;
                end
                3'b011: begin

                    if (z_exponent[9]) begin

                        z <= {z_sign, 8'hff, 23'b0};
                    end else if (z_exponent == 0) begin

                        z <= {z_sign, 8'b0, z_mantissa};
                    end else begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa};
                    end
                    counter <= 3'b100;
                end
                default: counter <= 3'b0;
            endcase
        end
    end
endmodule

