module fsm (IN, CLK, RST, MATCH);
input IN, CLK, RST;
output reg MATCH;


parameter S_IDLE  = 3'b000;
parameter S_1     = 3'b001;
parameter S_10    = 3'b010;
parameter S_100   = 3'b011;
parameter S_1001  = 3'b100;
parameter S_10011 = 3'b101;

reg [2:0] current_state, next_state;


always @(posedge CLK or posedge RST) begin
    if (RST)
        current_state <= S_IDLE;
    else
        current_state <= next_state;
end


always @(*) begin
    case (current_state)
        S_IDLE:  next_state = IN ? S_1     : S_IDLE;
        S_1:     next_state = IN ? S_1     : S_10;
        S_10:    next_state = IN ? S_1     : S_100;
        S_100:   next_state = IN ? S_1001  : S_100;
        S_1001:  next_state = IN ? S_10011 : S_1001;
        S_10011: next_state = IN ? S_1     : S_IDLE;
        default: next_state = S_IDLE;
    endcase
end


always @(*) begin
    MATCH = RST ? 1'b0 : ( (current_state == S_1001 && IN) || (current_state == S_10011 && IN) );
end

endmodule

