        .DEPTH(DEPTH),
        .WIDTH(WIDTH)
    ) ram (
        .wclk(wclk),
        .wenc(wenc),
        .waddr(waddr),
        .wdata(wdata),
        .rclk(rclk),
        .renc(renc),
        .raddr(raddr),
        .rdata(rdata)
    );


    reg [$clog2(DEPTH)-1:0] waddr_bin, raddr_bin;
    wire [$clog2(DEPTH)-1:0] waddr = waddr_bin;
    wire [$clog2(DEPTH)-1:0] raddr = raddr_bin;


    reg [3:0] wptr, rptr;
    wire [3:0] wptr_next = waddr_bin ^ (waddr_bin >> 1);
    wire [3:0] rptr_next = raddr_bin ^ (raddr_bin >> 1);


    reg [3:0] rptr_sync1, rptr_sync2;
    reg [3:0] wptr_sync1, wptr_sync2;


    always @(posedge wclk or negedge wrstn) begin
        if (~wrstn) begin
            waddr_bin <= 0;
            wptr <= 0;
            rptr_sync1 <= 0;
            rptr_sync2 <= 0;
        end else begin
            if (winc && !wfull)
                waddr_bin <= waddr_bin + 1;
            wptr <= wptr_next;
            rptr_sync1 <= rptr;
            rptr_sync2 <= rptr_sync1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (~rrstn) begin
            raddr_bin <= 0;
            rptr <= 0;
            wptr_sync1 <= 0;
            wptr_sync2 <= 0;
        end else begin
            if (rinc && !rempty)
                raddr_bin <= raddr_bin + 1;
            rptr <= rptr_next;
            wptr_sync1 <= wptr;
            wptr_sync2 <= wptr_sync1;
        end
    end


    wire [3:0] rptr_syn = rptr_sync2;
    wire [3:0] wptr_syn = wptr_sync2;
    assign rempty = (rptr == wptr_syn);
    assign wfull = (wptr == {~rptr_syn[3:2], rptr_syn[1:0]});


    wire wenc = winc && !wfull;
    wire renc = rinc && !rempty;
