module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] SP;


always @(posedge Clk) begin
    if (Rst) begin

        stack_mem[0] <= 4'b0;
        stack_mem[1] <= 4'b0;
        stack_mem[2] <= 4'b0;
        stack_mem[3] <= 4'b0;
        SP <= 3'd4;

        dataOut <= 4'b0;
    end else if (EN) begin
        if (!RW) begin 
            if (!FULL) begin
                stack_mem[SP - 3'd1] <= dataIn;
                SP <= SP - 3'd1;
            end
        end else begin 
            if (!EMPTY) begin
                dataOut <= stack_mem[SP];
                stack_mem[SP] <= 4'b0;
                SP <= SP + 3'd1;
            end
        end
    end
end


always @(*) begin
    EMPTY = (SP == 3'd4);
    FULL = (SP == 3'd0);
end

endmodule

