module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);
    reg state;
    localparam IDLE = 1'b0;
    localparam WAITING_FOR_FALL = 1'b1;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= IDLE;
            data_out <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (data_in) begin
                        state <= WAITING_FOR_FALL;
                    end
                    data_out <= 1'b0;
                end
                WAITING_FOR_FALL: begin
                    if (~data_in) begin
                        data_out <= 1'b1;
                        state <= IDLE;
                    end else begin
                        state <= IDLE;
                    end
                end
            endcase
        end
    end

endmodule

