module alu (
    input [31:0] a, b,
    input [5:0] aluc,
    output reg [31:0] r,
    output reg zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output reg flag
);
    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg [32:0] res;

    reg [31:0] temp_r;
    reg temp_zero, temp_negative, temp_overflow, temp_carry;
    reg temp_flag;

    always @* begin
        res = 33'b0;
        temp_r = 32'b0;
        temp_zero = 1'b0;
        temp_negative = 1'b0;
        temp_overflow = 1'b0;
        temp_carry = 1'b0;
        temp_flag = 1'bz;

        case(aluc)
            ADD: begin
                res = {a[31], a} + {b[31], b};

                temp_r = res[31:0];
                temp_negative = temp_r[31];
                temp_overflow = (a[31] == b[31]) && (temp_r[31] != a[31]);
                temp_carry = res[32];
            end
            ADDU: begin
                res = a + b;
                temp_r = res[31:0];
                temp_carry = res[32];
            end
            SUB: begin
                res = {a[31], a} - {b[31], b};
                temp_r = res[31:0];
                temp_negative = temp_r[31];
                temp_overflow = (a[31] != b[31]) && (temp_r[31] != a[31]);

                temp_carry = (a >= b) ? 1'b1 : 1'b0;
            end
            SUBU: begin
                res = a - b;
                temp_r = res[31:0];

                temp_carry = (a >= b) ? 1'b1 : 1'b0;
            end
            AND: begin
                temp_r = a & b;
            end
            OR: begin
                temp_r = a | b;
            end
            XOR: begin
                temp_r = a ^ b;
            end
            NOR: begin
                temp_r = ~(a | b);
            end
            SLT: begin
                temp_r = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
            end
            SLTU: begin
                temp_r = (a < b) ? 32'd1 : 32'd0;
            end
            SLL: begin
                temp_r = b << a[4:0];
            end
            SRL: begin
                temp_r = b >> a[4:0];
            end
            SRA: begin
                temp_r = $signed(b) >>> a[4:0];
            end
            SLLV: begin
                temp_r = b << a[4:0];
            end
            SRLV: begin
                temp_r = b >> a[4:0];
            end
            SRAV: begin
                temp_r = $signed(b) >>> a[4:0];
            end
            LUI: begin
                temp_r = {a[15:0], 16'b0};
            end
            default: begin
                temp_r = 32'bz;
            end
        endcase

        temp_zero = (temp_r == 32'b0);
        temp_negative = temp_r[31];


        r = temp_r;
        zero = temp_zero;
        negative = temp_negative;
        overflow = temp_overflow;
        carry = temp_carry;


        if (aluc == SLT) begin
            temp_flag = ($signed(a) < $signed(b));
        end else if (aluc == SLTU) begin
            temp_flag = (a < b);
        end else begin
            temp_flag = 1'bz;
        end
        flag = temp_flag;
    end
endmodule

