                        sign_dividend <= dividend[7];
                        sign_divisor <= divisor[7];
                        if (sign) begin
                            dividend_abs <= (dividend[7]) ? (~dividend + 1) : dividend;
                            divisor_abs <= (divisor[7]) ? (~divisor + 1) : divisor;
                        end else begin
                            dividend_abs <= dividend;
                            divisor_abs <= divisor;
                        end

                        sr <= { (sign_dividend ? (~dividend + 1) : dividend) << 1, 8'b0 };
                        cnt <= 4'd0;
                        state <= PROCESSING;
                        res_valid <= 0;
                    end
                end
                PROCESSING: begin
                    if (cnt < 8) begin

                        reg [8:0] temp_remainder;
                        reg [7:0] temp_quotient;
                        reg [8:0] subtract_result;
                        reg carry_out;

                        temp_remainder = sr[16:8] << 1;
                        temp_remainder = temp_remainder | (sr[7] ? 1 : 0);
                        temp_quotient = sr[7:0] << 1;

                        subtract_result = temp_remainder - divisor_abs;
                        carry_out = (temp_remainder < divisor_abs);

                        if (!carry_out) begin
                            temp_remainder = subtract_result;
                            temp_quotient = temp_quotient | 1;
                        end

                        sr <= { temp_remainder, temp_quotient };
                        cnt <= cnt + 1;
                    end else begin

                        state <= DONE;
                        res_valid <= 1;
                    end
                end
                DONE: begin

                    reg [7:0] final_quotient;
                    reg [8:0] final_remainder;

                    final_remainder = sr[16:8];
                    final_quotient = sr[7:0];

                    if (sign) begin

                        if (sign_dividend ^ sign_divisor) begin
                            final_quotient = ~final_quotient + 1;
                        end
                        if (sign_dividend) begin
                            final_remainder = ~final_remainder + 1;
                        end
                    end


                    result <= { final_remainder[7:0], final_quotient };
                    res_valid <= 1;


                    if (opn_valid && !res_valid) begin
                        state <= IDLE;
                        res_valid <= 0;
                    end
                end
            endcase
        end
    end

endmodule

