module fixed_point_adder #(parameter Q=4, N=8) (
    input [N-1:0] a, b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a, sign_b;
    wire [N-1:0] a_abs, b_abs;
    reg [N-1:0] res_abs;

    assign sign_a = a[N-1];
    assign sign_b = b[N-1];
    assign a_abs = sign_a ? (~a + 1) : a;
    assign b_abs = sign_b ? (~b + 1) : b;

    always @(*) begin
        if (sign_a == sign_b) begin
            res = a_abs + b_abs;
            res[N-1] = sign_a;
        end else begin
            if (a_abs > b_abs) begin
                res_abs = a_abs - b_abs;
                res[N-1] = 0;
            end else if (b_abs > a_abs) begin
                res_abs = b_abs - a_abs;
                res[N-1] = 1;
            end else begin
                res_abs = 0;
                res[N-1] = 0;
            end
            res[N-2:0] = res_abs[N-1:0];
        end
        c = res;
    end

endmodule

