module float_multi (
    input wire clk,
    input wire rst,
    input wire [31:0] a,
    input wire [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, initial_exp, z_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [49:0] product;

    reg guard_bit, round_bit, sticky;
    reg a_zero, b_zero, a_inf, b_inf, a_nan, b_nan, z_nan, z_inf;
    reg [23:0] z_mantissa;
    reg overflow, underflow;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 0;
            b_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            initial_exp <= 0;
            z_exponent <= 0;
            product <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
            a_zero <= 0;
            b_zero <= 0;
            a_inf <= 0;
            b_inf <= 0;
            a_nan <= 0;
            b_nan <= 0;
            z_nan <= 0;
            z_inf <= 0;
            z_mantissa <= 0;
            overflow <= 0;
            underflow <= 0;
        end else begin
            case (counter)
                3'b000: begin 
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    a_zero <= (a[30:23] == 0) && (a[22:0] == 0);
                    b_zero <= (b[30:23] == 0) && (b[22:0] == 0);
                    a_inf <= (a[30:23] == 8'hFF) && (a[22:0] == 0);
                    b_inf <= (b[30:23] == 8'hFF) && (b[22:0] == 0);
                    a_nan <= (a[30:23] == 8'hFF) && (a[22:0] != 0);
                    b_nan <= (b[30:23] == 8'hFF) && (b[22:0] != 0);
                    z_nan <= a_nan || b_nan;
                    z_inf <= (a_inf && b_zero) || (b_inf && a_zero) || (a_inf && b_inf);
                    initial_exp <= a_exponent + b_exponent - 9'd127;
                    counter <= counter + 1;
                end
                3'b001: begin 
                    product <= a_mantissa * b_mantissa;
                    if (a_zero || b_zero) begin
                        z_sign <= a_sign ^ b_sign;
                        z <= {z_sign, 31'b0};
                        counter <= 3'b111;
                    end else if (z_nan) begin
                        z <= 32'h7FC00000;
                        counter <= 3'b111;
                    end else if (z_inf) begin
                        z <= {z_sign, 8'hFF, 23'b0};
                        counter <= 3'b111;
                    end else begin
                        counter <= counter + 1;
                    end
                end
                3'b010: begin 
                    if (product[47] || product[46]) begin
                        product <= product >> 1;
                        z_exponent <= initial_exp + 1;
                    end else begin
                        z_exponent <= initial_exp;
                    end
                    z_mantissa <= product[46:23];

                    guard_bit <= product[22];
                    round_bit <= product[21];
                    sticky <= |product[20:0];
                    counter <= counter + 1;
                end
                3'b011: begin 
                    if (guard_bit && (round_bit || sticky)) begin
                        z_mantissa <= z_mantissa + 1;
                    end
                    if (z_mantissa[23]) begin 
                        z_mantissa <= z_mantissa >> 1;
                        z_exponent <= z_exponent + 1;
                    end
                    counter <= counter + 1;
                end
                3'b100: begin 
                    if (z_exponent >= 8'hFF) begin
                        z <= {z_sign, 8'hFF, 23'b0};

                        overflow <= 1;
                    end else if (z_exponent == 0) begin
                        underflow <= 1;

                    end else begin
                        z <= {z_sign, z_exponent, z_mantissa[22:0]};
                    end
                    counter <= 3'b0;
                end
                default: begin
                    z <= {z_sign, z_exponent, z_mantissa[22:0]};
                    counter <= 3'b0;
                end
            endcase
        end
    end
endmodule

