                next_state = S1;
            else
                next_state = S3;
        end
        S3: next_state = (data_in) ? S4 : IDLE;
        S4: next_state = IDLE;
        default: next_state = IDLE;
    endcase
end


assign sequence_detected = (next_state == S4);

