module asyn_fifo #(
  parameter WIDTH = 8,
  parameter DEPTH = 16
) (
  input wire wclk,
  input wire wrstn,
  input wire winc,
  input wire [WIDTH-1:0] wdata,
  output wire wfull,
  output wire rempty,
  input wire rclk,
  input wire rrstn,
  input wire rinc,
  output wire [WIDTH-1:0] rdata
);
  localparam ADDR_WIDTH = $clog2(DEPTH);

  reg [ADDR_WIDTH-1:0] waddr_bin, raddr_bin;
  reg [ADDR_WIDTH-1:0] wptr_gray, rptr_gray;
  wire [ADDR_WIDTH-1:0] next_wptr_gray, next_rptr_gray;
  reg [ADDR_WIDTH-1:0] wptr_gray_sync_0, wptr_gray_sync;
  reg [ADDR_WIDTH-1:0] rptr_gray_sync_0, rptr_gray_sync;


  always @(posedge wclk or negedge wrstn) begin
    if (~wrstn) begin
      waddr_bin <= 0;
      wptr_gray <= 0;
    end else begin
      if (winc && !wfull) begin
        waddr_bin <= waddr_bin + 1;
        wptr_gray <= next_wptr_gray;
      end
    end
  end


  always @(posedge rclk or negedge rrstn) begin
    if (~rrstn) begin
      raddr_bin <= 0;
      rptr_gray <= 0;
    end else begin
      if (rinc && !rempty) begin
        raddr_bin <= raddr_bin + 1;
        rptr_gray <= next_rptr_gray;
      end
    end
  end


  assign next_wptr_gray = waddr_bin ^ (waddr_bin >> 1);
  assign next_rptr_gray = raddr_bin ^ (raddr_bin >> 1);


  always @(posedge rclk) begin
    wptr_gray_sync_0 <= wptr_gray;
    wptr_gray_sync <= wptr_gray_sync_0;
  end


  always @(posedge wclk) begin
    rptr_gray_sync_0 <= rptr_gray;
    rptr_gray_sync <= rptr_gray_sync_0;
  end


  assign rempty = (rptr_gray == wptr_gray_sync);
  assign wfull = ((wptr_gray[ADDR_WIDTH-1] ^ wptr_gray_sync[ADDR_WIDTH-1]) &&
                  (wptr_gray[ADDR_WIDTH-2] ^ wptr_gray_sync[ADDR_WIDTH-2]) &&
                  (wptr_gray[ADDR_WIDTH-3:0] == wptr_gray_sync[ADDR_WIDTH-3:0]));


  dual_port_RAM #(
    .DEPTH(DEPTH),
    .WIDTH(WIDTH)
  ) ram (
    .wclk(wclk),
    .wenc(winc && !wfull),
    .waddr(waddr_bin),
    .wdata(wdata),
    .rclk(rclk),
    .renc(rinc && !rempty),
    .raddr(raddr_bin),
    .rdata(rdata)
  );

endmodule

module dual_port_RAM #(
  parameter DEPTH = 16,
  parameter WIDTH = 8
) (
  input wire wclk,
  input wire wenc,
  input wire [$clog2(DEPTH)-1:0] waddr,
  input wire [WIDTH-1:0] wdata,
  input wire rclk,
  input wire renc,
  input wire [$clog2(DEPTH)-1:0] raddr,
  output reg [WIDTH-1:0] rdata
);
  reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];
  always @(posedge wclk) begin
    if (wenc)
      RAM_MEM[waddr] <= wdata;
  end
  always @(posedge rclk) begin
    if (renc)
      rdata <= RAM_MEM[raddr];
  end
endmodule

