module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] dividend_abs, divisor_abs;
    reg [8:0] NEG_DIVISOR;
    reg [16:0] SR;

    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] quotient, remainder;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            cnt <= 0;
            start_cnt <= 0;
            SR <= 0;
            result <= 0;
            quotient <= 0;
            remainder <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                dividend_abs <= (sign && dividend[7]) ? -dividend : dividend;
                divisor_abs <= (sign && divisor[7]) ? -divisor : divisor;
                NEG_DIVISOR <= -divisor_abs;
                SR <= {dividend_abs, 8'b0} << 1;
                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else begin
                if (start_cnt) begin
                    if (cnt == 8) begin

                        res_valid <= 1;
                        result <= {remainder[7:0], quotient[7:0]};
                        start_cnt <= 0;
                        cnt <= 0;
                    end else begin

                        wire [8:0] current_remainder = SR[16:9];
                        wire [8:0] sub_res = current_remainder - NEG_DIVISOR;
                        wire carry_out = ~sub_res[8];
                        SR <= {sub_res, SR[7:1], carry_out};
                        quotient <= {quotient[6:0], carry_out};
                        cnt <= cnt + 1;
                    end
                end

                if (opn_valid)
                    res_valid <= 0;
                else if (cnt == 8)
                    res_valid <= 1;
            end
        end
    end
endmodule

