module adder_bcd(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);
    wire [4:0] sum_bin;
    reg [3:0] sum_corrected;
    reg carry_out;

    assign sum_bin = A + B + Cin;

    always @* begin
        if (sum_bin > 9) begin
            sum_corrected = sum_bin[3:0] + 4'd6;
            carry_out = 1'b1;
        end else begin
            sum_corrected = sum_bin[3:0];
            carry_out = 1'b0;
        end
    end

    assign Sum = sum_corrected;
    assign Cout = carry_out;
endmodule

