module accu (
    input               clk,
    input               rst_n,
    input       [7:0]   data_in,
    input               valid_in,
    output reg  [9:0]   data_out,
    output reg          valid_out
);
    reg [1:0] count;
    reg [9:0] sum_reg;
    reg reset_next;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            count     <= 2'b00;
            sum_reg   <= 10'b0;
            valid_out <= 1'b0;
            data_out  <= 10'b0;
            reset_next<= 1'b0;
        end else begin
            valid_out <= 1'b0;
            reset_next<= 1'b0;


            if (valid_in) begin
                sum_reg   <= sum_reg + {2'b00, data_in};
                count     <= count + 1;
            end


            if (count == 2'd3 && valid_in) begin
                valid_out  <= 1'b1;
                data_out   <= sum_reg + {2'b00, data_in};
                reset_next <= 1'b1;
            end


            if (reset_next) begin
                sum_reg   <= 10'b0;
                count     <= 2'b00;
                data_out  <= 10'b0;
            end
        end
    end
endmodule

