module fixed_point_adder #(parameter Q=2, parameter N=4) (
    input [N-1:0] a, b,
    output reg [N-1:0] c
);
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    reg [N-1:0] res;

    always @(*) begin
        if (a_sign == b_sign) begin
            res = a + b;
            res[N-1] = a_sign;
