module fixed_point_subtractor #(parameter Q=2, N=4) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    wire same_sign;
    wire a_sign, b_sign;
    wire [N-1:0] b_abs, a_abs;
    wire [N-1:0] sum;

    assign a_sign = a[N-1];
    assign b_sign = b[N-1];
    assign same_sign = (a_sign == b_sign);

    always @* begin
        if (same_sign) begin
            c = a - b;
            c[N-1] = a_sign;
        end else begin
            if (a_sign == 0) begin 
                b_abs = ~b + 1;
                sum = a + b_abs;
                if (a > b_abs) begin
                    c = sum;
                    c[N-1] = 0;
                end else begin
                    c = sum;
                    c[N-1] = 1;
                end
            end else begin 
                a_abs = ~a + 1;
                sum = a_abs + b;
                if (a_abs < b) begin
                    c = sum;
                    c[N-1] = 1;
                end else begin
                    c = sum;
                    c[N-1] = 0;
                end
            end
        end


        if (c == {N{1'b0}}) begin
            c[N-1] = 1'b0;
        end
    end

endmodule

