module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];

reg [2:0] SP;


initial begin
    SP = 4;
    dataOut = 4'b0;
    EMPTY = 1;
    FULL = 0;
    stack_mem[0] = 4'b0;
    stack_mem[1] = 4'b0;
    stack_mem[2] = 4'b0;
    stack_mem[3] = 4'b0;
end

always @(posedge Clk) begin
    if (Rst) begin

        SP <= 4;
        dataOut <= 4'b0;
        EMPTY <= 1;
        FULL <= 0;
        stack_mem[0] <= 4'b0;
        stack_mem[1] <= 4'b0;
        stack_mem[2] <= 4'b0;
        stack_mem[3] <= 4'b0;
    end else if (EN) begin
        reg [2:0] next_SP;
        next_SP = SP;

        if (RW) begin 
            if (!FULL) begin
                dataOut <= stack_mem[SP];
                stack_mem[SP] <= 4'b0;
                next_SP = SP + 1;
            end
        end else begin 
            if (!EMPTY) begin
                stack_mem[SP-1] <= dataIn;
                next_SP = SP - 1;
            end
        end

        SP <= next_SP;
        EMPTY <= (next_SP == 4);
        FULL <= (next_SP == 0);
    end
end

endmodule

