module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);
    parameter [1:0] idle = 2'b00,
                    s1_red = 2'b01,
                    s2_yellow = 2'b10,
                    s3_green = 2'b11;
    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;
    reg p_red_prev, p_yellow_prev, p_green_prev;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 0;
                end
                s1_red: begin
                    p_red <= 1;
                    if (cnt == 3) begin
                        state <= s3_green;
                        p_red <= 0;
                        p_green <= 1;
                    end
                end
                s3_green: begin
                    p_green <= 1;
                    if (cnt == 3) begin
                        state <= s2_yellow;
                        p_green <= 0;
                        p_yellow <= 1;
                    end
                end
                s2_yellow: begin
                    p_yellow <= 1;
                    if (cnt == 3) begin
                        state <= s1_red;
                        p_yellow <= 0;
                        p_red <= 1;
                    end
                end
                default: begin
                    state <= idle;
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 0;
                end
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && p_green)
                cnt <= 10;
            else if (!p_green && p_green_prev)
                cnt <= 60;
            else if (!p_yellow && p_yellow_prev)
                cnt <= 5;
            else if (!p_red && p_red_prev)
                cnt <= 10;
            else
                cnt <= cnt - 1;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red_prev <= 0;
            p_yellow_prev <= 0;
            p_green_prev <= 0;
        end else begin
            p_red_prev <= p_red;
            p_yellow_prev <= p_yellow;
            p_green_prev <= p_green;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            red <= p_red;
            yellow <= p_yellow;
            green <= p_green;
        end
    end

    assign clock = cnt;

endmodule

