module alu(...);
    input [31:0] a, b;
    input [5:0] aluc;
    output reg [31:0] r;
    output reg zero, negative;
    output reg carry, overflow;
    output reg flag;

    always @(*) begin
        case(aluc)

            ADD: begin
                {carry, r} = a + b;
                overflow = (a[31] == b[31]) && (r[31] != a[31]);
            end
            ADDU: begin
                {carry, r} = a + b;
                overflow = 0;

            end
            SUB: begin
                {carry, r} = a - b;
                overflow = (a[31] != b[31]) && (r[31] != a[31]);
                carry = (a >= b);

            end
            SUBU: begin
                {carry, r} = a - b;
                overflow = 0;
                carry = (a >= b);
            end

            default: r = 'z;
        endcase


        zero = (r == 32'b0);
        negative = r[31];
        flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;
    end
endmodule

