module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] abs_dividend, abs_divisor;
    reg [15:0] sr;

    reg [3:0] cnt;
    reg start_cnt;
    reg reg_sign;
    wire [8:0] neg_divisor;
    wire [8:0] neg_result;
    wire carry_out;


    wire [7:0] div_a_abs = sign ? (dividend[7] ? -dividend : dividend) : dividend;
    wire [7:0] div_b_abs = sign ? (divisor[7] ? -divisor : divisor) : divisor;


    wire [8:0] sub_result = sr[15:8] - neg_divisor;
    assign carry_out = ~sub_result[8];



    wire [7:0] remainder_signed = reg_sign ? (dividend[7] ? -sr[15:8] : sr[15:8]) : sr[15:8];
    wire [7:0] quotient_signed = reg_sign ? (div_a_abs[7] ^ div_b_abs[7] ? -sr[7:0] : sr[7:0]) : sr[7:0];

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            start_cnt <= 0;
            cnt <= 0;
            sr <= 16'b0;
            reg_sign <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                reg_sign <= sign;
                abs_dividend <= div_a_abs;
                abs_divisor <= div_b_abs;

                sr <= {div_a_abs, 8'b0} << 1;

                sr[15:8] <= {1'b0, div_b_abs};
                start_cnt <= 1;
                cnt <= 1;
            end else if (start_cnt) begin
                if (cnt < 8) begin

                    if (carry_out) begin
                        sr <= {sub_result, sr[0]};
                    end else begin
                        sr <= sr << 1;
                    end
                    cnt <= cnt + 1;
                end else begin

                    if (reg_sign) begin
                        result <= {remainder_signed, quotient_signed};
                    end else begin
                        result <= sr;
                    end
                    start_cnt <= 0;
                    res_valid <= 1;
                end
            end else if (res_valid) begin
                res_valid <= 0;
            end
        end
    end
endmodule

