module div_16bit(A, B, result, odd);
    input [15:0] A;
    input [7:0] B;
    output reg [15:0] result;
    output reg [15:0] odd;

    reg [15:0] a_reg;
    reg [7:0] b_reg;

    always @(A, B) begin
        a_reg = A;
        b_reg = B;
    end

    always @(A, B) begin
        result = 16'b0;
        odd = 16'b0;
        reg [7:0] rem = a_reg[15:8];
        reg [15:0] div = a_reg;
        reg [15:0] temp_result = 16'b0;

        for (integer i = 0;
 i < 8;
 i = i + 1) begin
            if (rem >= b_reg) begin
                rem = rem - b_reg;
                temp_result[15 - i] = 1'b1;
            end else begin
                temp_result[15 - i] = 1'b0;
            end
            rem = {rem[6:0], div[14 - i]};
        end

        result = temp_result;
        odd[7:0] = rem;
    end
endmodule

