module multi_16bit (
    input clk,
    input rst_n,
    input start,
    input [15:0] ain,
    input [15:0] bin,
    output reg [31:0] yout,
    output reg done
);
    reg [4:0] i;

    reg [15:0] areg, breg;

    reg [31:0] yout_r;

    reg done_r;



    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            i <= 5'b0;
        end else begin
            if (start && (i < 17)) begin
                i <= i + 1;
            end else begin
                i <= 5'b0;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            areg <= 16'b0;
            breg <= 16'b0;
            yout_r <= 32'b0;
            done_r <= 1'b0;
        end else begin
            if (i == 0) begin
                areg <= bin;

                breg <= ain;

                yout_r <= 32'b0;
            end else if (i > 0 && i < 17) begin
                if (areg[i-1]) begin
                    yout_r <= yout_r + (breg << (i-1));

                end
            end
            done_r <= (i == 16);

        end
    end

    assign done = done_r;
    assign yout = yout_r;

