module fixed_point_adder #(parameter Q = 8, parameter N = 16) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);
    reg [N-1:0] res;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire [N-1:0] abs_a, abs_b;
    reg [N-1:0] result_abs;
    reg result_sign;

    always @(*) begin

        abs_a = a_sign ? (~a + 1) : a;
        abs_b = b_sign ? (~b + 1) : b;

        if (a_sign == b_sign) begin

            result_abs = abs_a + abs_b;
            result_sign = a_sign;
        end else begin

            if (abs_a > abs_b) begin
                result_abs = abs_a - abs_b;
                result_sign = a_sign;
            end else begin
                result_abs = abs_b - abs_a;
                result_sign = b_sign;
            end
        end


        res = {result_sign, result_abs};
    end

    assign c = res;

endmodule

