module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, a_exponent_adj, b_exponent_adj;
    reg [23:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;
    reg [22:0] z_mantissa;
    reg [7:0] z_exponent;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] != 8'b0) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                    b_mantissa <= (b[30:23] != 8'b0) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};


                    if ((a[30:23] == 8'hff && a[22:0] != 0) || (b[30:23] == 8'hff && b[22:0] != 0)) begin

                        z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                        counter <= 3'b111;
                    end else if ((a[30:23] == 8'hff && a[22:0] == 0) || (b[30:23] == 8'hff && b[22:0] == 0)) begin

                        if ((a[30:23] == 8'hff && a[22:0] == 0) && (b[30:23] == 8'hff && b[22:0] == 0)) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                        end else begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                        end
                        counter <= 3'b111;
                    end else if (a[30:23] == 8'b0 && a[22:0] == 0 && (b[30:23] == 8'b0 && b[22:0] == 0)) begin

                        z <= {a_sign ^ b_sign, 31'b0};
                        counter <= 3'b111;
                    end else begin

                        counter <= 3'b001;
                    end
                end
                3'b001: begin

                    product <= a_mantissa * b_mantissa;
                    counter <= 3'b010;
                end
                3'b010: begin

                    if (product[47]) begin
                        product <= product >> 1;
                        a_exponent_adj <= a_exponent - 8'd127;
                        b_exponent_adj <= b_exponent - 8'd127;
                        z_exponent <= (a_exponent - 8'd127 + b_exponent - 8'd127 + 8'd1) + 8'd127;
                    end else begin
                        a_exponent_adj <= a_exponent - 8'd127;
                        b_exponent_adj <= b_exponent - 8'd127;
                        z_exponent <= a_exponent - 8'd127 + b_exponent - 8'd127;
                    end
                    counter <= 3'b011;
                end
                3'b011: begin

                    guard_bit <= product[22];
                    round_bit <= product[21];
                    sticky <= |product[20:0];
