module LIFObuffer(
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output wire EMPTY,
    output wire FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] SP;



assign EMPTY = (SP == 3'b100);

assign FULL = (SP == 3'b000);


always @(posedge Clk) begin
    if (Rst) begin

        SP <= 3'b100;
        dataOut <= 4'b0;
        for (integer i = 0;
 i < 4;
 i = i + 1)
            stack_mem[i] <= 4'b0;
    end else if (EN) begin
        case ({RW, FULL, EMPTY})

            3'b000: begin
                stack_mem[SP-1] <= dataIn;
                SP <= SP - 1;
            end

            3'b100: begin
                dataOut <= stack_mem[SP];
                stack_mem[SP] <= 4'b0;
                SP <= SP + 1;
            end

            default: ;

        endcase
    end
end

endmodule

