module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);
    parameter IDLE  = 2'b00;
    parameter STATE1 = 2'b01;
    parameter STATE2 = 2'b10;
    reg [1:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= IDLE;
            data_out <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (data_in == 0)
                        state <= STATE1;
                    else
                        state <= IDLE;
                    data_out <= 1'b0;
                end
                STATE1: begin
                    if (data_in == 1)
                        state <= STATE2;
                    else
                        state <= IDLE;
                    data_out <= 1'b0;
                end
                STATE2: begin
                    if (data_in == 0) begin
                        state <= IDLE;
                        data_out <= 1'b1;
                    end else begin
                        state <= IDLE;
                        data_out <= 1'b0;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

