module traffic_light(
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);
    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case(state)
                idle: state <= s1_red;
                s1_red: begin
                    if (cnt == 3)
                        state <= s3_green;
                    else
                        state <= s1_red;
                end
                s3_green: begin
                    if (cnt == 3)
                        state <= s2_yellow;
                    else
                        state <= s3_green;
                end
                s2_yellow: begin
                    if (cnt == 3)
                        state <= s1_red;
                    else
                        state <= s2_yellow;
                end
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (state == s3_green && pass_request) begin
                if (cnt > 10)
                    cnt <= 10;
                else
                    cnt <= cnt;
            end else if (!green && p_green) begin
                cnt <= 60;
            end else if (!yellow && p_yellow) begin
                cnt <= 5;
            end else if (!red && p_red) begin
                cnt <= 10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            p_red <= (state == s1_red);
            p_yellow <= (state == s2_yellow);
            p_green <= (state == s3_green);
            red <= p_red;
            yellow <= p_yellow;
            green <= p_green;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            clock <= 10;
        end else begin
            clock <= cnt;
        end
    end

endmodule

