module width_8to16 (
    input clk,
    input rst_n,
    input valid_in,
    input [7:0] data_in,
    output reg valid_out,
    output reg [15:0] data_out
);

reg [7:0] data_lock;
reg store_next;
reg [15:0] next_data;
reg gen_next;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data_out <= 16'b0;
        valid_out <= 1'b0;
        data_lock <= 8'b0;
        store_next <= 1'b0;
        next_data <= 16'b0;
        gen_next <= 1'b0;
    end else begin
        valid_out <= 1'b0;

        if (gen_next) begin
            data_out <= next_data;
            valid_out <= 1'b1;
            gen_next <= 1'b0;
        end

        if (store_next) begin
            if (valid_in) begin
                next_data <= {data_lock, data_in};
                gen_next <= 1'b1;
                store_next <= 1'b0;
            end
        end else begin
            if (valid_in) begin
                data_lock <= data_in;
                store_next <= 1'b1;
            end
        end
    end
end

endmodule

