module alu(
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [32:0] res_full;
    reg [31:0] res;

    assign zero = (r == 32'b0);
    assign negative = r[31];
    assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;

    always @(*) begin
        case (aluc)
            ADD: begin
                res_full = {1'b0, a} + {1'b0, b};
                res = res_full[31:0];
                carry = res_full[32];
                overflow = res_full[31] ^ res_full[32];
            end
            ADDU: begin
                res_full = {1'b0, a} + {1'b0, b};
                res = res_full[31:0];
                carry = res_full[32];
                overflow = 0;
            end
            SUB: begin
                res_full = {1'b0, a} - {1'b0, b};
                res = res_full[31:0];
                carry = res_full[32];
                overflow = res_full[31] ^ res_full[32];
            end
            SUBU: begin
                res_full = {1'b0, a} - {1'b0, b};
                res = res_full[31:0];
                carry = res_full[32];
                overflow = 0;
            end
            AND: begin
                res = a & b;
                carry = 0;
                overflow = 0;
            end
            OR: begin
                res = a | b;
                carry = 0;
                overflow = 0;
            end
            XOR: begin
                res = a ^ b;
                carry = 0;
                overflow = 0;
            end
            NOR: begin
                res = ~(a | b);
                carry = 0;
                overflow = 0;
            end
            SLT: begin
                res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                carry = 0;
                overflow = 0;
            end
            SLTU: begin
                res = (a < b) ? 32'd1 : 32'd0;
                carry = 0;
                overflow = 0;
            end
            SLL: begin
                res = b << a[4:0];
                carry = 0;
                overflow = 0;
            end
            SRL: begin
                res = b >> a[4:0];
                carry = 0;
                overflow = 0;
            end
            SRA: begin
                res = $signed(b) >>> a[4:0];
                carry = 0;
                overflow = 0;
            end
            SLLV: begin
                res = b << a[4:0];
                carry = 0;
                overflow = 0;
            end
            SRLV: begin
                res = b >> a[4:0];
                carry = 0;
                overflow = 0;
            end
            SRAV: begin
                res = $signed(b) >>> a[4:0];
                carry = 0;
                overflow = 0;
            end
            LUI: begin
                res = {a[31:16], 16'b0};
                carry = 0;
                overflow = 0;
            end
            default: begin
                res = 32'bz;
                carry = 0;
                overflow = 0;
            end
        endcase
        r = res;
    end
endmodule

