module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] abs_dividend, abs_divisor;
reg [16:0] SR;

reg [3:0] cnt;
reg start_cnt;


wire signed [7:0] signed_dividend = sign ? $signed(dividend) : $signed({1'b0, dividend});
wire signed [7:0] signed_divisor = sign ? $signed(divisor) : $signed({1'b0, divisor});

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        start_cnt <= 0;
        cnt <= 0;
        SR <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        result <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            abs_dividend <= sign ? (signed_dividend < 0 ? -signed_dividend : signed_dividend) : dividend;
            abs_divisor <= sign ? (signed_divisor < 0 ? -signed_divisor : signed_divisor) : divisor;

            SR <= {abs_dividend, 8'b0} << 1;

            start_cnt <= 1;
            cnt <= 1;
            res_valid <= 0;
        end else if (start_cnt) begin
            if (cnt == 8) begin

                result <= {SR[16:9], SR[7:0]};

                res_valid <= 1;
                start_cnt <= 0;
                cnt <= 0;
            end else begin

                wire [8:0] remainder = SR[16:9];
                wire [8:0] neg_divisor = -{{1'b0, abs_divisor}};

                wire [8:0] sub_result = remainder - neg_divisor;
                wire carry_out = ~sub_result[8];


                if (carry_out) begin

                    SR <= {sub_result, SR[7:0], 1'b1} << 1;
                end else begin

                    SR <= {remainder, SR[7:0], 1'b0} << 1;
                end
                cnt <= cnt + 1;
            end
        end
    end
end

endmodule

