module div_16bit(A, B, result, odd);
    input [15:0] A;
    input [7:0] B;
    output reg [15:0] result;
    output reg [15:0] odd;

    reg [15:0] a_reg, b_reg;


    always @(A, B) begin
        a_reg = A;
        b_reg = B;
    end


    always @(A, B) begin
        reg [7:0] dividend_high;
        reg [7:0] divisor;
        reg [7:0] rem;
        reg [15:0] quo;
        integer i;
        reg bit;

        dividend_high = a_reg[15:8];
        divisor = b_reg;
        rem = dividend_high;
        quo = 16'b0;

        for (i = 0;
 i < 16;
 i = i + 1) begin

            bit = a_reg[15 - i];
            rem = (rem << 1) | bit;

            if (rem >= divisor) begin
                quo[15 - i] = 1'b1;
                rem = rem - divisor;
            end else begin
                quo[15 - i] = 1'b0;
            end
        end

        result = quo;
        odd = {9'b0, rem};

    end
endmodule

