module cla_16bit (
    input [16:1] A,
    input [16:1] B,
    input C_in,
    output [16:1] S,
    output C_out
);
wire [16:1] G, P;
wire [16:1] C;

assign C[0] = C_in;


genvar i;
generate
    for (i = 1;
 i <= 16;
 i = i + 1) begin : pg
        assign G[i] = A[i] & B[i];
        assign P[i] = A[i] ^ B[i];
    end
endgenerate


generate
    for (i = 1;
 i <= 16;
 i = i + 1) begin : carry

        wire [i:1] terms;
        assign terms[i] = 1'b0;
        assign terms[1] = G[i];
        genvar j;
        for (j = 1;
 j <= i - 1;
 j = j + 1) begin : term_loop
            wire p_chain;
            assign p_chain = &P[i-1 : j+1];
            assign terms[j] = G[j] & p_chain;
            assign terms[i] = terms[i] | terms[j];
        end

        wire all_p;
        assign all_p = &P[i-1 : 1];
        assign terms[i] = terms[i] | (all_p & C[0]);
        assign C[i] = terms[i];
    end
endgenerate


assign S[1] = P[1] ^ C[0];
genvar k;
generate
    for (k = 2;
 k <= 16;
 k = k + 1) begin : sum
        assign S[k] = P[k] ^ C[k-1];
    end
endgenerate


