wire [16:1] G_terms;
generate
    for (i = 1;
 i <= 16;
 i = i + 1) begin : g_terms
        wire p_product;
        assign p_product = &P[i+16:i+1];
        assign G_terms[i] = G[i] & p_product;
    end
endgenerate
assign G_group = |G_terms;


assign P_group = &P[16:1];

assign C_out = G_group | (P_group & C[0]);

endmodule

