module fixed_point_adder #(parameter Q=4, parameter N=8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
reg a_sign, b_sign;
reg [N-1:0] res;

always @* begin
    a_sign = a[N-1];
    b_sign = b[N-1];
    if (a_sign == b_sign) begin

        reg [N-1:0] temp_res;
        temp_res = a + b;

        if (a_sign) begin

            res = (temp_res[N-1] == 0) ? {1'b1, {N-1{1'b0}}} : temp_res;
        end else begin

            res = (temp_res[N-1] == 1) ? {1'b0, {N-1{1'b1}}} : temp_res;
        end
    end else begin

        reg [N-1:0] a_abs, b_abs;
        reg a_larger;

        a_abs = a_sign ? (~a + 1) : a;
        b_abs = b_sign ? (~b + 1) : b;
        a_larger = (a_abs > b_abs);

        if (a_larger) begin
            res = a - b;
            res[N-1] = a_sign;
        end else begin
            res = b - a;
            res[N-1] = b_sign;
        end
    end
    c = res;
end

endmodule

