module float_multi (
    input wire clk,
    input wire rst,
    input wire [31:0] a,
    input wire [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [7:0] a_exponent, b_exponent, z_exponent;
reg [23:0] a_mantissa, b_mantissa, z_mantissa;
reg [49:0] product;
reg guard_bit, round_bit, sticky;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
        a_sign <= 1'b0;
        b_sign <= 1'b0;
        z_sign <= 1'b0;
        a_exponent <= 8'b0;
        b_exponent <= 8'b0;
        z_exponent <= 8'b0;
        a_mantissa <= 24'b0;
        b_mantissa <= 24'b0;
        product <= 48'b0;
        guard_bit <= 1'b0;
        round_bit <= 1'b0;
        sticky <= 1'b0;
    end else begin
        case (counter)
            3'd0: begin 
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= (a[30:23] == 8'd0) ? 8'd1 : a[30:23];
                b_exponent <= (b[30:23] == 8'd0) ? 8'd1 : b[30:23];
                a_mantissa <= (a[30:23] == 8'd0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                b_mantissa <= (b[30:23] == 8'd0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                counter <= counter + 1;
            end
            3'd1: begin 
                if ((a_exponent == 8'hff && a_mantissa != 24'b0) || 
                    (b_exponent == 8'hff && b_mantissa != 24'b0)) begin
                    z <= {a_sign ^ b_sign, 8'hff, 23'h000001};
                end else if (a_exponent == 8'hff || b_exponent == 8'hff) begin
                    if ((a_exponent == 8'hff && a_mantissa == 24'b0) || 
                        (b_exponent == 8'hff && b_mantissa == 24'b0)) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                    end else begin
                        z <= 32'b0;
                    end
                end else begin
                    z_exponent <= a_exponent + b_exponent - 8'd127;
                    product <= {a_mantissa, 24'b0} * {b_mantissa, 24'b0};
                    counter <= counter + 1;
                end
            end
            3'd2: begin 
                if (product[47]) begin
                    z_mantissa <= product[46:24];
                    z_exponent <= z_exponent + 1;
                end else begin
                    z_mantissa <= product[47:25];
                end
                guard_bit <= product[46:24];
                round_bit <= product[45];
                sticky <= |product[44:0];
                counter <= counter + 1;
            end
            3'd3: begin 
                if (guard_bit && (round_bit || sticky)) begin
                    if (z_mantissa[0]) begin
                        z_mantissa <= z_mantissa + 1;
                    end
                end
                counter <= counter + 1;
            end
            3'd4: begin 
                if (z_mantissa[23]) begin
                    z_mantissa <= {1'b1, z_mantissa[22:0]};
                    z_exponent <= z_exponent + 1;
                end
                counter <= counter + 1;
            end
            3'd5: begin 
                if (z_exponent > 8'd127) begin
                    z <= {z_sign, 8'hff, 23'b0};
                end else if (z_exponent < -8'd126) begin
                    z <= {z_sign, 31'b0};
                end else begin
                    z <= {z_sign, z_exponent + 127, z_mantissa[22:0]};
                end
                counter <= 3'b0;
            end
            default: counter <= 3'b0;
        endcase
    end
end

endmodule

