module LIFObuffer(
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);
    reg [2:0] SP;

    reg [3:0] stack_mem [0:3];


    always @(posedge Clk) begin
        reg [2:0] next_SP;
        reg next_EMPTY, next_FULL;

        if (EN) begin
            if (Rst) begin

                SP <= 3'b100;

                EMPTY <= 1'b1;
                FULL <= 1'b0;

                stack_mem[0] <= 4'b0;
                stack_mem[1] <= 4'b0;
                stack_mem[2] <= 4'b0;
                stack_mem[3] <= 4'b0;
            end else begin

                next_SP = SP;
                next_EMPTY = EMPTY;
                next_FULL = FULL;


                case ({RW, (SP == 3'b000), (SP == 3'b100)})
                    3'b0_0_0: begin 
                        stack_mem[SP-1] <= dataIn;
                        next_SP = SP - 1;
                        next_FULL = (next_SP == 3'b000);
                    end
                    3'b1_0_0: begin 
                        dataOut <= stack_mem[SP];
                        next_SP = SP + 1;
                        next_EMPTY = (next_SP == 3'b100);
                    end
                    default: begin 
                        next_SP = SP;
                        next_EMPTY = EMPTY;
                        next_FULL = FULL;
                    end
                endcase


                SP <= next_SP;
                EMPTY <= next_EMPTY;
                FULL <= next_FULL;
            end
        end
    end
endmodule

