module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output reg flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;


    reg [31:0] res;
    reg a_lt_b;
    wire [32:0] temp_sum, temp_diff;
    reg [4:0] shift_amount;


    assign zero = (res == 32'b0);


    assign negative = res[31];


    always @(*) begin
        case (aluc)
            SLT:  flag = a_lt_b;
            SLTU: flag = a_lt_b;
            default: flag = 1'bz;
        endcase
    end


    always @(*) begin
        case (aluc)
            ADD: begin
                temp_sum = {1'b0, a} + {1'b0, b};
                res = temp_sum[31:0];
                carry = temp_sum[32];
                overflow = (a[31] == b[31]) && (res[31] != a[31]);
            end
            ADDU: begin
                res = a + b;
                carry = 1'b0;

                overflow = 1'b0;
            end
            SUB: begin
                temp_diff = {1'b0, a} - {1'b0, b};
                res = temp_diff[31:0];
                carry = ~temp_diff[32];
                overflow = (a[31] != b[31]) && (res[31] != a[31]);
            end
            SUBU: begin
                res = a - b;
                carry = 1'b0;

                overflow = 1'b0;
            end
            AND: res = a & b;
            OR:  res = a | b;
            XOR: res = a ^ b;
            NOR: res = ~(a | b);
            SLT: begin
                a_lt_b = ($signed(a) < $signed(b));
                res = {31'b0, a_lt_b};
            end
            SLTU: begin
                a_lt_b = (a < b);
