module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg, b_reg;
integer i;


always @(*) begin
    a_reg = A;
    b_reg = B;
end


always @(*) begin
    reg [15:0] temp;
    reg [7:0] remainder;
    reg [15:0] quotient;

    remainder = {8'b0, a_reg[15:8]};

    quotient = 16'b0;


    for (i = 15;
 i >= 0;
 i = i - 1) begin
        if (remainder >= b_reg) begin
            quotient[i] = 1'b1;
            remainder = remainder - b_reg;
        end else begin
            quotient[i] = 1'b0;
        end


        if (i != 0) begin
            temp = {remainder[6:0], a_reg[i-1]};
            remainder = {8'b0, temp};
        end
    end

    result = quotient;
    odd = {8'b0, remainder};
end

endmodule

