module multi_16bit (
    input clk,
    input rst_n,
    input start,
    input [15:0] ain,
    input [15:0] bin,
    output reg [31:0] yout,
    output reg done
);

reg [4:0] i;

reg [15:0] areg, breg;

reg [31:0] yout_r;

reg done_r;



always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        i <= 5'b0;
        areg <= 16'b0;
        breg <= 16'b0;
        yout_r <= 32'b0;
    end else begin
        reg [4:0] i_next = i;


        if (start) begin
            i_next = (i < 17) ? i + 1 : 5'b0;
        end else begin
            i_next = 5'b0;
        end

        if (start && (i_next == 0)) begin
            areg <= ain;
            breg <= bin;
            yout_r <= 32'b0;
        end

        if (start && (i_next > 0) && (i_next < 17) && areg[i_next-1]) begin
            yout_r <= yout_r + (breg << (i_next-1));
        end
        i <= i_next;
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        done_r <= 1'b0;
    end else begin
        case (i)
            16: done_r <= 1'b1;

            17: done_r <= 1'b0;

            default: done_r <= done_r;
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        yout <= 32'b0;
        done <= 1'b0;
    end else begin
        yout <= yout_r;
        done <= done_r;
    end
end

