module fixed_point_adder #(parameter Q=3, N=5) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire [N-1:0] abs_a, abs_b;


    assign abs_a = a[N-1] ? (~a + 1) : a;
    assign abs_b = b[N-1] ? (~b + 1) : b;

    always @(*) begin
        if (a[N-1] == b[N-1]) begin

            res = abs_a + abs_b;
            res[N-1] = a[N-1];

            if (res[N-1] != a[N-1]) begin

                res = a[N-1] ? {1'b1, {(N-1){1'b0}}} : {1'b0, {(N-1){1'b1}}};
            end
        end else begin

            if (abs_a > abs_b) begin
                res = abs_a - abs_b;
                res[N-1] = 0;
            end else if (abs_b > abs_a) begin
                res = abs_b - abs_a;
                res[N-1] = 1;
            end else begin

                res = {1'b0, {(N-1){1'b0}}};
            end
        end
        c = res;
    end
endmodule

