module fixed_point_subtractor #(parameter Q=4, parameter N=8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a, sign_b;
    wire same_sign;
    reg [N-1:0] a_abs, b_abs;
    reg [N:0] sum_abs;

    reg res_sign;

    always @* begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        same_sign = (sign_a == sign_b);

        if (same_sign) begin

            res = a - b;
            res[N-1] = sign_a;
        end else begin

            a_abs = sign_a ? (~a + 1) : a;
            b_abs = sign_b ? (~b + 1) : b;
            sum_abs = a_abs + b_abs;
            res_sign = (a_abs > b_abs) ? 1'b0 : 1'b1;
            res = sum_abs[N-1:0];
            res[N-1] = res_sign;
        end


        if (res == 0)
            res[N-1] = 0;

        c = res;
    end
endmodule

