    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr_bin <= 0;
        end else begin
            if (ren) begin
                rptr_bin <= rptr_bin + 1;
            end
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr_gray <= 0;
        end else begin
            rptr_gray <= (rptr_bin >> 1) ^ rptr_bin;
        end
    end


    reg [PTR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync2;
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_gray_sync1 <= 0;
            rptr_gray_sync2 <= 0;
        end else begin
            rptr_gray_sync1 <= rptr_gray;
            rptr_gray_sync2 <= rptr_gray_sync1;
        end
    end
    assign wptr_sync_rclk = rptr_gray_sync2;


    reg [PTR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync2;
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_gray_sync1 <= 0;
            wptr_gray_sync2 <= 0;
        end else begin
            wptr_gray_sync1 <= wptr_gray;
            wptr_gray_sync2 <= wptr_gray_sync1;
        end
    end
    assign rptr_sync_wclk = wptr_gray_sync2;


    wire full_cond = (wptr_gray[PTR_WIDTH-1] ^ wptr_sync_rclk[PTR_WIDTH-1]) &&
                     (wptr_gray[PTR_WIDTH-2] ^ wptr_sync_rclk[PTR_WIDTH-2]) &&
                     (wptr_gray[PTR_WIDTH-3:0] == wptr_sync_rclk[PTR_WIDTH-3:0]);


    wire empty_cond = (wptr_gray == rptr_sync_wclk);


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wfull <= 0;
        end else begin
            wfull <= full_cond;
        end
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rempty <= 1;
        end else begin
            rempty <= empty_cond;
        end
    end

endmodule

