module traffic_light(rst_n, clk, pass_request, clock, red, yellow, green);
    input rst_n, clk, pass_request;
    output reg [7:0] clock;
    output reg red, yellow, green;

    parameter idle = 2'b00,
              s1_red = 2'b01,
              s2_yellow = 2'b10,
              s3_green = 2'b11;

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: begin
                    p_red <= 1;
                    if (cnt == 3) state <= s3_green;
                end
                s2_yellow: begin
                    p_yellow <= 1;
                    if (cnt == 3) state <= s1_red;
                end
                s3_green: begin
                    p_green <= 1;
                    if (cnt == 3) state <= s2_yellow;
                end
                default: state <= idle;
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
            clock <= 0;
        end else begin
            clock <= cnt;
            if (pass_request && p_green)
                cnt <= 10;
            else if (state == s1_red && p_red && !p_green)
                cnt <= 60;
            else if (state == s2_yellow && p_yellow && !p_red)
                cnt <= 5;
            else if (state == s3_green && p_green && !p_yellow)
                cnt <= 10;
            else if (cnt != 0)
                cnt <= cnt - 1;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {red, yellow, green} <= 3'b0;
        end else begin
            red <= p_red;
            yellow <= p_yellow;
            green <= p_green;
        end
    end

endmodule

