module alu(
    input [31:0] a, b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero, carry, negative, overflow,
    output reg flag
);
    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [32:0] res;
    reg carry_temp;
    reg overflow_temp;
    reg negative_temp;
    integer shamt_sll, shamt_srl, shamt_sra;

    always @* begin
        case(aluc)
            ADD: begin
                res = {1'b0, a} + {1'b0, b};
                carry_temp = res[32];
                r = res[31:0];
            end
            ADDU: begin
                res = {1'b0, a} + {1'b0, b};
                carry_temp = res[32];
                r = res[31:0];
            end
            SUB: begin
                res = {1'b0, a} - {1'b0, b};
                carry_temp = res[32];
                r = res[31:0];
            end
            SUBU: begin
                res = {1'b0, a} - {1'b0, b};
                carry_temp = res[32];
                r = res[31:0];
            end
            AND: begin
                r = a & b;
                carry_temp = 1'b0;
            end
            OR: begin
                r = a | b;
                carry_temp = 1'b0;
            end
            XOR: begin
                r = a ^ b;
                carry_temp = 1'b0;
            end
            NOR: begin
                r = ~(a | b);
                carry_temp = 1'b0;
            end
            SLT: begin
                r = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                carry_temp = 1'b0;
            end
            SLTU: begin
                r = (a < b) ? 32'd1 : 32'd0;
                carry_temp = 1'b0;
            end
            SLL: begin
                shamt_sll = b[4:0];
                if (shamt_sll == 0) begin
                    r = a;
                    carry_temp = 1'b0;
                end else begin
                    r = a << shamt_sll;
                    carry_temp = a[32 - shamt_sll];
                end
            end
            SRL: begin
                shamt_srl = b[4:0];
                if (shamt_srl == 0) begin
                    r = a;
                    carry_temp = 1'b0;
                end else begin
                    r = a >> shamt_srl;
                    carry_temp = a[shamt_srl - 1];
                end
            end
            SRA: begin
                shamt_sra = b[4:0];
                if (shamt_sra == 0) begin
                    r = a;
                    carry_temp = 1'b0;
                end else begin
                    r = $signed(a) >>> shamt_sra;
                    carry_temp = a[shamt_sra - 1];
                end
            end
            SLLV: begin
                shamt_sll = a[4:0];
                if (shamt_sll == 0) begin
                    r = a;
                    carry_temp = 1'b0;
                end else begin
                    r = a << shamt_sll;
                    carry_temp = a[32 - shamt_sll];
                end
            end
            SRLV: begin
                shamt_srl = a[4:0];
                if (shamt_srl == 0) begin
                    r = a;
                    carry_temp = 1'b0;
                end else begin
                    r = a >> shamt_srl;
                    carry_temp = a[shamt_srl - 1];
                end
            end
            SRAV: begin
                shamt_sra = a[4:0];
                if (shamt_sra == 0) begin
                    r = a;
                    carry_temp = 1'b0;
                end else begin
                    r = $signed(a) >>> shamt_sra;
                    carry_temp = a[shamt_sra - 1];
                end
            end
            LUI: begin
                r = {b[15:0], 16'b0};
                carry_temp = 1'b0;
            end
            default: begin
                r = 32'bz;
                carry_temp = 1'bz;
            end
        endcase

        overflow_temp = (aluc == ADD || aluc == ADDU || aluc == SUB || aluc == SUBU) ?
                       (( (a[31] == b[31]) && (r[31] != a[31]) ) ||
                        ( (aluc == SUB || aluc == SUBU) && (a[31] != b[31]) && (r[31] != a[31]) )) : 1'b0;

        negative_temp = (aluc == ADD || aluc == ADDU || aluc == SUB || aluc == SUBU || aluc == SLT) ? r[31] : 1'b0;
        flag = (aluc == SLT || aluc == SLTU) ? r[0] : 1'b0;
    end

    assign zero = (r == 32'b0);
    assign carry = carry_temp;
    assign negative = negative_temp;
    assign overflow = overflow_temp;

endmodule

