module radix2_div (
    input               clk,
    input               rst,
    input               sign,
    input signed [7:0]  dividend,
    input signed [7:0]  divisor,
    input               opn_valid,
    output reg          res_valid,
    output reg [15:0]   result
);

reg [7:0]  saved_dividend, saved_divisor;
reg        sign_dividend, sign_divisor;
reg [15:0] abs_dividend, abs_divisor;
reg [15:0] NEG_DIVISOR;
reg [15:0] SR;
reg [3:0]  cnt;
reg        start_cnt;
reg [7:0]  q_abs, r_abs;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        saved_dividend <= 0;
        saved_divisor <= 0;
        sign_dividend <= 0;
        sign_divisor <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        NEG_DIVISOR <= 0;
        SR <= 0;
        cnt <= 0;
        start_cnt <= 0;
        q_abs <= 0;
        r_abs <= 0;
        result <= 0;
    end else begin
        if (opn_valid && !res_valid) begin
            saved_dividend <= dividend;
            saved_divisor <= divisor;
            if (sign) begin
                sign_dividend <= dividend[7];
                sign_divisor <= divisor[7];
                abs_dividend <= dividend[7] ? (~dividend + 1) : dividend;
                abs_divisor <= divisor[7] ? (~divisor + 1) : divisor;
            end else begin
                sign_dividend <= 0;
                sign_divisor <= 0;
                abs_dividend <= dividend;
                abs_divisor <= divisor;
            end
            NEG_DIVISOR <= -abs_divisor;
            SR <= {abs_dividend, 8'b0} << 1;
            cnt <= 1;
            start_cnt <= 1;
            res_valid <= 0;
            q_abs <= 8'b0;
            r_abs <= 8'b0;
        end else if (start_cnt) begin
            if (cnt == 8) begin
                start_cnt <= 0;
                cnt <= 0;
                if (sign) begin
                    quotient_reg <= (sign_dividend ^ sign_divisor) ? (~q_abs + 1) : q_abs;
                    remainder_reg <= sign_dividend ? (~r_abs + 1) : r_abs;
                end else begin
                    quotient_reg <= q_abs;
                    remainder_reg <= r_abs;
                end
                result <= {remainder_reg, quotient_reg};
                res_valid <= 1;
            end else begin
                reg [15:0] temp;
                reg carry_out;
                temp = {1'b0, SR[15:8]} - NEG_DIVISOR;
                carry_out = temp[15];
                if (carry_out) begin
                    q_abs <= {q_abs[6:0], 1'b1};
                    r_abs <= temp[14:7];
                end else begin
                    q_abs <= {q_abs[6:0], 1'b0};
                    r_abs <= r_abs;
                end
                SR <= {temp[14:7], q_abs[7], SR[7:1]};
                cnt <= cnt + 1;
            end
        end
    end
end

endmodule

