    a_reg <= A;
    b_reg <= B;
end


always @(A, B) begin
    reg [15:0] temp_remainder;
    reg [7:0] divisor;
    reg [7:0] dividend_remaining;
    integer i;


    temp_remainder = {8'b0, a_reg[15:8]};
