    for (i = 0;
 i < 16;
 i = i + 1) begin

        temp_remainder = {temp_remainder[14:0], dividend_remaining[7]};
        dividend_remaining = {dividend_remaining[6:0], 1'b0};


        if (temp_remainder >= {8'b0, divisor}) begin
            result[15 - i] = 1'b1;
            temp_remainder = temp_remainder - {8'b0, divisor};
        end else begin
            result[15 - i] = 1'b0;
        end
    end


    odd = temp_remainder;
end

