module adder_bcd (A, B, Cin, Sum, Cout);
    input [3:0] A, B;
    input Cin;
    output reg [3:0] Sum;
    output reg Cout;

    wire [4:0] temp_sum;
    wire [4:0] sum_corrected;

    assign temp_sum = A + B + Cin;
    assign sum_corrected = temp_sum + 5'd6;

    always @* begin
        if (temp_sum >= 5'd10) begin
            Sum = sum_corrected[3:0];
            Cout = 1'b1;
        end else begin
            Sum = temp_sum[3:0];
            Cout = 1'b0;
        end
    end
endmodule

