module fixed_point_adder #(parameter Q=4, parameter N=8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    reg [N-1:0] magnitude_a, magnitude_b;

    always @* begin
        if (a_sign == b_sign) begin

            if (a_sign) begin
                magnitude_a = ~a + 1;

                magnitude_b = ~b + 1;

            end else begin
                magnitude_a = a;

                magnitude_b = b;

            end
            res = {a_sign, magnitude_a + magnitude_b};

        end else begin

            magnitude_a = a_sign ? (~a + 1) : a;

            magnitude_b = b_sign ? (~b + 1) : b;

            if (magnitude_a > magnitude_b) begin
                res = {a_sign, magnitude_a - magnitude_b};
            end else if (magnitude_b > magnitude_a) begin
                res = {b_sign, magnitude_b - magnitude_a};
            end else begin
                res = 0;

            end
        end
    end

    always @* begin
        c = res;
    end

endmodule

