module fixed_point_subtractor #(parameter Q=2, N=4) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    reg sign_a, sign_b;
    reg [N-1:0] a_abs, b_abs;
    reg [N-1:0] sum;

    always @* begin
        sign_a = a[N-1];
        sign_b = b[N-1];

        if (sign_a == sign_b) begin

            res = a - b;

            if (res == 0)
                res = 0;
        end else begin

            a_abs = sign_a ? (-a) : a;
            b_abs = sign_b ? (-b) : b;
            sum = a_abs + b_abs;


            if (a_abs > b_abs)
                res = {1'b0, sum[N-2:0]};

            else
                res = {1'b1, sum[N-2:0]};

        end


        if (res == 0)
            res = 0;
        c = res;
    end
endmodule

