module sequence_detector (
    input clk,
    input reset_n,
    input data_in,
    output sequence_detected
);

    localparam IDLE = 3'd0,
               S1   = 3'd1,
               S2   = 3'd2,
               S3   = 3'd3,
               S4   = 3'd4;

    reg [2:0] state, next_state;


    always @(posedge clk or negedge reset_n) begin
        if (!reset_n)
            state <= IDLE;
        else
            state <= next_state;
    end


    always @(*) begin
        case (state)
            IDLE: next_state = data_in ? S1 : IDLE;
            S1:   next_state = (data_in == 0) ? S2 : S1;
            S2:   next_state = (data_in == 0) ? S3 : IDLE;
            S3:   next_state = (data_in == 1) ? S4 : IDLE;
            S4:   next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end


    assign sequence_detected = (state == S4);

endmodule

