    input wire wclk,
    input wire rclk,
    input wire wrstn,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output wire wfull,
    output wire rempty,
    output wire [WIDTH-1:0] rdata
);
    reg [3:0] waddr_bin, raddr_bin;
    wire [3:0] wptr_gray, rptr_gray;
    reg [3:0] wptr_gray_reg, rptr_gray_reg;
    wire [3:0] wptr_gray_next, rptr_gray_next;
    reg [3:0] wptr_gray_sync1, wptr_gray_sync2;
    reg [3:0] rptr_gray_sync1, rptr_gray_sync2;
    wire [3:0] wptr_syn = wptr_gray_sync2;
    wire [3:0] rptr_syn = rptr_gray_sync2;

    dual_port_RAM #(.DEPTH(DEPTH), .WIDTH(WIDTH)) ram (
        .wclk(wclk),
        .wenc(wen),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(ren),
        .raddr(raddr_bin),
        .rdata(rdata)
    );

    wire wen = winc && !wfull;
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
            wptr_gray_reg <= 0;
        end else if (wen) begin
            waddr_bin <= waddr_bin + 1;
            wptr_gray_reg <= wptr_gray_next;
        end
    end
    assign wptr_gray_next = wptr_gray_reg ^ (wptr_gray_reg >> 1);
    assign wptr_gray = wptr_gray_reg;

    wire ren = rinc && !rempty;
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
            rptr_gray_reg <= 0;
        end else if (ren) begin
            raddr_bin <= raddr_bin + 1;
            rptr_gray_reg <= rptr_gray_next;
        end
    end
    assign rptr_gray_next = rptr_gray_reg ^ (rptr_gray_reg >> 1);
    assign rptr_gray = rptr_gray_reg;

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_gray_sync1 <= 0;
            wptr_gray_sync2 <= 0;
        end else begin
            wptr_gray_sync1 <= wptr_gray;
            wptr_gray_sync2 <= wptr_gray_sync1;
        end
    end

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_gray_sync1 <= 0;
            rptr_gray_sync2 <= 0;
        end else begin
            rptr_gray_sync1 <= rptr_gray;
            rptr_gray_sync2 <= rptr_gray_sync1;
        end
    end

    assign empty = (rptr_gray == rptr_syn);
    assign full = (wptr_gray[3] != wptr_syn[3]) &&
                  (wptr_gray[2] != wptr_syn[2]) &&
                  (wptr_gray[1:0] == wptr_syn[1:0]);

    assign rempty = empty;
    assign wfull = full;
endmodule

