module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

parameter idle = 2'b00,
          s1_red = 2'b01,
          s2_yellow = 2'b10,
          s3_green = 2'b11;

reg [1:0] state;
reg [7:0] cnt;
reg p_red, p_yellow, p_green;
reg p_red_prev, p_yellow_prev, p_green_prev;


always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= idle;
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
    end else begin
        case (state)
            idle: state <= s1_red;
            s1_red: begin
                if (cnt == 0)
                    state <= s3_green;
                else
                    state <= s1_red;
            end
            s3_green: begin
                if (cnt == 0)
                    state <= s2_yellow;
                else
                    state <= s3_green;
            end
            s2_yellow: begin
                if (cnt == 0)
                    state <= s1_red;
                else
                    state <= s2_yellow;
            end
            default: state <= idle;
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        cnt <= 10;
        p_red_prev <= 0;
        p_yellow_prev <= 0;
        p_green_prev <= 0;
    end else begin
        p_red_prev <= p_red;
        p_yellow_prev <= p_yellow;
        p_green_prev <= p_green;

        if (pass_request && p_green)
            cnt <= 10;
        else if (~p_green && p_green_prev)
            cnt <= 60;
        else if (~p_yellow && p_yellow_prev)
            cnt <= 5;
        else if (~p_red && p_red_prev)
            cnt <= 10;
        else
            cnt <= cnt - 1;
    end
end


always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
    end else begin
        case (state)
            idle: begin
                p_red <= 0;
                p_yellow <= 0;
                p_green <= 0;
            end
            s1_red: begin
                p_red <= 1;
                p_yellow <= 0;
                p_green <= 0;
            end
            s3_green: begin
                p_red <= 0;
                p_yellow <= 0;
                p_green <= 1;
            end
            s2_yellow: begin
                p_red <= 0;
                p_yellow <= 1;
                p_green <= 0;
            end
            default: begin
                p_red <= 0;
                p_yellow <= 0;
                p_green <= 0;
            end
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (~rst_n)
        clock <= 10;
    else
        clock <= cnt;
end

endmodule

