module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] abs_dividend, abs_divisor;
reg [7:0] neg_divisor;
reg [3:0] cnt;
reg start_cnt;
reg [15:0] sr;

reg [7:0] quotient;
reg [7:0] remainder;
reg dividend_sign, divisor_sign;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        quotient <= 0;
        remainder <= 0;
        start_cnt <= 0;
        cnt <= 0;
        result <= 0;
        dividend_sign <= 0;
        divisor_sign <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        neg_divisor <= 0;
        sr <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            if (sign) begin
                dividend_sign <= dividend[7];
                divisor_sign <= divisor[7];
                abs_dividend <= dividend[7] ? -dividend : dividend;
                abs_divisor <= divisor[7] ? -divisor : divisor;
                neg_divisor <= -(divisor[7] ? -divisor : divisor);
            end else begin
                dividend_sign <= 0;
                divisor_sign <= 0;
                abs_dividend <= dividend;
                abs_divisor <= divisor;
                neg_divisor <= -divisor;
            end

            sr <= {abs_dividend, 8'b0} << 1;
            cnt <= 1;
            start_cnt <= 1;
            res_valid <= 0;
        end else if (start_cnt) begin
            if (cnt == 8) begin

                start_cnt <= 0;
                quotient <= sr[6:0];
                remainder <= sr[15:9];
                if (sign) begin
                    if (dividend_sign ^ divisor_sign) quotient <= -quotient;
                    if (dividend_sign) remainder <= -remainder;
                end
                result <= {remainder, quotient};
                res_valid <= 1;
            end else begin

                reg [9:0] sum;
                sum = {1'b0, sr[15:9]} + {1'b0, abs_divisor};
                if (sum[9]) begin 
                    sr[15:9] <= sum[8:0];
                    sr[6:0] <= {sr[7:1], 1'b1};
                end else begin
                    sr[6:0] <= {sr[7:1], 1'b0};
                end
                cnt <= cnt + 1;
            end
        end else begin
            res_valid <= 0;
        end
    end
end

endmodule

