module fixed_point_adder #(parameter Q=2, N=4) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-2:0] mag_a, mag_b;
    reg sign_a, sign_b, signs_same, res_sign;
    reg [N-1:0] temp_sum;
    reg [N-1:0] sum_mag;
    reg [N-1:0] res;

    always @(*) begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        signs_same = (sign_a == sign_b);

        mag_a = a[N-2:0];
        mag_b = b[N-2:0];

        if (signs_same) begin
            temp_sum = {1'b0, mag_a} + {1'b0, mag_b};
            if (temp_sum[N]) begin
                res_sign = 1;
                sum_mag = {N-1{1'b1}};
            end else begin
                res_sign = sign_a;
                sum_mag = temp_sum[N-1:0];
            end
        end else begin
            if (mag_a > mag_b) begin
                sum_mag = mag_a - mag_b;
                res_sign = 0;
            end else if (mag_b > mag_a) begin
                sum_mag = mag_b - mag_a;
                res_sign = 1;
            end else begin
                sum_mag = 0;
                res_sign = 0;
            end
        end

        res = {res_sign, sum_mag};
        c = res;
    end
endmodule

