module fixed_point_subtractor #(
    parameter Q = 4,  
    parameter N = 8   
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    reg sign;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire [N-2:0] a_integer = a[N-2 : N-Q-1];
    wire [Q-1:0] a_fraction = a[Q-1 : 0];
    wire [N-2:0] b_integer = b[N-2 : N-Q-1];
    wire [Q-1:0] b_fraction = b[Q-1 : 0];
    reg [N-1:0] a_abs, b_abs;
    reg [N-1:0] res_abs;
    reg sign_res;

    always @* begin
        if (a_sign == b_sign) begin

            res = {a_sign, a_integer - b_integer, a_fraction - b_fraction};
            sign = a_sign;
        end else begin

            a_abs = a_sign ? -a : a;
            b_abs = b_sign ? -b : b;
            if (a_abs > b_abs) begin
                res_abs = a_abs - b_abs;
                sign_res = 1'b0;
            end else if (b_abs > a_abs) begin
                res_abs = b_abs - a_abs;
                sign_res = 1'b1;
            end else begin
                res_abs = 0;
                sign_res = 1'b0;
            end
            res = {sign_res, res_abs[N-2:0]};
            sign = sign_res;
        end


        if (res == 0) begin
            sign = 1'b0;
        end


        c = {sign, res[N-2:0]};
    end

endmodule

