reg a_sign, b_sign, z_sign;
reg [7:0] a_exponent, b_exponent, z_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg [22:0] a_mantissa_full, b_mantissa_full;
reg [47:0] product;
reg guard_bit, round_bit, sticky;
reg [7:0] sum_exp;
reg overflow, underflow;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b000;
        z <= 32'b0;
    end else begin
        case (counter)
            3'b000: begin

                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= a[22:0];
                b_mantissa <= b[22:0];

                if (a_exponent == 0) begin
                    a_mantissa_full <= {1'b0, a[22:0]};
                    a_actual_exp <= -126;
                end else begin
                    a_mantissa_full <= {1'b1, a[22:0]};
                    a_actual_exp <= a_exponent - 127;
                end

                if (b_exponent == 0) begin
                    b_mantissa_full <= {1'b0, b[22:0]};
                    b_actual_exp <= -126;
                end else begin
                    b_mantissa_full <= {1'b1, b[22:0]};
                    b_actual_exp <= b_exponent - 127;
                end

                sum_exp <= a_actual_exp + b_actual_exp;

                counter <= counter + 1;
            end
            3'b001: begin

                product <= a_mantissa_full * b_mantissa_full;

                counter <= counter + 1;
            end
            3'b010: begin

                if (product[47]) begin
                    product <= product >> 1;
                    sum_exp <= sum_exp + 1;
                end

                counter <= counter + 1;
