module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [2:0] SP;

reg [3:0] stack_mem [0:3];


always @(posedge Clk) begin
    if (Rst) begin

        SP <= 3'd4;
        stack_mem[0] <= 4'b0;
        stack_mem[1] <= 4'b0;
        stack_mem[2] <= 4'b0;
        stack_mem[3] <= 4'b0;
        dataOut <= 4'b0;
    end else if (EN) begin
        case ({RW, FULL, EMPTY})

            3'b0_1_0: begin
                stack_mem[SP-1] <= dataIn;

                SP <= SP - 1;

            end

            3'b1_0_0: begin
                dataOut <= stack_mem[SP];

                SP <= SP + 1;

            end
            default: begin

            end
        endcase
    end
end


always @* begin
    EMPTY = (SP == 3'd4);

    FULL = (SP == 3'd0);

end

endmodule

