module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);
    reg [1:0] state;
    reg data_in_prev, data_in_prev2;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= 2'b00;
            data_out <= 0;
            data_in_prev <= 0;
            data_in_prev2 <= 0;
        end else begin
            data_in_prev2 <= data_in_prev;
            data_in_prev <= data_in;
            case (state)
                2'b00: begin 
                    if (data_in_prev2 == 0 && data_in_prev == 1 && data_in == 0) begin
                        data_out <= 1;
                        state <= 2'b00;
                    end else begin
                        data_out <= 0;
                        state <= 2'b00;
                    end
                end

                default: begin
                    data_out <= 0;
                    state <= 2'b00;
                end
            endcase
        end
    end
endmodule

