module cla_16bit(A, B, CIn, S, G, P, COut);
    input [16:1] A, B, CIn;
    output [16:1] S;
    output G, P, COut;

    wire [16:1] g, p;
    wire [16:1] c;
    assign c[0] = CIn;


    genvar i;
    generate
        for (i = 1;
 i <= 16;
 i = i + 1) begin : gen_gp
            assign g[i] = A[i] & B[i];
            assign p[i] = A[i] ^ B[i];
        end
    endgenerate


    generate
        for (i = 1;
 i <= 16;
 i = i + 1) begin : carry_compute
            integer j;
            always @(*) begin
                c[i] = 0;
                for (j = 1;
 j <= i;
 j = j + 1) begin
                    reg temp;
                    temp = g[j];
                    for (integer k = j + 1;
 k <= i;
 k = k + 1) begin
                        temp = temp & p[k];
                    end
                    c[i] = c[i] | temp;
                end
            end
        end
    endgenerate


    generate
        for (i = 1;
 i <= 16;
 i = i + 1) begin : sum_compute
            assign S[i] = p[i] ^ c[i];
        end
    endgenerate


    reg G_reg, P_reg;
    integer m;
    always @(*) begin
        G_reg = 0;
        P_reg = 1;
        for (m = 1;
 m <= 16;
 m = m + 1) begin
            G_reg = G_reg | (g[m] & P_reg);
            P_reg = P_reg & p[m];
        end
    end

    assign G = G_reg;
    assign P = P_reg;
    assign COut = G_reg | (P_reg & CIn);
endmodule

