module fixed_point_adder #(parameter Q=2, N=4) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;
wire [N-1:0] abs_a, abs_b;
wire same_sign = (a[N-1] == b[N-1]);

always @(*) begin
    if (same_sign) begin
        res = a + b;
    end else begin
        abs_a = a[N-1] ? (~a + 1) : a;
        abs_b = b[N-1] ? (~b + 1) : b;
        if (abs_a >= abs_b) begin
            res = a - b;
        end else begin
            res = b - a;
        end
    end
    c = res;
end

endmodule

