module fixed_point_subtractor #(parameter Q=4, parameter N=8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    reg sign_a, sign_b;
    reg [N-2:0] a_mag, b_mag;
    reg [N-2:0] absolute_a, absolute_b;
    reg [N-2:0] sum;
    reg sign_c;

    always @(*) begin
        sign_a = a[N-1];
        sign_b = b[N-1];


        if (a == 0 && b == 0) begin
            res = 0;
        end else if (sign_a == sign_b) begin

            res = a - b;

            sign_c = (res == 0) ? 1'b0 : sign_a;
        end else begin

            absolute_a = (sign_a) ? (~a[N-2:0] + 1) : a[N-2:0];
            absolute_b = (sign_b) ? (~b[N-2:0] + 1) : b[N-2:0];

            if (absolute_a > absolute_b) begin
                sum = absolute_a - absolute_b;
                sign_c = sign_a;
            end else begin
                sum = absolute_b - absolute_a;
                sign_c = sign_b;
            end

            sign_c = (sum == 0) ? 1'b0 : sign_c;
        end

        res[N-1] = sign_c;
        res[N-2:0] = sum;
        c = res;
    end
endmodule

