    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            special_case <= 1'b0;
        end else begin
            case (counter)
                3'b000: begin 
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];

                    if (a[30:23] == 8'hff) begin
                        if (a[22:0] != 0) special_case <= 1'b1;

                        else begin 
                            special_case <= 1'b1;
                            if (a[31] ^ b[31]) z_sign <= 1'b1;
                            else z_sign <= 1'b0;
                            z_exponent <= 8'hff;
                            z_mantissa <= 23'b0;
                        end
                    end else if (b[30:23] == 8'hff) begin
                        if (b[22:0] != 0) special_case <= 1'b1;

                        else begin 
                            special_case <= 1'b1;
                            if (a[31] ^ b[31]) z_sign <= 1'b1;
                            else z_sign <= 1'b0;
                            z_exponent <= 8'hff;
                            z_mantissa <= 23'b0;
                        end
                    end else if (a[30:0] == 31'b0) begin 
                        special_case <= 1'b1;
                        z_sign <= a[31] ^ b[31];
                        z_exponent <= 8'b0;
                        z_mantissa <= 23'b0;
                    end else if (b[30:0] == 31'b0) begin 
                        special_case <= 1'b1;
                        z_sign <= a[31] ^ b[31];
                        z_exponent <= 8'b0;
                        z_mantissa <= 23'b0;
                    end else begin
                        special_case <= 1'b0;
                        counter <= counter + 1;
                    end
                end
                3'b001: begin 
                    product <= {24'b1, a_mantissa} * {24'b1, b_mantissa};
                    z_exponent <= a_exponent + b_exponent - 8'd127;
                    counter <= counter + 1;
                end
                3'b010: begin 
                    if (product[48:47] >= 2'b10) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end

                    guard_bit <= product[23];
                    round_bit <= product[22];
                    sticky <= |product[21:0];
                    counter <= counter + 1;
                end
                3'b011: begin 

                    if (z_exponent >= 8'hfe) begin 
                        z_exponent <= 8'hff;
                        z_mantissa <= 23'b0;
                    end else if (z_exponent == 0 && product[48]) begin 
                        z_exponent <= 0;
                        z_mantissa <= 23'b0;
                    end else begin

                        if ((guard_bit & (round_bit | sticky)) || 
                            (guard_bit & ~round_bit & ~sticky & z_mantissa[0])) begin
                            if (z_mantissa == 23'h7fffff) begin
                                z_mantissa <= 23'h000000;
                                z_exponent <= z_exponent + 1;
                            end else begin
                                z_mantissa <= z_mantissa + 1;
                            end
                        end
                    end
                    counter <= counter + 1;
                end
                3'b100: begin 
                    if (special_case)
                        z <= {z_sign, z_exponent, z_mantissa};
                    else
                        z <= {z_sign, z_exponent, z_mantissa};
                    counter <= 3'b0;
                end
                default: counter <= 3'b0;
            endcase
        end
    end
