module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);
    reg [3:0] stack_mem [0:3];

    reg [2:0] SP;

    reg [3:0] next_dataOut;
    reg [2:0] next_SP;
    reg next_EMPTY, next_FULL;

    always @(posedge Clk) begin
        if (EN) begin
            next_dataOut = dataOut;
            next_SP = SP;
            next_EMPTY = EMPTY;
            next_FULL = FULL;

            if (Rst) begin

                integer i;
                for (i = 0;
 i < 4;
 i = i + 1)
                    stack_mem[i] <= 4'b0;
                next_SP = 3'b100;

                next_EMPTY = 1'b1;
                next_FULL = 1'b0;
                next_dataOut = 4'b0;
            end else begin

                if (!next_FULL && !RW) begin
                    stack_mem[next_SP - 1] <= dataIn;
                    next_SP = next_SP - 1;
                end

                else if (!next_EMPTY && RW) begin
                    next_dataOut = stack_mem[next_SP];
                    stack_mem[next_SP] <= 4'b0;
                    next_SP = next_SP + 1;
                end
            end


            SP <= next_SP;
            dataOut <= next_dataOut;
            EMPTY <= (next_SP == 3'b100);

            FULL <= (next_SP == 3'b000);

        end
    end
endmodule

