module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);
    parameter IDLE = 2'b00;
    parameter STATE_1 = 2'b01;
    parameter STATE_2 = 2'b10;
    reg [1:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= IDLE;
            data_out <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (data_in) begin
                        state <= STATE_1;
                    end else begin
                        state <= IDLE;
                    end
                    data_out <= 0;
                end
                STATE_1: begin
                    if (~data_in) begin
                        state <= STATE_2;
                        data_out <= 1;
                    end else begin
                        state <= STATE_1;
                        data_out <= 0;
                    end
                end
                STATE_2: begin
                    state <= IDLE;
                    data_out <= 0;
                end
                default: begin
                    state <= IDLE;
                    data_out <= 0;
                end
            endcase
        end
    end
endmodule

