module alu(
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output flag
);
    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [31:0] res;
    wire signed [31:0] a_signed = a;
    wire signed [31:0] b_signed = b;

    assign zero = (res == 32'b0);
    assign negative = res[31];
    assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;

    always @(*) begin
        case(aluc)
            ADD: begin
                {carry, res} = {1'b0, a} + {1'b0, b};
                overflow = (a_signed[31] == b_signed[31]) && (res[31] != a_signed[31]);
            end
            ADDU: begin
                {carry, res} = {1'b0, a} + {1'b0, b};
                overflow = 1'b0;
            end
            SUB: begin
                {carry, res} = {1'b0, a} - {1'b0, b};
                overflow = (a_signed[31] != b_signed[31]) && (res[31] != a_signed[31]);
            end
            SUBU: begin
                {carry, res} = {1'b0, a} - {1'b0, b};
                overflow = 1'b0;
            end
            AND: begin
                res = a & b;
                {carry, overflow} = 2'b00;
            end
            OR: begin
                res = a | b;
                {carry, overflow} = 2'b00;
            end
            XOR: begin
                res = a ^ b;
                {carry, overflow} = 2'b00;
            end
            NOR: begin
                res = ~(a | b);
                {carry, overflow} = 2'b00;
            end
            SLT: begin
                res = (a_signed < b_signed) ? 32'b1 : 32'b0;
                {carry, overflow} = 2'b00;
            end
            SLTU: begin
                res = (a < b) ? 32'b1 : 32'b0;
                {carry, overflow} = 2'b00;
            end
            SLL: begin
                res = a << b[4:0];
                {carry, overflow} = 2'b00;
            end
            SRL: begin
                res = a >> b[4:0];
                {carry, overflow} = 2'b00;
            end
            SRA: begin
                res = $signed(a) >>> b[4:0];
                {carry, overflow} = 2'b00;
            end
            SLLV: begin
                res = a << b[4:0];
                {carry, overflow} = 2'b00;
            end
            SRLV: begin
                res = a >> b[4:0];
                {carry, overflow} = 2'b00;
            end
            SRAV: begin
                res = $signed(a) >>> b[4:0];
                {carry, overflow} = 2'b00;
            end
            LUI: begin
                res = {a[15:0], 16'b0};
                {carry, overflow} = 2'b00;
            end
            default: begin
                res = 32'bz;
                {carry, overflow} = 2'b00;
            end
        endcase
        r = res;
    end
endmodule

