module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] abs_dividend, abs_divisor;
reg [15:0] SR;
reg [3:0] cnt;
reg start_cnt;
reg [7:0] NEG_DIVISOR;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        cnt <= 0;
        start_cnt <= 0;
        result <= 0;
        SR <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        NEG_DIVISOR <= 0;
    end else begin
        if (opn_valid && !res_valid && !start_cnt) begin

            if (sign) begin
                abs_dividend <= dividend[7] ? (~dividend + 8'd1) : dividend;
                abs_divisor <= divisor[7] ? (~divisor + 8'd1) : divisor;
            end else begin
                abs_dividend <= dividend;
                abs_divisor <= divisor;
            end
            NEG_DIVISOR <= -abs_divisor;

            SR <= {abs_dividend, 8'b0} << 1;

            cnt <= 4'd1;
            start_cnt <= 1;
            res_valid <= 0;
        end else if (start_cnt) begin
            if (cnt < 8) begin

                if (SR[15:8] >= abs_divisor) begin 
                    SR[15:8] <= SR[15:8] - abs_divisor;
                    SR[0] <= 1'b1;

                end else begin
                    SR[0] <= 1'b0;
                end
                SR <= SR << 1;

                cnt <= cnt + 1;
            end else begin

                result <= {SR[15:8], SR[7:0]};
                res_valid <= 1;
                start_cnt <= 0;
                cnt <= 0;
            end
        end else begin
            res_valid <= 0;
        end
    end
end

endmodule

