module fixed_point_subtractor #(
    parameter Q = 8,
    parameter N = 16
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);
    reg [N-1:0] res;
    reg res_sign;
    reg [N-1:0] res_val;
    wire sign_a, sign_b;
    wire same_sign;
    reg [N-1:0] abs_a, abs_b;

    assign sign_a = a[N-1];
    assign sign_b = b[N-1];
    assign same_sign = (sign_a == sign_b);


    always @* begin
        abs_a = sign_a ? (~a + 1) : a;
        abs_b = sign_b ? (~b + 1) : b;
    end


    always @* begin
        if (same_sign) begin
            res_val = a - b;
            res_sign = sign_a;
        end else begin
            res_val = abs_a - abs_b;
            if (abs_a > abs_b)
                res_sign = (sign_a) ? 1'b1 : 1'b0;
            else
                res_sign = (sign_a) ? 1'b0 : 1'b1;
        end


        if (res_val == 0)
            res_sign = 0;
    end


    always @* begin
        res = {res_sign, res_val[N-2:0]};
    end


    assign c = res;

endmodule

