module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa, product, product_shifted;
    reg guard_bit, round_bit, sticky;
    reg [23:0] z_mantissa;
    reg overflow, round_up;
    reg [23:0] mantissa_part;
    reg shift_flag;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 1'b0;
            b_sign <= 1'b0;
            z_sign <= 1'b0;
            a_exponent <= 8'b0;
            b_exponent <= 8'b0;
            z_exponent <= 8'b0;
            a_mantissa <= 24'b0;
            b_mantissa <= 24'b0;
            product <= 48'b0;
            product_shifted <= 48'b0;
            guard_bit <= 1'b0;
            round_bit <= 1'b0;
            sticky <= 1'b0;
            z_mantissa <= 24'b0;
            overflow <= 1'b0;
            round_up <= 1'b0;
            mantissa_part <= 24'b0;
            shift_flag <= 1'b0;
        end else begin
            case (counter)
                3'b000: begin 
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};
                    counter <= 3'b001;
                end
                3'b001: begin 
                    if ((a_exponent == 8'hff && a_mantissa != 0) || 
                        (b_exponent == 8'hff && b_mantissa != 0)) begin
                        z <= {1'b0, 8'hff, 23'h1};

                    end else if (a_exponent == 8'hff || b_exponent == 8'hff) begin
                        if ((a_exponent == 8'hff && b_exponent == 8'hff) ||
                            ((a_exponent == 8'hff && b_mantissa == 0) ||
                            (b_exponent == 8'hff && a_mantissa == 0))) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};

                        end else begin
                            z <= {a_sign ^ b_sign, 8'h0, 23'h0};

                        end
                    end else if (a_exponent == 0 && a_mantissa == 0) begin
                        if (b_exponent == 0 && b_mantissa == 0) begin
                            z <= {1'b0, 8'hff, 23'h1};

                        end else begin
                            z <= {a_sign ^ b_sign, 8'h0, 23'h0};

                        end
                    end else if (b_exponent == 0 && b_mantissa == 0) begin
                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};

                    end else begin
                        product <= a_mantissa * b_mantissa;
                        counter <= 3'b010;
                    end
                end
                3'b010: begin 
                    if (product[47]) begin
                        product_shifted <= product >> 1;
                        z_exponent <= a_exponent + b_exponent - 127 + 1;
                        shift_flag <= 1'b1;
                    end else begin
                        product_shifted <= product;
                        z_exponent <= a_exponent + b_exponent - 127;
                        shift_flag <= 1'b0;
                    end
                    counter <= 3'b011;
                end
                3'b011: begin 
                    if (shift_flag) begin
                        mantissa_part <= product_shifted[46:23];
                        guard_bit <= product_shifted[22];
                        round_bit <= product_shifted[21];
                        sticky <= |product_shifted[20:0];
                    end else begin
                        mantissa_part <= product_shifted[47:24];
                        guard_bit <= product_shifted[23];
                        round_bit <= product_shifted[22];
                        sticky <= |product_shifted[21:0];
                    end
                    counter <= 3'b100;
                end
                3'b100: begin 
                    round_up = guard_bit & (round_bit | sticky);
                    z_mantissa = mantissa_part + round_up;
                    overflow = z_mantissa[23];
                    counter <= 3'b101;
                end
                3'b101: begin 
                    if (overflow) begin
                        z_mantissa = z_mantissa >> 1;
                        z_exponent <= z_exponent + 1;
                    end
                    if (z_exponent >= 255) begin
                        z <= {z_sign, 8'hff, 23'h0};

                    end else if (z_exponent <= 0) begin
                        z <= {z_sign, 24'h0};

                    end else begin
                        z <= {z_sign, z_exponent, z_mantissa[22:0]};
                    end
                    counter <= 3'b111;
                end
                default: counter <= 3'b0;
            endcase
        end
    end
