module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] current_state, next_state;
parameter IDLE = 2'b00,
          FIRST = 2'b01,
          PULSE_END = 2'b10;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        current_state <= IDLE;
    end else begin
        current_state <= next_state;
    end
end


always @* begin
    case (current_state)
        IDLE: next_state = data_in ? FIRST : IDLE;
        FIRST: next_state = data_in ? IDLE : PULSE_END;
        PULSE_END: next_state = IDLE;
        default: next_state = IDLE;
    endcase
    data_out = (next_state == PULSE_END);
end

endmodule

