module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);
    parameter idle = 2'b00,
              s1_red = 2'b01,
              s2_yellow = 2'b10,
              s3_green = 2'b11;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) state <= idle;
        else state <= next_state;
    end


    always @(*) begin
        case (state)
            idle:    next_state = s1_red;
            s1_red:  next_state = (cnt == 3) ? s3_green : s1_red;
            s3_green: next_state = (cnt == 60) ? s2_yellow : s3_green;
            s2_yellow: next_state = (cnt == 3) ? s1_red : s2_yellow;
            default: next_state = idle;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) cnt <= 8'd10;
        else begin
            if (pass_request && green) cnt <= 8'd10;
            else if (!green && p_green) cnt <= 8'd60;
            else if (!yellow && p_yellow) cnt <= 8'd5;
            else if (!red && p_red) cnt <= 8'd10;
            else cnt <= cnt - 8'd1;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) {p_red, p_yellow, p_green} <= 3'b0;
        else {p_red, p_yellow, p_green} <= {red, yellow, green};
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) {red, yellow, green} <= 3'b0;
        else {red, yellow, green} <= {p_red, p_yellow, p_green};
    end


    assign clock = cnt;
endmodule

