module width_8to16 (
    input clk,
    input rst_n,
    input valid_in,
    input [7:0] data_in,
    output reg valid_out,
    output reg [15:0] data_out
);

reg [7:0] data_lock_reg;
reg [15:0] next_data_out;
reg need_output;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data_lock_reg <= 8'b0;
        next_data_out <= 16'b0;
        need_output <= 1'b0;
        valid_out <= 1'b0;
        data_out <= 16'b0;
    end else begin

        if (valid_in) begin
            if (data_lock_reg != 8'b0) begin

                next_data_out <= {data_lock_reg, data_in};
                need_output <= 1'b1;
                data_lock_reg <= 8'b0;

            end else begin

                data_lock_reg <= data_in;
                need_output <= 1'b0;
            end
        end else begin
            need_output <= 1'b0;

        end


        valid_out <= need_output;
        data_out <= next_data_out;
    end
end

endmodule

