    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] abs_dividend, abs_divisor;
    reg [8:0] SR_upper;

    reg [7:0] SR_lower;

    reg [3:0] cnt;

    reg start_cnt;
    reg [8:0] NEG_DIVISOR;


    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            cnt <= 0;
            start_cnt <= 0;
            SR_upper <= 0;
            SR_lower <= 0;
            NEG_DIVISOR <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;

                SR_upper <= {abs_dividend, 1'b0};
                SR_lower <= 0;
                NEG_DIVISOR <= -abs_divisor;

                cnt <= 4'd1;
                start_cnt <= 1;
                res_valid <= 0;
