                        SR_upper <= SR_upper - NEG_DIVISOR;
                        SR_lower <= {SR_lower[6:0], 1'b1};
                    end else begin
                        SR_upper <= SR_upper;
                        SR_lower <= {SR_lower[6:0], 1'b0};
                    end

                    SR_upper <= SR_upper << 1;
                    SR_lower <= SR_lower << 1;
                    cnt <= cnt + 1;
                end
            end else if (res_valid) begin
                res_valid <= 0;
            end
        end
    end
