module multi_16bit (
    input clk,
    input rst_n,
    input start,
    input [15:0] ain,
    input [15:0] bin,
    output reg [31:0] yout,
    output reg done
);
reg [4:0] i;
reg [15:0] areg;
reg [15:0] breg;
reg [31:0] yout_r;
reg done_r;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        i <= 5'd0;
        done_r <= 1'b0;
        areg <= 16'd0;
        breg <= 16'd0;
        yout_r <= 32'd0;
        done <= 1'b0;
        yout <= 32'd0;
    end else begin

        if (start && (i < 17))
            i <= i + 5'd1;
        else
            i <= 5'd0;


        if (i == 16)
            done_r <= 1'b1;
        else if (i == 17)
            done_r <= 1'b0;
        else
            done_r <= done_r;


        if ((i > 0) && (i < 17)) begin
            if (areg[i-1])
                yout_r <= yout_r + (breg << (i-1));
        end


        if (i == 0 && start) begin
            areg <= ain;
            breg <= bin;
        end


        done <= done_r;
        yout <= yout_r;
    end
end

endmodule

