module fixed_point_subtractor #(parameter Q=2, N=4) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);
    reg [N-1:0] res;
    reg res_sign, res_mag [N-2:0];


    wire sign_a, sign_b;
    wire [N-2:0] mag_a, mag_b;
    wire [ (N-1 - Q) -1 : 0 ] int_a, int_b;
    wire [ Q-1 : 0 ] frac_a, frac_b;
    reg [ (N-1 - Q) -1 : 0 ] int_diff;
    reg [ Q-1 : 0 ] frac_diff;
    reg borrow;
    reg [N-2:0] new_mag;

    assign sign_a = a[N-1];
    assign mag_a = a[N-2:0];
    assign sign_b = b[N-1];
    assign mag_b = b[N-2:0];

    always @(*) begin
        if (sign_a == sign_b) begin

            int_a = mag_a >> Q;
            frac_a = mag_a & ((1 << Q) - 1);
            int_b = mag_b >> Q;
            frac_b = mag_b & ((1 << Q) - 1);


            int_diff = int_a - int_b;


            if (frac_a >= frac_b) begin
                frac_diff = frac_a - frac_b;
                borrow = 0;
            end else begin
                frac_diff = frac_a + (1 << Q) - frac_b;
                int_diff = int_diff - 1;
                borrow = 1;
            end


            if (int_diff + borrow < 0) begin
                new_mag = 0;
            end else begin
                new_mag = (int_diff << Q) | frac_diff;
            end


            res_sign = (new_mag == 0) ? 1'b0 : sign_a;
        end else begin

            new_mag = mag_a + mag_b;
            if (mag_a > mag_b)
                res_sign = sign_a;
            else
                res_sign = ~sign_a;

        end

        res = {res_sign, new_mag};
        c = res;
    end
endmodule

