module float_multi (
    input wire clk,
    input wire rst,
    input wire [31:0] a,
    input wire [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, sum_exponent, z_exponent;
    reg [22:0] a_mantissa_stored, b_mantissa_stored;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;
    reg overflow;
    reg [7:0] new_exponent;
    reg [23:0] rounded_mantissa;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 0;
            b_sign <= 0;
            z_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            sum_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            product <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
            new_exponent <= 0;
            rounded_mantissa <= 0;
        end else begin
            case (counter)

                3'b000: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa_stored <= a[22:0];
                    b_mantissa_stored <= b[22:0];
                    counter <= 3'b001;
                end


                3'b001: begin

                    if ((a_exponent == 8'hFF) && (a_mantissa_stored != 0)) begin
                        z <= {1'b0, 8'hFF, 23'h1};
                        counter <= 3'b111;
                    end else if ((b_exponent == 8'hFF) && (b_mantissa_stored != 0)) begin
                        z <= {1'b0, 8'hFF, 23'h1};
                        counter <= 3'b111;
                    end

                    else if ((a_exponent == 8'hFF) && (a_mantissa_stored == 0)) begin
                        if ((b_exponent == 8'hFF) && (b_mantissa_stored == 0)) begin
                            z <= {1'b0, 8'hFF, 23'h1};
                            counter <= 3'b111;
                        end else begin
                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 8'hFF;
                            z_mantissa <= 0;
                            counter <= 3'b111;
                        end
                    end else if ((b_exponent == 8'hFF) && (b_mantissa_stored == 0)) begin
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 8'hFF;
                        z_mantissa <= 0;
                        counter <= 3'b111;
                    end

                    else if ((a_exponent == 0) && (a_mantissa_stored == 0)) begin
                        counter <= 3'b111;
                    end else if ((b_exponent == 0) && (b_mantissa_stored == 0)) begin
                        counter <= 3'b111;
                    end

                    else begin
                        a_mantissa <= (a_exponent != 0) ? {1'b1, a_mantissa_stored} : {1'b0, a_mantissa_stored};
                        b_mantissa <= (b_exponent != 0) ? {1'b1, b_mantissa_stored} : {1'b0, b_mantissa_stored};
                        sum_exponent <= (a_exponent + b_exponent) - 8'd127;
                        counter <= 3'b010;
                    end
                end


                3'b010: begin
                    product <= a_mantissa * b_mantissa;
                    counter <= 3'b011;
                end


                3'b011: begin
                    if (product[47]) begin
                        product <= product >> 1;
                        sum_exponent <= sum_exponent + 1;
                    end
                    guard_bit <= product[23];
                    round_bit <= product[22];
                    sticky <= |product[21:0];
                    counter <= 3'b100;
                end


                3'b100: begin
                    rounded_mantissa = product[46:24] + (guard_bit & (round_bit | sticky));
                    if (guard_bit & (round_bit | sticky)) begin
                        rounded_mantissa = rounded_mantissa + 1;
                        if (rounded_mantissa[23])
                            rounded_mantissa = 0;
                    end
                    new_exponent = sum_exponent;
                    if (rounded_mantissa[23])
                        new_exponent = sum_exponent + 1;
                    if (new_exponent >= 8'hFE) begin
                        z <= {z_sign, 8'hFF, 23'h0};
                    end else if (new_exponent == 0) begin
                        z <= {z_sign, 8'h0, 23'h0};
                    end else begin
                        z <= {z_sign, new_exponent, rounded_mantissa[22:0]};
                    end
                    counter <= 3'b111;
                end

                default: begin
                    counter <= 3'b000;
                end
            endcase
        end
    end
endmodule

