module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire rclk,
    input wire wrstn,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output reg rempty,
    output reg wfull,
    output reg [WIDTH-1:0] rdata
);

localparam ADDR_WIDTH = $clog2(DEPTH);
localparam PTR_WIDTH = ADDR_WIDTH + 1;


reg [PTR_WIDTH-1:0] wptr_bin, rptr_bin;
reg [PTR_WIDTH-1:0] wptr_gray, rptr_gray;


reg [PTR_WIDTH-1:0] wptr_gray_sync_rclk [1:0];
reg [PTR_WIDTH-1:0] rptr_gray_sync_wclk [1:0];


wire [ADDR_WIDTH-1:0] waddr_bin = wptr_bin[ADDR_WIDTH-1:0];
wire [ADDR_WIDTH-1:0] raddr_bin = rptr_bin[ADDR_WIDTH-1:0];


wire wen = winc && !wfull;
wire ren = rinc && !rempty;
wire [ADDR_WIDTH-1:0] waddr = waddr_bin;
wire [ADDR_WIDTH-1:0] raddr = raddr_bin;


dual_port_RAM #(
    .DEPTH(DEPTH),
    .WIDTH(WIDTH)
) ram (
    .wclk(wclk),
    .wenc(wen),
    .waddr(waddr),
    .wdata(wdata),
    .rclk(rclk),
    .renc(ren),
    .raddr(raddr),
    .rdata(rdata)
);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_bin <= 0;
        wptr_gray <= 0;
        wptr_gray_sync_rclk[0] <= 0;
        wptr_gray_sync_rclk[1] <= 0;
    end else begin
        if (wen) wptr_bin <= wptr_bin + 1;
        wptr_gray <= (wptr_bin >> 1) ^ wptr_bin;
        wptr_gray_sync_rclk[0] <= wptr_gray;
        wptr_gray_sync_rclk[1] <= wptr_gray_sync_rclk[0];
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_bin <= 0;
        rptr_gray <= 0;
        rptr_gray_sync_wclk[0] <= 0;
        rptr_gray_sync_wclk[1] <= 0;
    end else begin
        if (ren) rptr_bin <= rptr_bin + 1;
        rptr_gray <= (rptr_bin >> 1) ^ rptr_bin;
        rptr_gray_sync_wclk[0] <= rptr_gray;
        rptr_gray_sync_wclk[1] <= rptr_gray_sync_wclk[0];
    end
end


wire [PTR_WIDTH-1:0] rptr_gray_sync = rptr_gray_sync_wclk[1];
wire [PTR_WIDTH-1:0] wptr_gray_sync = wptr_gray_sync_rclk[1];

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) rempty <= 1'b1;
    else rempty <= (rptr_bin == wptr_gray_sync);
end

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) wfull <= 1'b0;
    else begin
        wfull <= (wptr_gray[PTR_WIDTH-1] != rptr_gray_sync[PTR_WIDTH-1]) &&
                (wptr_gray[PTR_WIDTH-2] != rptr_gray_sync[PTR_WIDTH-2]) &&
                (wptr_gray[PTR_WIDTH-3:0] == rptr_gray_sync[PTR_WIDTH-3:0]);
    end
end

endmodule

module dual_port_RAM #(
    parameter DEPTH = 16,
    parameter WIDTH = 8
) (
    input wire wclk,
    input wire wenc,
    input wire [$clog2(DEPTH)-1:0] waddr,
    input wire [WIDTH-1:0] wdata,
    input wire rclk,
    input wire renc,
    input wire [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
    if (wenc) RAM_MEM[waddr] <= wdata;
end

always @(posedge rclk) begin
    if (renc) rdata <= RAM_MEM[raddr];
end

endmodule

