module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [2:0] SP;

reg [3:0] stack_mem [0:3];


always @(posedge Clk) begin
    if (EN) begin
        if (Rst) begin

            SP <= 3'd4;
            stack_mem[0] <= 4'd0;
            stack_mem[1] <= 4'd0;
            stack_mem[2] <= 4'd0;
            stack_mem[3] <= 4'd0;
            dataOut <= 4'd0;
            EMPTY <= 1'b1;
            FULL <= 1'b0;
        end else begin
            if (!FULL && !RW) begin 
                stack_mem[SP - 1] <= dataIn;

                SP <= SP - 1;
                EMPTY <= (SP - 1 == 3'd4) ? 1'b1 : 1'b0;

                FULL <= (SP - 1 == 3'd0) ? 1'b1 : 1'b0;
            end else if (!EMPTY && RW) begin 
                dataOut <= stack_mem[SP];

                stack_mem[SP] <= 4'd0;

                SP <= SP + 1;
                EMPTY <= (SP + 1 == 3'd4) ? 1'b1 : 1'b0;

                FULL <= 1'b0;
            end
        end
    end
end

endmodule

