    reg r_red, r_yellow, r_green;

    assign clock = cnt;
    assign red = r_red;
    assign yellow = r_yellow;
    assign green = r_green;


    always @* begin
        case(state)
            idle: state_next = s1_red;
            s1_red: state_next = (cnt == 0) ? s3_green : s1_red;
            s2_yellow: state_next = (cnt == 0) ? s1_red : s2_yellow;
            s3_green: state_next = (cnt == 0) ? s2_yellow : s3_green;
            default: state_next = idle;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
