                cnt <= 10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            r_red <= 0;
            r_yellow <= 0;
            r_green <= 0;
        end else begin
            r_red <= p_red;
            r_yellow <= p_yellow;
            r_green <= p_green;
        end
    end

