module alu (a, b, aluc, r, zero, carry, negative, overflow, flag);
input [31:0] a, b;
input [5:0] aluc;
output reg [31:0] r;
output zero, carry, negative, overflow;
output reg flag;


parameter ADD = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND = 6'b100100;
parameter OR = 6'b100101;
parameter XOR = 6'b100110;
parameter NOR = 6'b100111;
parameter SLT = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL = 6'b000000;
parameter SRL = 6'b000010;
parameter SRA = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI = 6'b001111;

reg [31:0] slt_result, sltu_result;
reg carry_reg, overflow_reg;


assign zero = (r == 32'b0);


assign negative = r[31];


assign overflow = overflow_reg;


assign carry = carry_reg;


wire flag_value = (aluc == SLT) ? slt_result :
                  (aluc == SLTU) ? sltu_result :
                  1'bz;
assign flag = flag_value;


always @(*) begin
    slt_result = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
    sltu_result = (a < b) ? 32'd1 : 32'd0;
end


always @(*) begin
    case (aluc)
        ADD: begin
            {carry_reg, r} = a + b;
            overflow_reg = (a[31] & b[31] & ~r[31]) | (~a[31] & ~b[31] & r[31]);
        end
        ADDU: begin
            {carry_reg, r} = a + b;
            overflow_reg = 1'b0;
        end
        SUB: begin
            {carry_reg, r} = a - b;
            overflow_reg = (a[31] & ~b[31] & ~r[31]) | (~a[31] & b[31] & r[31]);
        end
        SUBU: begin
            {carry_reg, r} = a - b;
            overflow_reg = 1'b0;
        end
        AND: begin
            r = a & b;
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        OR: begin
            r = a | b;
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        XOR: begin
            r = a ^ b;
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        NOR: begin
            r = ~(a | b);
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SLT: begin
            r = slt_result;
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SLTU: begin
            r = sltu_result;
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SLL: begin
            r = b << a[4:0];
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SRL: begin
            r = b >> a[4:0];
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SRA: begin
            r = $signed(b) >>> a[4:0];
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SLLV: begin
            r = b << a[4:0];
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SRLV: begin
            r = b >> a[4:0];
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        SRAV: begin
            r = $signed(b) >>> a[4:0];
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        LUI: begin
            r = {a[15:0], 16'b0};
            carry_reg = 1'b0;
            overflow_reg = 1'b0;
        end
        default: begin
            r = 32'bz;
            carry_reg = 1'bz;
            overflow_reg = 1'bz;
        end
    endcase
end

endmodule

