module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] dividend_reg, divisor_reg;
    reg [7:0] abs_dividend, abs_divisor;
    reg [8:0] NEG_DIVISOR;
    reg [8:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [15:0] result_reg;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            cnt <= 0;
            start_cnt <= 0;
            dividend_reg <= 0;
            divisor_reg <= 0;
            SR <= 0;
            result_reg <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                dividend_reg <= dividend;
                divisor_reg <= divisor;
                abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                NEG_DIVISOR <= -{1'b0, abs_divisor};
                SR <= {abs_dividend, 1'b0};
                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt == 8) begin

                    result_reg <= {SR[8:1], {8{1'b0}}};
                    cnt <= 0;
                    start_cnt <= 0;
                    res_valid <= 1;
                end else begin

                    if (SR >= NEG_DIVISOR) begin
                        SR <= (SR - NEG_DIVISOR) << 1 | 1'b1;
                    end else begin
                        SR <= SR << 1;
                    end
                    cnt <= cnt + 1;
                end
            end
        end
        result <= result_reg;
        if (res_valid && opn_valid) begin
            res_valid <= 0;
        end
    end
endmodule

