module div_16bit(A, B, result, odd);
input [15:0] A, B;
output reg [15:0] result, odd;

reg [15:0] a_reg, b_reg;

always @(*) begin
    a_reg = A;
    b_reg = B;
end

always @(*) begin
    reg [7:0] remainder;

    reg [15:0] quotient;
    remainder = 8'b0;
    quotient = 16'b0;
    for (int i = 15;
 i >= 0;
 i = i - 1) begin
        remainder = {remainder[6:0], a_reg[i]};

        if (remainder >= b_reg) begin
            remainder = remainder - b_reg;
            quotient[i] = 1'b1;
        end else begin
            quotient[i] = 1'b0;
        end
    end
    result = quotient;
    odd = {8'b0, remainder};

end

endmodule

