module fixed_point_adder #(parameter Q=4, N=8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire same_sign;
    wire [N-1:0] abs_a, abs_b;


    assign same_sign = (a[N-1] == b[N-1]);


    assign abs_a = a[N-1] ? (~a + 1) : a;
    assign abs_b = b[N-1] ? (~b + 1) : b;

    always @* begin
        if (same_sign) begin

            res = abs_a + abs_b;
            res[N-1] = a[N-1];
        end else begin

            if (abs_a > abs_b) begin
                res = a - b;
            end else if (abs_b > abs_a) begin
                res = b - a;
            end else begin
                res = 0;
            end

            res[N-1] = 1'b0;
        end
    end

    assign c = res;

endmodule

