module fixed_point_subtractor #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire [N-1:0] a_abs = a_sign ? (~a + 1) : a;
    wire [N-1:0] b_abs = b_sign ? (~b + 1) : b;
    reg [N-2:0] res_magnitude;
    reg res_sign;
    reg [N-1:0] res;

    always @* begin
        if (a_sign == b_sign) begin
            if (a_abs >= b_abs) begin
                res_magnitude = a_abs - b_abs;
                res_sign = a_sign;
            end else begin
                res_magnitude = b_abs - a_abs;
                res_sign = a_sign;
            end
        end else begin
            res_magnitude = a_abs + b_abs;
            res_sign = (a_abs >= b_abs) ? a_sign : b_sign;
        end

        if (res_magnitude == 0)
            res_sign = 0;

        res = {res_sign, res_magnitude};
    end

    assign c = res;
endmodule

