module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);


localparam STATE0 = 2'b00;
localparam STATE1 = 2'b01;
localparam STATE2 = 2'b10;

reg [1:0] current_state, next_state;


always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        current_state <= STATE0;
    end else begin
        current_state <= next_state;
    end
end


always @(*) begin
    if (~rst_n)
        data_out = 1'b0;
    else
        case (current_state)
            STATE2: data_out = 1'b1;
            default: data_out = 1'b0;
        endcase
end


always @(*) begin
    case (current_state)
        STATE0: begin
            if (data_in)
                next_state = STATE1;
            else
                next_state = STATE0;
        end
        STATE1: begin
            if (data_in)
                next_state = STATE1;
            else
                next_state = STATE2;
        end
        STATE2: begin
            next_state = STATE0;
        end
        default: next_state = STATE0;
    endcase
end

endmodule

