module alu(
    input [31:0] a, b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero, negative,
    output wire carry, overflow, flag
);
    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg [32:0] res_temp;
    reg [31:0] temp;
    reg carry_add, carry_sub, overflow_add, overflow_sub;

    always @(*) begin
        case (aluc)
            ADD: begin
                temp = a + b;
                res_temp = {1'b0, temp};
                r = temp;
                overflow_add = ((a[31] & b[31] & ~temp[31]) | (~a[31] & ~b[31] & temp[31]));
                carry_add = res_temp[32];
            end
            ADDU: begin
                temp = a + b;
                res_temp = {1'b0, temp};
                r = temp;
                overflow_add = 1'b0;
                carry_add = res_temp[32];
            end
            SUB: begin
                temp = a - b;
                res_temp = {1'b0, temp};
                r = temp;
                overflow_sub = ((a[31] != b[31]) && (temp[31] != a[31]));
                carry_sub = res_temp[32];
            end
            SUBU: begin
                temp = a - b;
                r = temp;
                overflow_sub = 1'b0;
                carry_sub = (a >= b) ? 1'b1 : 1'b0;
            end
            AND: begin
                r = a & b;
                overflow_add = 1'b0;
                carry_add = 1'b0;
            end
            OR: begin
                r = a | b;
                overflow_add = 1'b0;
                carry_add = 1'b0;
            end
            XOR: begin
                r = a ^ b;
                overflow_add = 1'b0;
                carry_add = 1'b0;
            end
            NOR: begin
                r = ~(a | b);
                overflow_add = 1'b0;
                carry_add = 1'b0;
            end
            SLT: begin
                r = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                overflow_add = 1'b0;
                carry_add = 1'b0;
            end
            SLTU: begin
                r = (a < b) ? 32'd1 : 32'd0;
                overflow_add = 1'b0;
                carry_add = 1'b0;
            end
            SLL: begin
                r = b << a[4:0];
                overflow_add = 1'b0;
                carry_add = 1'b0;
            end
            SRL: begin
                r = b >> a[4:0];
                overflow_add = 1'b0;
                carry_add = 1'b0;
            end
            SRA: begin
                r = $signed(b) >>> a[4:0];
                overflow_add = 1'b0;
                carry_add = 1'b0;
            end
            SLLV: begin
                r = b << a[4:0];
                overflow_add = 1'b0;
                carry_add = 1'b0;
            end
            SRLV: begin
                r = b >> a[4:0];
                overflow_add = 1'b0;
                carry_add = 1'b0;
            end
            SRAV: begin
                r = $signed(b) >>> a[4:0];
                overflow_add = 1'b0;
                carry_add = 1'b0;
            end
            LUI: begin
                r = {a[15:0], 16'b0};
                overflow_add = 1'b0;
                carry_add = 1'b0;
            end
            default: begin
                r = 32'bz;
                overflow_add = 1'b0;
                carry_add = 1'b0;
            end
        endcase
    end

    assign zero = (r == 32'b0);
    assign negative = r[31];
    assign carry = (aluc == ADD || aluc == ADDU) ? carry_add :
                   (aluc == SUB || aluc == SUBU) ? carry_sub : 1'b0;
    assign overflow = (aluc == ADD) ? overflow_add :
                     (aluc == SUB) ? overflow_sub : 1'b0;
    assign flag = (aluc == SLT || aluc == SLTU) ? r[0] : 1'bz;

endmodule

