module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] dividend_abs;
    reg [7:0] divisor_abs;
    reg sign_dividend;
    reg sign_divisor;
    reg [16:0] SR;

    reg [7:0] NEG_DIVISOR;
    reg [7:0] remainder_abs;
    reg [7:0] quotient_abs;
    reg [7:0] remainder;
    reg [7:0] quotient;
    wire [8:0] temp_remainder;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            start_cnt <= 0;
            cnt <= 0;
            SR <= 0;
            NEG_DIVISOR <= 0;
            dividend_abs <= 0;
            divisor_abs <= 0;
            sign_dividend <= 0;
            sign_divisor <= 0;
            remainder <= 0;
            quotient <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                sign_dividend <= sign ? dividend[7] : 1'b0;
                sign_divisor <= sign ? divisor[7] : 1'b0;
                dividend_abs <= (sign && dividend[7]) ? -dividend : dividend;
                divisor_abs <= (sign && divisor[7]) ? -divisor : divisor;
                NEG_DIVISOR <= -{(divisor_abs[7] ? 1'b1 : 1'b0), divisor_abs};
                SR <= {dividend_abs, 1'b0} << 1;

                start_cnt <= 1;
                cnt <= 1;
            end else if (start_cnt) begin
                temp_remainder = SR[16:8] - NEG_DIVISOR;
                if (cnt == 8) begin

                    start_cnt <= 0;
                    remainder_abs <= (temp_remainder[8] == 0) ? temp_remainder[7:0] : SR[16:8];
                    quotient_abs <= SR[7:0];
                    res_valid <= 1;
                end else begin
                    if (temp_remainder[8] == 0) begin
                        SR[16:8] <= temp_remainder[7:0];
                        SR[0] <= 1;
                    end else begin
                        SR[0] <= 0;
                    end
                    SR <= SR << 1;
                    cnt <= cnt + 1;
                end
            end else if (res_valid) begin
                res_valid <= 0;
            end
        end
    end

    always @(*) begin
        if (sign) begin
            remainder = sign_dividend ? remainder_abs : -remainder_abs;
            quotient = (sign_dividend ^ sign_divisor) ? -quotient_abs : quotient_abs;
        end else begin
            remainder = remainder_abs;
            quotient = quotient_abs;
        end
    end

    always @(posedge clk) begin
        if (start_cnt && !res_valid) begin
            result <= {remainder, quotient};
        end
    end
endmodule

