module div_16bit(A, B, result, odd);
input [15:0] A;
input [7:0] B;
output reg [15:0] result;
output reg [15:0] odd;

reg [15:0] a_reg;
reg [7:0] b_reg;


always @(A, B) begin
    a_reg = A;
    b_reg = B;
end


always @(a_reg, b_reg) begin
    reg [15:0] remainder;
    reg [15:0] quotient;
    integer i;

    remainder = {8'b0, a_reg[15:8]};

    quotient = 16'b0;

    for (i = 0;
 i < 16;
 i = i + 1) begin

        remainder = {remainder[14:0], a_reg[7 - i]};
        if (remainder >= {1'b0, b_reg}) begin
            quotient[15 - i] = 1'b1;
            remainder = remainder - {1'b0, b_reg};
        end else begin
            quotient[15 - i] = 1'b0;
        end
    end


    result = quotient;
    odd = remainder;
end

endmodule

