module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [8:0] a_exponent, b_exponent, z_exponent;
reg [23:0] a_mantissa, b_mantissa, z_mantissa;
reg [49:0] product;
reg guard_bit, round_bit, sticky;
reg [9:0] exp_sum;

wire is_nan_a, is_nan_b, is_nan_z, is_inf_a, is_inf_b;
wire is_zero;
reg [24:0] rounded_mantissa;

always @(*) begin
    is_nan_a = (a_exponent == 9'h1FF) && (a_mantissa != 0);
    is_nan_b = (b_exponent == 9'h1FF) && (b_mantissa != 0);
    is_nan_z = is_nan_a || is_nan_b;

    is_inf_a = (a_exponent == 9'h1FF) && (a_mantissa == 0);
    is_inf_b = (b_exponent == 9'h1FF) && (b_mantissa == 0);

    is_zero = (a_mantissa == 0 && a_exponent == 0) || (b_mantissa == 0 && b_exponent == 0);
end

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
        a_sign <= 0;
        b_sign <= 0;
        a_exponent <= 0;
        b_exponent <= 0;
        a_mantissa <= 0;
        b_mantissa <= 0;
        product <= 0;
        guard_bit <= 0;
        round_bit <= 0;
        sticky <= 0;
        z_sign <= 0;
        z_exponent <= 0;
        z_mantissa <= 0;
        exp_sum <= 0;
    end else begin
        case (counter)
            3'd0: begin
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= {1'b0, a[30:23]};
                b_exponent <= {1'b0, b[30:23]};

                if (a[30:23] != 8'b0)
                    a_mantissa <= {1'b1, a[22:0]};
                else
                    a_mantissa <= {1'b0, a[22:0]};

                if (b[30:23] != 8'b0)
                    b_mantissa <= {1'b1, b[22:0]};
                else
                    b_mantissa <= {1'b0, b[22:0]};

                exp_sum <= a_exponent + b_exponent - 9'd127;
                counter <= counter + 1;
            end

            3'd1: begin
                if (is_nan_z) begin
                    z_exponent <= 9'h1FF;
                    z_mantissa <= 24'h000001;
                    z_sign <= a_sign ^ b_sign;
                    z <= {z_sign, 8'hFF, 23'h1};
                    counter <= 3'd7;
                end else if ((is_inf_a && is_zero) || (is_inf_b && is_zero)) begin
                    z_exponent <= 9'h1FF;
                    z_mantissa <= 24'h000001;
                    z_sign <= a_sign ^ b_sign;
                    z <= {z_sign, 8'hFF, 23'h1};
                    counter <= 3'd7;
                end else if (is_inf_a || is_inf_b) begin
                    z_exponent <= exp_sum;
                    z_mantissa <= 0;
                    z_sign <= a_sign ^ b_sign;
                    z <= {z_sign, z_exponent[7:0], 23'b0};
                    counter <= 3'd7;
                end else if (is_zero) begin
                    z_exponent <= 0;
                    z_mantissa <= 0;
                    z_sign <= a_sign ^ b_sign;
                    z <= {z_sign, 8'b0, 23'b0};
                    counter <= 3'd7;
                end else begin
                    product <= a_mantissa * b_mantissa;
                    counter <= counter + 1;
                end
            end

            3'd2: begin

                integer i;
                reg [4:0] lz;
                lz = 0;
                for (i = 47;
 i >= 0;
 i = i - 1)
                    if (product[i]) break;
                    else lz = lz + 1;

                product <= product << lz;
                if (product[47]) begin
                    product <= product >> 1;
                    exp_sum <= exp_sum + 1;
                end

                guard_bit <= product[23];
                round_bit <= product[22];
                sticky <= |product[21:0];
                counter <= counter + 1;
            end

            3'd3: begin
                if (guard_bit && (round_bit || sticky)) begin
                    rounded_mantissa = {1'b0, product[46:24]} + 1;
                end else begin
                    rounded_mantissa = {1'b0, product[46:24]};
                end

                if (rounded_mantissa[23]) begin
                    z_mantissa <= rounded_mantissa[23:1];
                    exp_sum <= exp_sum + 1;
                end else begin
                    z_mantissa <= rounded_mantissa[22:0];
                end
                counter <= counter + 1;
            end

            3'd4: begin
                if (exp_sum >= 9'h1FF) begin
                    z_exponent <= 8'hFF;
                    z_mantissa <= 24'h0;
                end else if (exp_sum <= 9'h001) begin
                    z_exponent <= 8'h0;
                    z_mantissa <= 24'h0;
                end else begin
                    z_exponent <= exp_sum[7:0];
                end
                counter <= counter + 1;
            end

            3'd5: begin
                z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                counter <= 3'd7;
            end

            default: begin
                counter <= 3'd0;
            end
        endcase
    end
end

endmodule

