module asyn_fifo #(
  parameter WIDTH = 8,
  parameter DEPTH = 16
) (
  input wire wclk,
  input wire rclk,
  input wire wrstn,
  input wire rrstn,
  input wire winc,
  input wire rinc,
  input wire [WIDTH-1:0] wdata,
  output reg wfull,
  output reg rempty,
  output wire [WIDTH-1:0] rdata
);
  localparam ADDR_WIDTH = $clog2(DEPTH);
  wire [$clog2(DEPTH)-1:0] waddr, raddr;
  wire ram_wenc = winc && !wfull;
  wire ram_renc = rinc && !rempty;

  dual_port_RAM #(.DEPTH(DEPTH), .WIDTH(WIDTH)) ram (
    .wclk(wclk),
    .wenc(ram_wenc),
    .waddr(waddr),
    .wdata(wdata),
    .rclk(rclk),
    .renc(ram_renc),
    .raddr(raddr),
    .rdata(rdata)
  );

  reg [ADDR_WIDTH-1:0] waddr_bin, raddr_bin;
  reg [ADDR_WIDTH-1:0] wptr, rptr;
  reg [ADDR_WIDTH-1:0] wptr_gray, wptr_gray_sync1, wptr_gray_sync;
  reg [ADDR_WIDTH-1:0] rptr_gray, rptr_gray_sync1, rptr_gray_sync;


  always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
      waddr_bin <= 0;
      wptr <= 0;
      wptr_gray <= 0;
      wptr_gray_sync1 <= 0;
      wptr_gray_sync <= 0;
    end else begin
      if (ram_wenc) waddr_bin <= waddr_bin + 1;
      wptr <= waddr_bin ^ (waddr_bin >> 1);
      wptr_gray_sync1 <= wptr;
      wptr_gray_sync <= wptr_gray_sync1;
    end
  end


  always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
      raddr_bin <= 0;
      rptr <= 0;
      rptr_gray <= 0;
      rptr_gray_sync1 <= 0;
      rptr_gray_sync <= 0;
    end else begin
      if (ram_renc) raddr_bin <= raddr_bin + 1;
      rptr <= raddr_bin ^ (raddr_bin >> 1);
      rptr_gray_sync1 <= rptr;
      rptr_gray_sync <= rptr_gray_sync1;
    end
  end


  always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
      rptr_gray_sync1 <= 0;
      rptr_gray_sync <= 0;
    end else begin
      rptr_gray_sync1 <= rptr_gray;
      rptr_gray_sync <= rptr_gray_sync1;
    end
  end


  always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
      wptr_gray_sync1 <= 0;
      wptr_gray_sync <= 0;
    end else begin
      wptr_gray_sync1 <= wptr_gray;
      wptr_gray_sync <= wptr_gray_sync1;
    end
  end


  always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
      wfull <= 0;
    end else begin
      wfull <= (wptr_gray != rptr_gray_sync) && 
               (wptr_gray[ADDR_WIDTH-1] != rptr_gray_sync[ADDR_WIDTH-1]) &&
               (wptr_gray[ADDR_WIDTH-2] != rptr_gray_sync[ADDR_WIDTH-2]) &&
               (wptr_gray[ADDR_WIDTH-3:0] == rptr_gray_sync[ADDR_WIDTH-3:0]);
    end
  end

  always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
      rempty <= 1;
    end else begin
      rempty <= (rptr_gray == wptr_gray_sync);
    end
  end

  assign waddr = waddr_bin;
  assign raddr = raddr_bin;
endmodule

