module LIFObuffer(
    input wire [3:0] dataIn,
    input wire RW, 
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];

reg [3:0] SP;

integer i;

always @(posedge Clk) begin
    if (EN) begin
        if (Rst) begin

            SP <= 4;
            EMPTY <= 1;
            FULL <= 0;
            dataOut <= 0;
            for (i = 0;
 i < 4;
 i = i + 1)
                stack_mem[i] <= 0;
        end else begin
            reg [3:0] next_SP = SP;

            if (RW == 0) begin 
                if (!FULL) begin
                    stack_mem[next_SP] <= dataIn;
                    next_SP = next_SP + 1;
                end
            end else begin 
                if (!EMPTY) begin
                    dataOut <= stack_mem[next_SP - 1];
                    next_SP = next_SP - 1;
                end
            end
            SP <= next_SP;

            FULL <= (next_SP == 4);
            EMPTY <= (next_SP == 0);
        end
    end
end

endmodule

