module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    localparam IDLE = 2'b00;
    localparam PULSE_START = 2'b01;
    localparam PULSE_END = 2'b10;

    reg [1:0] state_reg;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state_reg <= IDLE;
            data_out <= 0;
        end else begin
            case (state_reg)
                IDLE: begin
                    data_out <= 0;
                    if (data_in) begin
                        state_reg <= PULSE_START;
                    end else begin
                        state_reg <= IDLE;
                    end
                end
                PULSE_START: begin
                    data_out <= 0;
                    if (~data_in) begin
                        state_reg <= PULSE_END;
                    end else begin
                        state_reg <= PULSE_START;
                    end
                end
                PULSE_END: begin
                    data_out <= 1;
                    state_reg <= IDLE;
                end
                default: begin
                    state_reg <= IDLE;
                    data_out <= 0;
                end
            endcase
        end
    end

endmodule

