module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] dividend_reg, divisor_reg;
reg [7:0] abs_dividend, abs_divisor;
reg [8:0] SR;

reg [8:0] NEG_DIVISOR;

reg [3:0] cnt;
reg start_cnt;
reg quotient_sign, remainder_sign;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        result <= 16'b0;
        dividend_reg <= 8'b0;
        divisor_reg <= 8'b0;
        abs_dividend <= 8'b0;
        abs_divisor <= 8'b0;
        SR <= 9'b0;
        NEG_DIVISOR <= 9'b0;
        cnt <= 0;
        start_cnt <= 0;
        quotient_sign <= 0;
        remainder_sign <= 0;
    end else begin
        if (opn_valid && !res_valid) begin
            dividend_reg <= dividend;
            divisor_reg <= divisor;

            if (sign) begin
                quotient_sign <= (dividend[7] ^ divisor[7]);
                remainder_sign <= dividend[7];
                abs_dividend <= dividend[7] ? (-dividend) : dividend;
                abs_divisor <= divisor[7] ? (-divisor) : divisor;
            end else begin
                quotient_sign <= 0;
                remainder_sign <= 0;
                abs_dividend <= dividend;
                abs_divisor <= divisor;
            end

            SR <= {abs_dividend, 1'b0};

            NEG_DIVISOR <= -{1'b0, abs_divisor};
            cnt <= 4'd1;
            start_cnt <= 1;
        end else if (start_cnt) begin
            if (cnt == 4'd8) begin

                start_cnt <= 0;
                if (sign) begin
                    result[7:0] <= quotient_sign ? (-SR[7:0]) : SR[7:0];
                    result[15:8] <= remainder_sign ? (-SR[8:1]) : SR[8:1];
                end else begin
                    result[7:0] <= SR[7:0];
                    result[15:8] <= SR[8:1];
                end
                res_valid <= 1;
            end else begin

                reg [8:0] sr_shifted = SR << 1;
                reg [8:0] sub_result = {1'b0, sr_shifted[8:1]} - NEG_DIVISOR;
                reg carry_out = ~sub_result[8];

                if (carry_out) begin
                    SR <= {sub_result[7:0], 1'b1};
                end else begin
                    SR <= {sr_shifted[8:1], 1'b0};
                end
                cnt <= cnt + 1;
            end
        end else begin
            res_valid <= 0;
        end
    end
end

endmodule

