    input [16:1] B,
    input C_in,
    output [16:1] S,
    output C_out,
    output P,
    output G
);
    wire [16:1] p, g;
    wire [16:0] P, G;
    wire [16:0] carry;
    integer i;

    generate
    for (i=1;
 i<=16;
 i=i+1) begin : gen_pg
        assign p[i] = A[i] ^ B[i];
        assign g[i] = A[i] & B[i];
    end
    endgenerate

    assign P[0] = p[1];
    assign G[0] = g[1];
    generate
    for (i=2;
 i<=16;
 i=i+1) begin : gen_pg
        assign P[i] = p[i] & P[i-1];
        assign G[i] = g[i] | (p[i] & G[i-1]);
