module fixed_point_adder #(parameter Q=4, N=8) (
    input  [N-1:0] a,
    input  [N-1:0] b,
    output [N-1:0] c
);
    reg [N-1:0] res;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];

    always @(*) begin
        if (a_sign == b_sign) begin

            res = {a_sign, a[N-2:0] + b[N-2:0]};
        end else begin

            if ($signed(a) > $signed(b)) begin
                res = a - b;
            end else begin
                res = b - a;
            end
        end
    end

    assign c = res;

endmodule

