module fixed_point_subtractor #(parameter Q = 4, parameter N = 8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;

    always @* begin
        if (a[N-1] == b[N-1]) begin

            res = a - b;
            if (res[N-1]) begin

                res = ~res + 1'b1;
                res[N-1] = ~a[N-1];
            end else begin
                res[N-1] = a[N-1];
            end
        end else begin

            if ($signed(a) > $signed(b)) begin
                res = a - b;
                res[N-1] = 1'b0;

            end else begin
                res = b - a;
                res[N-1] = 1'b1;

            end
        end

        if (res == 0) begin
            res[N-1] = 1'b0;
        end
        c = res;
    end

endmodule

