module float_multi (
    input wire clk,
    input wire rst,
    input wire [31:0] a,
    input wire [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa, product, z_mantissa;
    reg [47:0] product_full;
    reg [5:0] guard_bit, round_bit, sticky;
    reg [2:0] shift_count;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b000: begin 
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    if (a[30:23] == 8'b0)
                        a_mantissa <= {1'b0, a[22:0]};
                    else
                        a_mantissa <= {1'b1, a[22:0]};
                    if (b[30:23] == 8'b0)
                        b_mantissa <= {1'b0, b[22:0]};
                    else
                        b_mantissa <= {1'b1, b[22:0]};
                    counter <= counter + 1;
                end
                3'b001: begin 
                    if (a_exponent == 8'hff) begin 
                        if (a_mantissa != 0) begin 
                            z <= {a_sign, 8'hff, 23'h1};
                        end else begin 
                            if (b_exponent == 8'hff) begin
                                if (b_mantissa != 0) begin
                                    z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                                end else begin 
                                    z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                                end
                            end else if (b_exponent == 0) begin 
                                z <= {8'hff, 23'h1};
                            end else begin
                                z_sign <= a_sign ^ b_sign;
                                z_exponent <= a_exponent + b_exponent - 127;
                                product_full <= {a_mantissa, 24'b0} * {b_mantissa, 24'b0};
                                counter <= counter + 1;
                            end
                        end
                    end else if (b_exponent == 8'hff) begin 
                        if (b_mantissa != 0) begin
                            z <= {b_sign, 8'hff, 23'h1};
                        end else begin
                            if (a_exponent == 8'hff) begin
                                if (a_mantissa != 0) begin
                                    z <= {b_sign ^ a_sign, 8'hff, 23'h1};
                                end else begin
                                    z <= {b_sign ^ a_sign, 8'hff, 23'h0};
                                end
                            end else if (a_exponent == 0) begin
                                z <= {8'hff, 23'h1};
                            end else begin
                                z_sign <= a_sign ^ b_sign;
                                z_exponent <= a_exponent + b_exponent - 127;
                                product_full <= {a_mantissa, 24'b0} * {b_mantissa, 24'b0};
                                counter <= counter + 1;
                            end
                        end
                    end else if (a_exponent == 0) begin 
                        if (b_exponent == 0) begin 
                            if (a_mantissa == 0 && b_mantissa == 0) begin
                                z <= 32'h0;
                            end else begin
                                z_sign <= a_sign ^ b_sign;
                                z_exponent <= 8'd0;
                                product_full <= {a_mantissa, 24'b0} * {b_mantissa, 24'b0};
                                counter <= counter + 1;
                            end
                        end else begin
                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= b_exponent + 8'd127 - 8'd127;

                            product_full <= {a_mantissa, 24'b0} * {b_mantissa, 24'b0};
                            counter <= counter + 1;
                        end
                    end else if (b_exponent == 0) begin 
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= a_exponent + 8'd127 - 8'd127;
                        product_full <= {a_mantissa, 24'b0} * {b_mantissa, 24'b0};
                        counter <= counter + 1;
                    end else begin
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= a_exponent + b_exponent - 8'd127;
                        product_full <= {a_mantissa, 24'b0} * {b_mantissa, 24'b0};
                        counter <= counter + 1;
                    end
                    if (a_exponent != 8'hff && b_exponent != 8'hff && a_exponent != 0 && b_exponent != 0) begin
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= a_exponent + b_exponent - 8'd127;
                        product_full <= {a_mantissa, 24'b0} * {b_mantissa, 24'b0};
                        counter <= counter + 1;
                    end
                end
                3'b010: begin 
                    if (product_full[47]) begin 
                        product <= product_full[48:25];
                        z_exponent <= z_exponent + 8'd1;
                        shift_count <= 47 - 24;

                    end else begin 
                        integer i;
                        reg [5:0] leading_zero;
                        leading_zero = 0;
                        for (i=47;
 i>=0;
 i=i-1) begin
                            if (product_full[i]) begin
                                leading_zero = 47 - i;
                                i = -1;
                            end
                        end
