module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire rclk,
    input wire wrstn,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output reg rempty,
    output reg wfull,
    output wire [WIDTH-1:0] rdata
);
    localparam ADDR_WIDTH = $clog2(DEPTH);

    function [ADDR_WIDTH-1:0] bin2gray(input [ADDR_WIDTH-1:0] bin);
        bin2gray = (bin >> 1) ^ bin;
    endfunction


    reg [ADDR_WIDTH-1:0] waddr_bin = 0;
    reg [ADDR_WIDTH-1:0] wptr_gray = 0;
    reg [ADDR_WIDTH-1:0] rptr_gray_sync1 = 0, rptr_gray_sync = 0;


    reg [ADDR_WIDTH-1:0] raddr_bin = 0;
    reg [ADDR_WIDTH-1:0] rptr_gray = 0;
    reg [ADDR_WIDTH-1:0] wptr_gray_sync1 = 0, wptr_gray_sync = 0;


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_gray_sync1 <= 0;
            rptr_gray_sync <= 0;
        end else begin
            rptr_gray_sync1 <= rptr_gray;
            rptr_gray_sync <= rptr_gray_sync1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_gray_sync1 <= 0;
            wptr_gray_sync <= 0;
        end else begin
            wptr_gray_sync1 <= wptr_gray;
            wptr_gray_sync <= wptr_gray_sync1;
        end
    end


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
            wptr_gray <= 0;
        end else begin
            if (winc && !wfull) begin
                waddr_bin <= waddr_bin + 1;
                wptr_gray <= bin2gray(waddr_bin + 1);
            end
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
            rptr_gray <= 0;
        end else begin
            if (rinc && !rempty) begin
                raddr_bin <= raddr_bin + 1;
                rptr_gray <= bin2gray(raddr_bin + 1);
            end
        end
    end


    always @(*) begin
        rempty = (rptr_gray == wptr_gray_sync);
        wfull = (wptr_gray == {~rptr_gray_sync[ADDR_WIDTH-1:ADDR_WIDTH-2], 
                               rptr_gray_sync[ADDR_WIDTH-3:0]});
    end


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(raddr_bin),
        .rdata(rdata)
    );
endmodule


module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire wenc,
    input wire [$clog2(DEPTH)-1:0] waddr,
    input wire [WIDTH-1:0] wdata,
    input wire rclk,
    input wire renc,
    input wire [$clog2(DEPTH)-1:0] raddr,
