module LIFObuffer(
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);
    reg [2:0] SP;

    reg [3:0] stack_mem [0:3];

    integer i;

    always @(posedge Clk) begin
        if (EN) begin
            if (Rst) begin 
                for (i = 0;
 i < 4;
 i = i + 1)
                    stack_mem[i] <= 4'b0;
                SP <= 3'd4;
                dataOut <= 4'b0;

            end else begin
                if (RW == 0) begin 
                    if (!FULL) begin
                        stack_mem[SP] <= dataIn;
                        SP <= SP - 3'd1;
                    end
                end else begin 
                    if (!EMPTY) begin
                        dataOut <= stack_mem[SP];
                        stack_mem[SP] <= 4'b0;

                        SP <= SP + 3'd1;
                    end
                end
            end
        end
    end


    always @(*) begin
        EMPTY = (SP == 3'd4);
        FULL = (SP == 3'd0);
    end

