module traffic_light(
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);
    parameter [1:0] idle = 2'b00,
                    s1_red = 2'b01,
                    s2_yellow = 2'b10,
                    s3_green = 2'b11;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: state <= (cnt == 8'd3) ? s3_green : s1_red;
                s2_yellow: state <= (cnt == 8'd3) ? s1_red : s2_yellow;
                s3_green: state <= (cnt == 8'd3) ? s2_yellow : s3_green;
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin
            if (pass_request && green)
                cnt <= 8'd10;
            else if (green && p_green)
                cnt <= 8'd60;
            else if (yellow && p_yellow)
                cnt <= 8'd5;
            else if (red && p_red)
                cnt <= 8'd10;
            else
                cnt <= cnt - 8'd1;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {p_red, p_yellow, p_green} <= 3'b0;
        end else begin
            {p_red, p_yellow, p_green} <= {red, yellow, green};
        end
    end


    always @(*) begin
        {red, yellow, green} = 3'b0;
        case (state)
            s1_red: red = 1'b1;
            s2_yellow: yellow = 1'b1;
            s3_green: green = 1'b1;
            default: {red, yellow, green} = 3'b0;
        endcase
    end

    assign clock = cnt;

endmodule

