            if (next_cnt == 4'd8) begin
                dout_parallel <= {din_serial, shift_reg[7:1]};
                dout_valid <= 1'b1;
                cnt <= 4'd0;
            end else begin
                dout_valid <= 1'b0;
            end
        end
    end

