module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [7:0] saved_dividend, saved_divisor;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] abs_dividend, abs_divisor;
    reg [7:0] neg_divisor;
    reg [7:0] quotient;
    reg [7:0] remainder;
    reg [7:0] saved_quotient, saved_remainder;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            start_cnt <= 0;
            cnt <= 0;
            SR <= 0;
            quotient <= 0;
            remainder <= 0;
            saved_dividend <= 0;
            saved_divisor <= 0;
            neg_divisor <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid) begin
                saved_dividend <= dividend;
                saved_divisor <= divisor;

                abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;

                SR <= {abs_dividend, 8'b0} << 1;
                neg_divisor <= -abs_divisor;
                cnt <= 1;
                start_cnt <= 1;
            end else if (start_cnt) begin
                if (cnt == 8) begin

                    if (sign) begin
                        saved_remainder <= dividend[7] ? ~remainder + 1 : remainder;
                        saved_quotient <= (saved_dividend[7] ^ saved_divisor[7]) ? ~quotient + 1 : quotient;
                    end else begin
                        saved_remainder <= remainder;
                        saved_quotient <= quotient;
                    end
                    result <= {saved_remainder, saved_quotient};
                    res_valid <= 1;
                    start_cnt <= 0;
                    cnt <= 0;
                end else begin

                    reg [8:0] temp = {1'b0, SR[15:8]} - {1'b0, neg_divisor};
                    if (temp[8] == 0) begin
                        remainder <= temp[7:0];
                        quotient <= {quotient[6:0], 1'b1};
                    end else begin
                        quotient <= {quotient[6:0], 1'b0};
                    end
                    SR <= {remainder, quotient} << 1;
                    cnt <= cnt + 1;
                end
            end else begin
                res_valid <= 0;
            end
        end
    end
endmodule

