module div_16bit (A, B, result, odd);
input [15:0] A;
input [7:0] B;
output reg [15:0] result = 0;
output reg [15:0] odd = 0;

reg [15:0] a_reg;
reg [7:0] b_reg;

always @(A, B) begin
    a_reg = A;
    b_reg = B;
end

always @(A, B) begin
    reg [15:0] quotient;
    reg [15:0] remainder;
    integer i;

    quotient = 16'b0;
    remainder = 16'b0;
    for (i = 15;
 i >= 0;
 i = i - 1) begin
        remainder = remainder << 1;
        remainder[0] = a_reg[i];
        if (remainder >= {8'b0, b_reg}) begin
            quotient[i] = 1'b1;
            remainder = remainder - {8'b0, b_reg};
        end else begin
            quotient[i] = 1'b0;
        end
    end
    result = quotient;
    odd = remainder;
end

endmodule

