module adder_bcd (A, B, Cin, Sum, Cout);
    input [3:0] A, B;
    input Cin;
    output [3:0] Sum;
    output Cout;

    wire [4:0] sum_temp = {1'b0, A} + {1'b0, B} + Cin;
    wire [4:0] sum_corrected = sum_temp + 5'd6;

