module fixed_point_adder #(parameter Q=3, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    wire a_sign, b_sign;
    reg [N-1:0] abs_a, abs_b;
    reg [N:0] sum_abs;

    wire overflow;

    always @(*) begin
        a_sign = a[N-1];
        b_sign = b[N-1];


        if (a_sign == b_sign) begin

            abs_a = a_sign ? (~a + 1) : a;
            abs_b = b_sign ? (~b + 1) : b;
            sum_abs = abs_a + abs_b;


            if (sum_abs[N]) begin 
                if (a_sign)
                    res = {1'b1, {(N-1){1'b0}}};

                else
                    res = {1'b0, {(N-1){1'b1}}};

            end else begin
                res = {a_sign, sum_abs[N-1:0]};

            end
        end

        else begin
            abs_a = a_sign ? (~a + 1) : a;
            abs_b = b_sign ? (~b + 1) : b;

            if (abs_a > abs_b) begin
                res = abs_a - abs_b;
                res[N-1] = a_sign;

            end else if (abs_b > abs_a) begin
                res = abs_b - abs_a;
                res[N-1] = b_sign;
            end else begin
                res = 0;

            end
        end

        c = res;
    end
endmodule

