reg [N-1:0] res;
reg [N-1:0] abs_a, abs_b;
reg [N-1:0] sum;
integer i;

always @* begin
    sign_a = a[N-1];
    sign_b = b[N-1];
    res = 0;

    if (sign_a == sign_b) begin

        res = a - b;


        if (res == 0)
            res[N-1] = 0;
    end else begin

        abs_a = sign_a ? (~a + 1) : a;
        abs_b = sign_b ? (~b + 1) : b;
        sum = abs_a + abs_b;

        if (sign_a == 0 && sign_b == 1) begin

            if (a > b)
                res = {1'b0, sum[N-2:0]};

            else
                res = {1'b1, sum[N-2:0]};

        end else begin

            res = {1'b1, sum[N-2:0]};

        end


        if (sign_a == 0 && sign_b == 1)
            res[N-1] = (a > b) ? 1'b0 : 1'b1;
        else
            res[N-1] = (a < b) ? 1'b0 : 1'b1;
    end

    c = res;
end

