    reg a_zero, a_inf, a_nan, b_zero, b_inf, b_nan;
    reg [7:0] exponents_sum;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b000;
            z <= 32'b0;
            a_reg <= 32'b0;
            b_reg <= 32'b0;
            a_sign <= 1'b0;
            b_sign <= 1'b0;
