            a_inf <= 1'b0;
            a_nan <= 1'b0;
            b_zero <= 1'b0;
            b_inf <= 1'b0;
            b_nan <= 1'b0;
        end else begin
            case (counter)
                3'b000: begin
                    a_reg <= a;
                    b_reg <= b;
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};
                    counter <= counter + 1;
                end
                3'b001: begin

                    a_zero = (a_exponent == 0 && a_mantissa == 0);
                    b_zero = (b_exponent == 0 && b_mantissa == 0);
                    a_inf = (a_exponent == 8'hFF && a_mantissa == 0);
                    b_inf = (b_exponent == 8'hFF && b_mantissa == 0);
                    a_nan = (a_exponent == 8'hFF && a_mantissa != 0);
                    b_nan = (b_exponent == 8'hFF && b_mantissa != 0);

                    special_case = 0;
                    if (a_nan || b_nan) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h1};
                        special_case = 1;
                    end else if ((a_inf && b_zero) || (b_inf && a_zero)) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h1};
                        special_case = 1;
                    end else if (a_inf || b_inf) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                        special_case = 1;
                    end else if (a_zero || b_zero) begin
                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                        special_case = 1;
                    end
                    if (!special_case) begin
                        sum_exponent = a_exponent + b_exponent - 9'd127;
                        counter <= counter + 1;
                    end else begin
                        counter <= 3'b000;
                    end
                end
                3'b010: begin
                    if (!special_case) begin
                        product = a_mantissa * b_mantissa;
                        counter <= counter + 1;
                    end
                end
                3'b011: begin
                    if (!special_case) begin

                        if (product[47:46] >= 2) begin
                            product = product >> 1;
                            sum_exponent = sum_exponent + 1;
                        end

                        if (product[47]) begin
                            guard = product[46];
                            round = product[45];
                            sticky = |product[44:0];
                        end else begin
                            guard = product[45];
                            round = product[44];
                            sticky = |product[43:0];
                        end
                        counter <= counter + 1;
                    end
                end
                3'b100: begin
                    if (!special_case) begin

                        if (guard) begin
                            if (round || sticky) begin
                                mantissa = product[46:24] + 1;

                                if (mantissa[23]) begin
                                    mantissa = 23'b0;
                                    sum_exponent = sum_exponent + 1;
                                end
                            end else begin
                                mantissa = product[46:24];
                            end
                        end else begin
                            mantissa = product[46:24];
                        end

                        if (sum_exponent > 9'd255) begin
                            exponent = 9'h1FF;
                        end else if (sum_exponent < 0) begin
                            exponent = 9'h000;
                        end else begin
                            exponent = sum_exponent;
                        end

                        temp_z = {a_sign ^ b_sign, exponent[7:0], mantissa};
                        counter <= 3'b000;
                        z <= temp_z;
                    end
                end
                default: begin
                    counter <= 3'b000;
                end
            endcase
        end
    end
