module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire rclk,
    input wire wrstn,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output wire wfull,
    output wire rempty,
    output wire [WIDTH-1:0] rdata
);
    localparam ADDR_WIDTH = $clog2(DEPTH) + 1;
    reg [ADDR_WIDTH-1:0] waddr_bin, raddr_bin;
    reg [ADDR_WIDTH-1:0] wptr_gray, rptr_gray;
    reg [ADDR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync2;
    reg [ADDR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync2;


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram_inst (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(waddr_bin[ADDR_WIDTH-2:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(raddr_bin[ADDR_WIDTH-2:0]),
        .rdata(rdata)
    );


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
            wptr_gray <= 0;
            wptr_gray_sync1 <= 0;
            wptr_gray_sync2 <= 0;
        end else begin

            if (winc && !wfull)
                waddr_bin <= waddr_bin + 1;

            wptr_gray <= (waddr_bin >> 1) ^ waddr_bin;

            wptr_gray_sync1 <= rptr_gray_sync2;
            wptr_gray_sync2 <= wptr_gray_sync1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
            rptr_gray <= 0;
            rptr_gray_sync1 <= 0;
            rptr_gray_sync2 <= 0;
        end else begin

            if (rinc && !rempty)
                raddr_bin <= raddr_bin + 1;

            rptr_gray <= (raddr_bin >> 1) ^ raddr_bin;

            rptr_gray_sync1 <= wptr_gray_sync2;
            rptr_gray_sync2 <= rptr_gray_sync1;
        end
    end


    assign wfull = (wptr_gray[ADDR_WIDTH-1] ^ rptr_gray_sync2[ADDR_WIDTH-1]) &&
                   (wptr_gray[ADDR_WIDTH-2] ^ rptr_gray_sync2[ADDR_WIDTH-2]) &&
                   (wptr_gray[ADDR_WIDTH-3:0] == rptr_gray_sync2[ADDR_WIDTH-3:0]);
