module LIFObuffer(dataIn, RW, EN, Rst, Clk, EMPTY, FULL, dataOut);
    input [3:0] dataIn;
    input RW, EN, Rst, Clk;
    output reg EMPTY, FULL;
    output reg [3:0] dataOut;

    reg [3:0] stack_mem [0:3];
    reg [2:0] SP;


    always @(posedge Clk) begin
        if (Rst) begin

            SP <= 3'd4;

            EMPTY <= 1'b1;
            FULL <= 1'b0;
            dataOut <= 4'b0;
            stack_mem[0] <= 4'b0;
            stack_mem[1] <= 4'b0;
            stack_mem[2] <= 4'b0;
            stack_mem[3] <= 4'b0;
        end else begin
            if (EN) begin
                case ({RW, !FULL, !EMPTY})
                    3'b010: begin 
                        stack_mem[SP-1] <= dataIn;
                        SP <= SP - 1;
                    end
                    3'b101: begin 
                        dataOut <= stack_mem[SP];
                        stack_mem[SP] <= 4'b0;
                        SP <= SP + 1;
                    end
                endcase
            end
        end
    end


    always @* begin
        EMPTY = (SP == 3'd4);
        FULL = (SP == 3'd0);
    end
endmodule

