            state <= IDLE;
            data_out <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (data_in) begin
                        state <= RISE;
                        data_out <= 1'b0;
                    end else begin
                        state <= IDLE;
                        data_out <= 1'b0;
                    end
                end
                RISE: begin
                    if (data_in) begin
                        state <= RISE;
                        data_out <= 1'b0;
                    end else begin
                        state <= IDLE;
                        data_out <= 1'b1;
                    end
                end
                default: begin
                    state <= IDLE;
                    data_out <= 1'b0;
                end
            endcase
        end
    end
