module fixed_point_adder #(parameter Q = 16, N = 32) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    reg sign_a, sign_b;
    reg [N-2:0] mag_a, mag_b;
    reg [N-2:0] sum_mag, diff_mag;

    always @(*) begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        mag_a = a[N-2:0];
        mag_b = b[N-2:0];

        if (sign_a == sign_b) begin

            sum_mag = mag_a + mag_b;
            res[N-1] = sign_a;
            res[N-2:0] = sum_mag;
        end else begin

            if (mag_a > mag_b) begin
                diff_mag = mag_a - mag_b;
                res[N-1] = sign_a;
                res[N-2:0] = diff_mag;
            end else if (mag_b > mag_a) begin
                diff_mag = mag_b - mag_a;
                res[N-1] = sign_b;
                res[N-2:0] = diff_mag;
            end else begin

                res = {1'b0, {(N-1){1'b0}}};
            end
        end


        if (sign_a == sign_b && mag_a + mag_b > {1'b0, {(N-2){1'b1}}}) begin
            res = {sign_a, {(N-1){1'b1}}};
        end

        c = res;
    end
endmodule

