module fixed_point_subtractor #(parameter Q=4, parameter N=8) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);
    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire sign_res;
    reg [N-1:0] abs_a, abs_b;

    always @(*) begin
        if (sign_a == sign_b) begin

            res = $signed(a) - $signed(b);
            res[N-1] = sign_a;
        end else begin

            abs_a = sign_a ? (-$signed(a)) : $signed(a);
            abs_b = sign_b ? (-$signed(b)) : $signed(b);
            res = abs_a + abs_b;

            if (sign_a) begin 
                sign_res = (abs_b > abs_a) ? 1'b0 : 1'b1;
            end else begin 
                sign_res = ($signed(a) > $signed(b)) ? 1'b0 : 1'b1;
            end
            res = {sign_res, res[N-1:1]};
        end

        if (res == 0)
            res[N-1] = 1'b0;
    end

    assign c = res;

endmodule

