module float_multi(
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg [7:0] a_exponent, b_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg a_sign, b_sign, z_sign;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;
    reg [22:0] z_mantissa;
    reg [8:0] z_exponent;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_exponent <= 8'b0;
            b_exponent <= 8'b0;
            a_mantissa <= 23'b0;
            b_mantissa <= 23'b0;
            a_sign <= 0;
            b_sign <= 0;
            product <= 48'b0;
            z_mantissa <= 23'b0;
            z_exponent <= 9'b0;
        end else begin
            case (counter)
                3'b000: begin 
                    a_sign <= a[31];
                    a_exponent <= a[30:23];
                    a_mantissa <= (a[30:23] != 0) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                    b_sign <= b[31];
                    b_exponent <= b[30:23];
                    b_mantissa <= (b[30:23] != 0) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};
                    counter <= 3'b001;
                end
                3'b001: begin 
                    if ((a[30:23] == 8'hFF && a[22:0] != 0) || (b[30:23] == 8'hFF && b[22:0] != 0)) begin
                        z <= {1'b0, 8'hFF, 1'b1, 22'b0};
                    end else if (a[30:23] == 8'hFF || b[30:23] == 8'hFF) begin
                        z <= {a[31] ^ b[31], 8'hFF, 1'b1, 22'b0};
                    end else if ((a_exponent == 0 && a_mantissa == 0) || (b_exponent == 0 && b_mantissa == 0)) begin
                        z <= {a_sign ^ b_sign, 31'b0};
                    end else begin
                        counter <= 3'b010;
                    end
                end
                3'b010: begin 
                    product <= a_mantissa * b_mantissa;
                    z_exponent <= a_exponent + b_exponent - 9'd127;
                    counter <= 3'b011;
                end
                3'b011: begin 
                    integer i, shift;
                    reg [47:0] temp_product;
                    temp_product = product;
                    shift = 0;
                    for (i=47;
 i>=0;
 i=i-1) begin
                        if (temp_product[i]) begin
                            shift = 47 - i;
                            break;
                        end
                    end
