    reg p_red, p_yellow, p_green;

    assign clock = cnt;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: begin
                    if (cnt == 8'd3)
                        state <= s3_green;
                    else
                        state <= s1_red;
                end
                s3_green: begin
                    if (cnt == 8'd60)
                        state <= s2_yellow;
                    else
                        state <= s3_green;
                end
                s2_yellow: begin
                    if (cnt == 8'd3)
                        state <= s1_red;
                    else
                        state <= s2_yellow;
                end
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin
            if (pass_request && p_green) begin
                cnt <= 8'd10;
            end else if (p_green && !green) begin
                cnt <= 8'd60;
            end else if (p_yellow && !yellow) begin
