module fixed_point_adder #(parameter Q=3, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;

always @(*) begin
    reg sign_a, sign_b;
    reg [N-1:0] abs_a, abs_b;
    reg [N-1:0] res_magnitude;
    reg res_sign;

    sign_a = a[N-1];
    sign_b = b[N-1];

    if (sign_a == sign_b) begin
        res = a + b;
        res_sign = sign_a;
    end else begin
        abs_a = sign_a ? (~a + 1) : a;
        abs_b = sign_b ? (~b + 1) : b;

        if (abs_a > abs_b) begin
            res_magnitude = abs_a - abs_b;
            res_sign = sign_a;
        end else if (abs_b > abs_a) begin
            res_magnitude = abs_b - abs_a;
            res_sign = sign_b;
        end else begin
            res_magnitude = 0;
            res_sign = 0;
        end

        res = {res_sign, res_magnitude[N-2:0]};
    end
end

always @(*) begin
    c = res;
end

endmodule

