module fixed_point_subtractor #(parameter Q=2, N=4) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);
    reg [N-1:0] res;
    reg a_sign, b_sign;
    reg same_sign;
    reg [N-1:0] abs_a, abs_b;
    reg [N-1:0] sum;
    reg res_sign;

    always @* begin
        a_sign = a[N-1];
        b_sign = b[N-1];
        same_sign = (a_sign == b_sign);

        if (same_sign) begin

            res = a - b;
            res_sign = a_sign;
        end else begin
            if (a_sign) begin

                abs_a = ~a + 1;
                abs_b = b;
                sum = abs_a + abs_b;
                res_sign = (abs_a > abs_b) ? 1'b1 : 1'b0;
            end else begin

                abs_b = ~b + 1;
                sum = a + abs_b;
                res_sign = (a > abs_b) ? 1'b0 : 1'b1;
            end
        end


        if (sum == 0)
            res_sign = 1'b0;


        res = {res_sign, sum[N-1:1]};
        c = res;
    end
endmodule

