    assign is_nan_a = (a_exponent == 8'hff) && (a_mantissa != 23'd0);
    assign is_nan_b = (b_exponent == 8'hff) && (b_mantissa != 23'd0);
    assign is_inf_a = (a_exponent == 8'hff) && (a_mantissa == 23'd0);
    assign is_inf_b = (b_exponent == 8'hff) && (b_mantissa == 23'd0);
    assign is_zero_a = (a_exponent == 8'd0) && (a_mantissa == 23'd0);
    assign is_zero_b = (b_exponent == 8'd0) && (b_mantissa == 23'd0);

