        if (rst) begin
            counter <= 3'd0;
            z <= 32'd0;
        end else begin
            case (counter)
                3'd0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a_exponent != 8'd0 && a_exponent != 8'hff) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                    b_mantissa <= (b_exponent != 8'd0 && b_exponent != 8'hff) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};
                    z_sign <= a_sign ^ b_sign;
                    inf_flag <= 0;
                    nan_flag <= 0;
                    zero_flag <= 0;


                    if (is_nan_a || is_nan_b) begin
                        z <= {1'b0, 8'hff, 23'h1};

                        counter <= 3'd0;
                    end else if ((is_inf_a || is_inf_b) && (is_zero_a || is_zero_b)) begin
                        z <= {1'b0, 8'hff, 23'h1};

                        counter <= 3'd0;
                    end else if (is_inf_a || is_inf_b) begin
                        z_exponent <= 8'hff;
                        z_mantissa <= 23'd0;
                        counter <= 3'd1;
                    end else if (is_zero_a || is_zero_b) begin
                        z <= 32'd0;
                        counter <= 3'd0;
                    end else begin
                        product <= a_mantissa * b_mantissa;
                        exp_sum <= a_exponent + b_exponent - 9'd127;
                        counter <= 3'd1;
                    end
                end

                3'd1: begin

                    if (product[47]) begin
                        exp_sum <= exp_sum + 9'd1;
                        norm_mantissa <= product[46:23];
                    end else begin
                        norm_mantissa <= product[47:24];
                    end

                    guard_bit <= product[23];
                    round_bit <= product[22];
                    sticky_bit <= |product[21:0];
                    counter <= 3'd2;
