                    end

                    if (norm_mantissa[23]) begin 
                        norm_mantissa <= norm_mantissa >> 1;
                        exp_sum <= exp_sum + 9'd1;
                    end

                    overflow <= (exp_sum >= 9'd255);
                    underflow <= (exp_sum <= 9'd0);
                    counter <= 3'd3;
                end

                3'd3: begin

                    if (overflow) begin
                        z <= {z_sign, 8'hff, 23'd0};

                    end else if (underflow) begin
                        z <= 32'd0;

                    end else begin
                        z_mantissa <= norm_mantissa[22:0];
                        z_exponent <= exp_sum[7:0];
                        z <= {z_sign, z_exponent, z_mantissa};
                    end
                    counter <= 3'd0;
                end
            endcase
        end
    end
