module LIFObuffer(dataIn, RW, EN, Rst, Clk, EMPTY, FULL, dataOut);
    input [3:0] dataIn;
    input RW, EN, Rst, Clk;
    output reg EMPTY, FULL;
    output reg [3:0] dataOut;

    reg [3:0] stack_mem [0:3];

    reg [3:0] SP;


    always @(posedge Clk) begin
        reg [3:0] next_SP;
        reg push, pop;

        if (Rst) begin

            SP <= 4;
            EMPTY <= 1;
            FULL <= 0;
            stack_mem[0] <= 0;
            stack_mem[1] <= 0;
            stack_mem[2] <= 0;
            stack_mem[3] <= 0;
            dataOut <= 0;
        end else if (EN) begin

            push = (RW == 0) && (~FULL);
            pop = (RW == 1) && (~EMPTY);

            next_SP = SP;



            if (push) begin
                stack_mem[SP - 1] <= dataIn;
                next_SP = SP - 1;
            end else if (pop) begin
                dataOut <= stack_mem[SP - 1];
                stack_mem[SP - 1] <= 0;
                next_SP = SP + 1;
            end


            SP <= next_SP;
            EMPTY <= (next_SP == 4);
            FULL <= (next_SP == 0);
        end
    end
endmodule

