module width_8to16 (
    input clk,
    input rst_n,
    input valid_in,
    input [7:0] data_in,
    output valid_out,
    output [15:0] data_out
);

reg [7:0] data_lock;
reg stored_data;
reg [15:0] buffered_data;
reg buffered_valid;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data_lock <= 8'b0;
        stored_data <= 1'b0;
        buffered_valid <= 1'b0;
        buffered_data <= 16'b0;
