reg [7:0] abs_dividend, abs_divisor;
reg quotient_sign, remainder_sign;
reg [15:0] SR;
reg [3:0] cnt;
reg start_cnt;
reg [7:0] NEG_DIVISOR;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        SR <= 0;
        cnt <= 0;
        start_cnt <= 0;
        dividend_reg <= 0;
        divisor_reg <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        quotient_sign <= 0;
        remainder_sign <= 0;
        NEG_DIVISOR <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            dividend_reg <= dividend;
            divisor_reg <= divisor;
            quotient_sign <= 0;
            remainder_sign <= 0;
            if (sign) begin

                quotient_sign <= dividend[7] ^ divisor[7];
                remainder_sign <= dividend[7];
                abs_dividend <= dividend[7] ? -dividend : dividend;
                abs_divisor <= divisor[7] ? -divisor : divisor;
            end else begin

                quotient_sign <= 0;
                remainder_sign <= 0;
                abs_dividend <= dividend;
                abs_divisor <= divisor;
            end


            SR <= {abs_dividend, 8'b0} << 1;


            NEG_DIVISOR <= sign ? -abs_divisor : abs_divisor;

            cnt <= 4'd1;
            start_cnt <= 1;
            res_valid <= 0;
        end else if (start_cnt && !res_valid) begin
            if (cnt == 4'd8) begin

                start_cnt <= 0;
                cnt <= 0;
                res_valid <= 1;


                if (sign) begin

                    result[15:8] <= remainder_sign ? -SR[15:8] : SR[15:8];
                    result[7:0] <= quotient_sign ? -SR[7:0] : SR[7:0];
                end else begin

                    result[15:8] <= SR[15:8];
                    result[7:0] <= SR[7:0];
                end
            end else begin






                wire [8:0] sub_result = {1'b0, SR[15:8]} - {1'b0, NEG_DIVISOR};
                wire carry_out = ~sub_result[8];



                SR <= {SR[14:0], carry_out};


                cnt <= cnt + 1;
            end
        end else if (res_valid) begin

            res_valid <= opn_valid ? 0 : res_valid;
        end
    end
end

endmodule

