module multi_16bit(clk, rst_n, start, ain, bin, yout, done);
input clk, rst_n, start;
input [15:0] ain, bin;
output reg [31:0] yout;
output reg done;

reg [4:0] i;

reg [15:0] areg;

reg [15:0] breg;

reg [31:0] yout_r;

reg done_r;


always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin

        i <= 5'b0;
        done_r <= 1'b0;
        areg <= 16'b0;
        breg <= 16'b0;
        yout_r <= 32'b0;
    end else begin

        if (start && (i < 17))
            i <= i + 1;
        else
            i <= 5'b0;


        case (i)
            16: done_r <= 1'b1;
            17: done_r <= 1'b0;
            default: done_r <= done_r;
        endcase


        if (start) begin
            if (i == 0) begin

                areg <= ain;
                breg <= bin;
            end else if (i > 0 && i < 17) begin

                if (areg[i-1])
                    yout_r <= yout_r + (breg << (i-1));
            end
        end
    end
end


always @* begin
    yout = yout_r;
    done = done_r;
end

endmodule

