module cla_4bit(A, B, Cin, S, G, P);
input [4:1] A, B;
input Cin;
output [4:1] S;
output G, P;

wire [4:1] p, g;
wire [4:1] c;

assign p = A ^ B;
assign g = A & B;

assign c[1] = g[1] | (p[1] & Cin);
assign c[2] = g[2] | (p[2] & g[1]) | (p[2] & p[1] & Cin);
assign c[3] = g[3] | (p[3] & g[2]) | (p[3] & p[2] & g[1]) | (p[3] & p[2] & p[1] & Cin);
assign c[4] = G | (P & Cin);

assign S[1] = p[1] ^ Cin;
assign S[2] = p[2] ^ c[1];
assign S[3] = p[3] ^ c[2];
assign S[4] = p[4] ^ c[3];

assign G = g[4] | (p[4] & g[3]) | (p[4] & p[3] & g[2]) | (p[4] & p[3] & p[2] & g[1]);
assign P = &p;

endmodule

