module fixed_point_adder #(parameter Q, parameter N) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);
reg a_msb, b_msb;
reg [N-1:0] absolute_a, absolute_b;
reg [N-1:0] sum_abs;
reg result_sign;

always @* begin
    a_msb = a[N-1];
    b_msb = b[N-1];


    absolute_a = a_msb ? (~a + 1) : a;
    absolute_b = b_msb ? (~b + 1) : b;

    if (a_msb == b_msb) begin

        sum_abs = absolute_a + absolute_b;
        result_sign = a_msb;
    end else begin

        if (absolute_a > absolute_b) begin
            sum_abs = absolute_a - absolute_b;
            result_sign = a_msb;
        end else if (absolute_b > absolute_a) begin
            sum_abs = absolute_b - absolute_a;
            result_sign = b_msb;
        end else begin

            sum_abs = 0;
            result_sign = 0;
        end
    end


    c = {result_sign, sum_abs[N-2:0]};
end

endmodule

