module fixed_point_subtractor #(parameter Q=2, parameter N=4) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;

always @* begin
    if (a[N-1] == b[N-1]) begin

        res = a - b;
        res[N-1] = a[N-1];
    end else begin

        reg [N-1:0] abs_a, abs_b;
        reg [N-1:0] sum_abs;
        reg res_sign;

        abs_a = a[N-1] ? (~a + 1) : a;
        abs_b = b[N-1] ? (~b + 1) : b;

        sum_abs = abs_a + abs_b;

        if (abs_a > abs_b) begin
            res_sign = a[N-1];
        end else begin
            res_sign = ~a[N-1];
        end

        res = {res_sign, sum_abs[N-2:0]};
    end


    if (res == {N{1'b0}}) begin
        res[N-1] = 1'b0;
    end
end

assign c = res;

endmodule

