module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg a_sign, b_sign, z_sign;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [48:0] product;
    reg guard_bit, round_bit, sticky;

    localparam IDLE = 3'b000;
    localparam INPUT_PROC = 3'b001;
    localparam SPECIAL_CASES = 3'b010;
    localparam MULT = 3'b011;
    localparam NORMALIZE = 3'b100;
    localparam ROUND = 3'b101;
    localparam ADJUST = 3'b110;
    localparam OUTPUT = 3'b111;

    always @(posedge clk) begin
        if (rst) begin
            counter <= IDLE;
            z <= 0;
        end else begin
            case (counter)
                IDLE: begin
                    counter <= INPUT_PROC;
                end
                INPUT_PROC: begin
                    a_sign <= a[31];
                    a_exponent <= a[30:23];
                    b_sign <= b[31];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] != 0) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                    b_mantissa <= (b[30:23] != 0) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};
                    counter <= SPECIAL_CASES;
                end
                SPECIAL_CASES: begin
                    if (a_exponent == 8'hFF || b_exponent == 8'hFF) begin
                        if ((a_exponent == 8'hFF && a_mantissa[22:0] != 0) || (b_exponent == 8'hFF && b_mantissa[22:0] != 0)) begin
                            z <= 32'h7FC00000;

                        end else if (a_exponent == 8'hFF && b_exponent == 8'hFF) begin
                            z <= 32'h7F800000;

                        end else if ((a_exponent == 8'hFF) || (b_exponent == 8'hFF)) begin
                            z <= 32'h7FC00000;

                        end else begin
                            z_sign <= a_sign ^ b_sign;
                            z <= 32'hFF800000;

                        end
                        counter <= OUTPUT;
                    end else if (a_exponent == 0 || b_exponent == 0) begin
                        if (a_mantissa == 0 && b_mantissa == 0) begin
                            z <= 0;
                        end else begin
                            z_sign <= a_sign ^ b_sign;
                            z <= 0;
                        end
                        counter <= OUTPUT;
                    end else begin
                        counter <= MULT;
                    end
                end
                MULT: begin
                    product <= a_mantissa * b_mantissa;
                    counter <= NORMALIZE;
                end
                NORMALIZE: begin
                    if (product[48]) begin
                        z_mantissa <= product[48:25];
                        z_exponent <= a_exponent + b_exponent - 8'd127 + 1;
                    end else begin
                        z_mantissa <= product[47:24];
                        z_exponent <= a_exponent + b_exponent - 8'd127;
                    end
                    counter <= ROUND;
                end
                ROUND: begin
                    guard_bit <= product[23];
                    round_bit <= product[22];
                    sticky <= |product[21:0];

                    if (guard_bit && (round_bit || sticky)) begin
                        z_mantissa[23] <= z_mantissa[23] ^ 1;

                        if (z_mantissa[23]) begin
                            z_exponent <= z_exponent + 1;

                            z_mantissa <= {1'b1, z_mantissa[23:1]};
                        end
                    end
                    counter <= ADJUST;
                end
                ADJUST: begin
                    if (z_exponent >= 8'hFF) begin
                        z <= {z_sign, 8'hFF, 23'b0};

                    end else if (z_exponent == 0) begin

                        z <= {z_sign, 8'h00, z_mantissa[22:0]};
                    end else begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                    end
                    counter <= OUTPUT;
                end
                OUTPUT: begin
                    z <= (z_exponent >= 8'hFF) ? {z_sign, 8'hFF, 23'b0} :
                         (z_exponent == 0) ? {z_sign, 8'h00, z_mantissa[22:0]} :
                         {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                    counter <= IDLE;
                end
                default: counter <= IDLE;
            endcase
        end
    end
