module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output [63:0] result,
    output overflow
);

wire signed [63:0] A_signed = $signed(A);
wire signed [63:0] B_signed = $signed(B);
wire signed [63:0] result_signed = A_signed - B_signed;

assign result = result_signed;

assign overflow = (~A[63] & B[63] & result[63]) | (A[63] & ~B[63] & ~result[63]);

endmodule

