module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);
    reg [1:0] state;
    localparam [1:0] State0 = 2'b00;
    localparam [1:0] State1 = 2'b01;
    localparam [1:0] State2 = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= State0;
            data_out <= 1'b0;
        end else begin
            case (state)
                State0: begin
                    if (data_in) begin
                        state <= State1;
                        data_out <= 1'b0;
                    end else begin
                        state <= State0;
                        data_out <= 1'b0;
                    end
                end
                State1: begin
                    if (!data_in) begin
                        state <= State2;
                        data_out <= 1'b1;
                    end else begin
                        state <= State1;
                        data_out <= 1'b0;
                    end
                end
                State2: begin
                    state <= State0;
                    data_out <= 1'b0;
                end
                default: begin
                    state <= State0;
                    data_out <= 1'b0;
                end
            endcase
        end
    end

endmodule

