module traffic_light (
    input wire rst_n,
    input wire clk,
    input wire pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);
    parameter [1:0] idle = 2'b00;
    parameter [1:0] s1_red = 2'b01;
    parameter [1:0] s2_yellow = 2'b10;
    parameter [1:0] s3_green = 2'b11;

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;
    reg p_green_prev, p_yellow_prev, p_red_prev;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: state <= (cnt == 3) ? s3_green : s1_red;
                s2_yellow: state <= (cnt == 3) ? s1_red : s2_yellow;
                s3_green: state <= (cnt == 0) ? s2_yellow : s3_green;
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
            red <= 0;
            yellow <= 0;
            green <= 0;
            p_green_prev <= 0;
            p_yellow_prev <= 0;
            p_red_prev <= 0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
            p_green_prev <= p_green;
            p_yellow_prev <= p_yellow;
            p_red_prev <= p_red;


            if (pass_request && p_green) begin
                cnt <= 8'd10;
            end else if (!p_green && p_green_prev) begin
                cnt <= 8'd60;
            end else if (!p_yellow && p_yellow_prev) begin
                cnt <= 8'd5;
            end else if (!p_red && p_red_prev) begin
                cnt <= 8'd10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            red <= p_red;
            yellow <= p_yellow;
            green <= p_green;
        end
    end


    always @(*) begin
        clock = cnt;
    end

endmodule

