module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output wire zero,
    output reg carry,
    output wire negative,
    output reg overflow,
    output wire flag
);


parameter ADD = 6'b100000;



assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;


assign zero = (r == 32'd0);


assign negative = r[31];


always @(*) begin

    r = 32'bz;
    carry = 1'b0;
    overflow = 1'b0;
    case (aluc)
        ADD: begin
            {carry, r} = {1'b0, a} + {1'b0, b};
            overflow = (a[31] == b[31]) && (r[31] != a[31]);
        end
        ADDU: begin
            {carry, r} = a + b;
            overflow = 1'b0;
        end
        SUB: begin
            {carry, r} = {1'b0, a} - {1'b0, b};
            overflow = (a[31] != b[31]) && (r[31] != a[31]);
        end
        SUBU: begin
            {carry, r} = a - b;
            overflow = 1'b0;
        end
        AND: r = a & b;
        OR: r = a | b;
        XOR: r = a ^ b;
        NOR: r = ~(a | b);
        SLT: begin
            r = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;




            overflow = ...;

        end
        SLTU: begin
            r = (a < b) ? 32'd1 : 32'd0;
            overflow = 1'b0;
        end
        SLL: r = b << a[4:0];
        SRL: r = b >> a[4:0];
        SRA: r = $signed(b) >>> a[4:0];
        SLLV: r = a << b[4:0];
        SRLV: r = a >> b[4:0];
        SRAV: r = $signed(a) >>> b[4:0];
        LUI: r = {a[31:16], 16'b0};
        default: r = 32'bz;
    endcase
end

endmodule

