module fixed_point_adder #(
    parameter Q = 2,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

localparam TWO_N_MINUS_1 = (1 << (N-1));

reg [N-1:0] res;

always @(*) begin
    reg a_sign, b_sign;
    reg [N-2:0] a_mag, b_mag;
    reg [N-2:0] res_mag;
    reg res_sign;

    a_sign = a[N-1];
    b_sign = b[N-1];
    a_mag = a[N-2:0];
    b_mag = b_sign ? (TWO_N_MINUS_1 - b[N-2:0]) : b[N-2:0];

    if (a_sign == b_sign) begin

        res_sign = a_sign;
        res_mag = a_mag + b_mag;
        res = {res_sign, res_mag};
    end else begin

        if (a_mag > b_mag) begin
            res_sign = 0;
            res_mag = a_mag - b_mag;
        end else if (a_mag < b_mag) begin
            res_sign = 1;
            res_mag = b_mag - a_mag;
        end else begin
            res_sign = 0;
            res_mag = 0;
        end
        res = {res_sign, res_mag};
    end
end

assign c = res;

endmodule

