module fixed_point_subtractor #(parameter Q=8, N=16) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;

    always @* begin
        if (a[N-1] == b[N-1]) begin 
            res = a - b;
            res[N-1] = a[N-1];

        end else begin
            if (a[N-1] == 1'b0 && b[N-1] == 1'b1) begin 
                reg [N-2:0] a_mag = a[N-2:0];
                reg [N-2:0] b_mag = -b[N-2:0];
                if (a_mag >= b_mag) begin
                    res[N-1] = 0;
                    res[N-2:0] = a_mag - b_mag;
                end else begin
                    res[N-1] = 1;
                    res[N-2:0] = b_mag - a_mag;
                end
            end else if (a[N-1] == 1'b1 && b[N-1] == 1'b0) begin 
                reg [N-2:0] a_mag = -a[N-2:0];
                reg [N-2:0] b_mag = b[N-2:0];
                if (a_mag >= b_mag) begin
                    res[N-1] = 1;
                    res[N-2:0] = a_mag - b_mag;
                end else begin
                    res[N-1] = 0;
                    res[N-2:0] = b_mag - a_mag;
                end
            end else begin 
                res = a - b;
                res[N-1] = a[N-1];

            end
        end


        if (res == {1'b0, {N-1{1'b0}}}) begin 
            res[N-1] = 0;

        end
    end

    assign c = res;
endmodule

