module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg [47:0] product_shifted;
    reg guard_bit, round_bit, sticky;
    reg [22:0] z_mantissa;
    reg [4:0] rounding_bits;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 1'b0;
            b_sign <= 1'b0;
            a_exponent <= 8'b0;
            b_exponent <= 8'b0;
            a_mantissa <= 23'b0;
            b_mantissa <= 23'b0;
            product <= 48'b0;
            product_shifted <= 48'b0;
            guard_bit <= 1'b0;
            round_bit <= 1'b0;
            sticky <= 1'b0;
            z_mantissa <= 23'b0;
            z_sign <= 1'b0;
            z_exponent <= 8'b0;
        end else begin
            case (counter)
                3'b000: begin 
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};
                    product <= a_mantissa * b_mantissa;
                    z_exponent <= a_exponent + b_exponent - 8'd127;
                    counter <= counter + 1;
                end
                3'b001: begin 
                    if (a_exponent == 8'hff || b_exponent == 8'hff) begin
                        if (a_exponent == 8'hff && b_exponent == 8'hff) begin
                            if (a_mantissa != 0 && b_mantissa != 0) z <= {1'b0, 8'hff, 23'h1};

                            else z <= {a_sign ^ b_sign, 8'hff, 23'h0};

                        end else if (a_exponent == 8'hff) begin
                            if (a_mantissa == 0) begin 
                                if (b_exponent == 8'h0 || b_mantissa == 0) begin
                                    z <= {b_sign, 8'hff, 23'h0};

                                end else if (b_mantissa != 0) begin
                                    z <= {a_sign ^ b_sign, 8'hff, 23'h0};

                                end else z <= {1'b0, 8'h0, 23'h0};

                            end else begin 
                                z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                            end
                        end else begin 
                            if (b_mantissa == 0) begin 
                                z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                            end else if (a_exponent == 8'h0 && a_mantissa == 0) begin
                                z <= {b_sign, 8'hff, 23'h1};

                            end else begin
                                z <= {b_sign, 8'hff, 23'h0};
                            end
                        end
                    end else if (a_exponent == 8'h0 || b_exponent == 8'h0) begin
                        if (a_exponent == 8'h0 && b_exponent == 8'h0) begin
                            if (a_mantissa == 0 && b_mantissa == 0) begin
                                z <= {a_sign ^ b_sign, 8'h0, 23'h1};

                            end else if (a_mantissa == 0) begin 
                                z <= {b_sign, 8'h0, 23'h0};
                            end else begin 
                                z <= {a_sign, 8'h0, 23'h0};
                            end
                        end else if (a_exponent == 8'h0) begin 
                            z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                        end else begin 
                            z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                        end
                    end else begin 
                        if (product[47]) begin
                            product_shifted <= product >> 1;
                            z_exponent <= z_exponent + 1;
                        end else product_shifted <= product;
                        guard_bit <= product[23];
                        round_bit <= product[22];
                        sticky <= |product[21:0];
                        counter <= counter + 1;
                    end
                end
                3'b010: begin 
                    if (guard_bit) begin
                        if (round_bit | sticky) begin
                            z_mantissa <= product_shifted[23:1] + 1;
                        end else z_mantissa <= product_shifted[23:1];
                    end else z_mantissa <= product_shifted[23:1];
                    counter <= counter + 1;
                end
                3'b011: begin 
                    if (z_mantissa[23]) begin 
                        z_exponent <= z_exponent + 1;
                        z_mantissa <= z_mantissa[22:0];
                    end
                    if (z_exponent > 8'hff) begin 
                        z <= {z_sign, 8'hff, 23'h0};
                    end else if (z_exponent == 8'h0 && z_mantissa != 0) begin 
                        z <= {z_sign, 8'h0, 23'h0};
                    end else begin 
                        z <= {z_sign, z_exponent, z_mantissa[22:0]};
                    end
                    counter <= 3'b000;
                end
            endcase
        end
    end
endmodule

