module sub_64bit (
    input  signed [63:0] A,
    input  signed [63:0] B,
    output [63:0] result,
    output overflow
);
    wire signed [63:0] res = A - B;

    assign result = res;
    assign overflow = (~A[63] & B[63] & res[63]) | (A[63] & ~B[63] & ~res[63]);
endmodule

